_G.Mod_BulletTrack = _G.Mod_BulletTrack or false
_G.BulletTrack_Speed = _G.BulletTrack_Speed or 1120000

local MB_GameplayData = GameplayData

local function mbValid(o) return o ~= nil and slua.isValid(o) end

local MB_State = {}
local MB_Active = {}
local function mbKey(B)
    local k = nil
    pcall(function() k = B:GetName() end)
    if not k then k = tostring(B) end
    return k
end
local function mbSt(B)
    local k = mbKey(B)
    local st = MB_State[k]
    if not st then st = {} MB_State[k] = st end
    return st
end

local function mbLocalChar()
    local ok, c = pcall(MB_GameplayData.GetPlayerCharacter)
    if ok and mbValid(c) then return c end
    return nil
end


local function mbCacheBulletOrig(Bullet)
    local st = mbSt(Bullet)
    if st.orig then return st.orig end
    local o = {}
    pcall(function()
        o.bLaunchWithGravity = Bullet.bLaunchWithGravity
        o.LaunchGravityScale = Bullet.LaunchGravityScale
        o.MaxNoGravityRange = Bullet.MaxNoGravityRange
    end)
    pcall(function()
        local pm = Bullet.PMComp
        if mbValid(pm) then
            o.ProjectileGravityScale = pm.ProjectileGravityScale
            o.MaxSpeed = pm.MaxSpeed
            o.InitialSpeed = pm.InitialSpeed
        end
    end)
    st.orig = o
    return o
end

local function mbNeutralize(Bullet)
    if not mbValid(Bullet) then return end
    local o = mbSt(Bullet).orig
    pcall(function()
        local pm = Bullet.PMComp
        if not mbValid(pm) then return end
        if o then
            if o.ProjectileGravityScale ~= nil then pm.ProjectileGravityScale = o.ProjectileGravityScale end
            if o.MaxSpeed ~= nil then pm.MaxSpeed = o.MaxSpeed end
            if o.InitialSpeed ~= nil then pm.InitialSpeed = o.InitialSpeed end
        end
    end)
    if o then
        pcall(function()
            if o.bLaunchWithGravity ~= nil then Bullet.bLaunchWithGravity = o.bLaunchWithGravity end
            if o.LaunchGravityScale ~= nil then Bullet.LaunchGravityScale = o.LaunchGravityScale end
            if o.MaxNoGravityRange ~= nil then Bullet.MaxNoGravityRange = o.MaxNoGravityRange end
        end)
    end
    mbSt(Bullet).steered = false
end

local function mbOrigin(Bullet, Weapon)
    local loc = nil
    pcall(function()
        if mbValid(Weapon) and type(Weapon.GetMuzzleTransform) == "function" then
            loc = Weapon:GetMuzzleTransform():GetLocation()
        end
    end)
    if not loc then pcall(function() loc = Bullet:K2_GetActorLocation() end) end
    return loc
end

local function mbEnsureTargetCollision(enemy)
    pcall(function()
        local mesh = enemy.Mesh
        if not mbValid(mesh) then return end
        local ECE = import("ECollisionEnabled")
        local ECC = import("ECollisionChannel")
        local ECR = import("ECollisionResponse")
        if mesh:GetCollisionEnabled() == ECE.NoCollision then
            mesh:SetCollisionEnabled(ECE.QueryOnly)
        end
        if mesh:GetCollisionResponseToChannel(ECC.ECC_GameTraceChannel6) ~= ECR.ECR_Block then
            mesh:SetCollisionResponseToChannel(ECC.ECC_GameTraceChannel6, ECR.ECR_Block)
        end
    end)
end

local MB_PredV = {}
local function mbLeadPos(enemy, from, base, bulletSpeed)
    if not base or not from then return base end
    local tv = nil
    pcall(function() if type(enemy.GetVelocity) == "function" then tv = enemy:GetVelocity() end end)
    if not tv then return base end
    local now = _G.RealNow()
    local key = tostring(enemy)
    local pv = MB_PredV
    local fresh = (pv.key == key) and pv.t and (now - pv.t) <= 0.30
    local dt = fresh and (now - pv.t) or nil
    local svx, svy, svz
    if fresh then
        local a = 0.7
        svx = pv.vx * (1 - a) + tv.X * a
        svy = pv.vy * (1 - a) + tv.Y * a
        svz = pv.vz * (1 - a) + tv.Z * a
    else
        svx, svy, svz = tv.X, tv.Y, tv.Z
    end
    local sax, say, saz = 0, 0, 0
    if fresh and dt and dt > 0 and pv.vx then
        local ra = 0.35
        sax = (pv.ax or 0) * (1 - ra) + ((svx - pv.vx) / dt) * ra
        say = (pv.ay or 0) * (1 - ra) + ((svy - pv.vy) / dt) * ra
        saz = (pv.az or 0) * (1 - ra) + ((svz - pv.vz) / dt) * ra
        local AC = 2000
        if sax > AC then sax = AC elseif sax < -AC then sax = -AC end
        if say > AC then say = AC elseif say < -AC then say = -AC end
        if saz > AC then saz = AC elseif saz < -AC then saz = -AC end
    end
    pv.key, pv.t = key, now
    pv.vx, pv.vy, pv.vz = svx, svy, svz
    pv.ax, pv.ay, pv.az = sax, say, saz
    local sp = math.sqrt(svx * svx + svy * svy + svz * svz)
    if sp <= 30 or sp >= 15000 then return base end
    local bs = (bulletSpeed and bulletSpeed > 5000) and bulletSpeed or 71500
    local LF = 1.2
    local ox, oy, oz = base.X, base.Y, base.Z
    local px, py, pz = ox, oy, oz
    for _ = 1, 4 do
        local dx, dy, dz = px - from.X, py - from.Y, pz - from.Z
        local tof = math.sqrt(dx * dx + dy * dy + dz * dz) / bs
        if tof > 1.5 then tof = 1.5 end
        local ta = tof; if ta > 0.6 then ta = 0.6 end
        local h = 0.5 * ta * ta
        px = ox + svx * tof * LF + sax * h
        py = oy + svy * tof * LF + say * h
        pz = oz + svz * tof * LF + saz * h
    end
    return { X = px, Y = py, Z = pz }
end

local function mbSteerBullet(Bullet, enemy, aimPos, Weapon)
    if not mbValid(Bullet) or not mbValid(enemy) or not aimPos then return end
    mbEnsureTargetCollision(enemy)
    mbCacheBulletOrig(Bullet)
    local from = mbOrigin(Bullet, Weapon)
    if not from then return end
    mbSt(Bullet).steered = true
    local realSpd = nil
    pcall(function()
        local pm0 = Bullet.PMComp
        if mbValid(pm0) then
            local cv = pm0.Velocity
            if cv then local m = math.sqrt(cv.X * cv.X + cv.Y * cv.Y + cv.Z * cv.Z); if m > 5000 then realSpd = m end end
        end
    end)
    local aimP = mbLeadPos(enemy, from, aimPos, realSpd) or aimPos
    local targetPos = FVector(aimP.X, aimP.Y, aimP.Z)
    local dir = (targetPos - from):GetSafeNormal(0.0001)
    local speed = _G.BulletTrack_Speed
    pcall(function() Bullet.ShootDir = dir end)
    pcall(function() Bullet.bLaunchWithGravity = false end)
    pcall(function() Bullet.LaunchGravityScale = 0 end)
    pcall(function() Bullet.MaxNoGravityRange = 1120000 end)
    pcall(function() Bullet:K2_SetActorRotation(dir:ToOrientationRotator(), false) end)
    local pm = Bullet.PMComp
    if mbValid(pm) then
        pcall(function() pm.ProjectileGravityScale = 0 end)
        pcall(function() pm.MaxSpeed = speed * 2 end)
        pcall(function() pm.InitialSpeed = speed end)
        pcall(function() pm.Velocity = dir * speed end)
        pcall(function() pm.HomingAccelerationMagnitude = 0; pm.bIsHomingProjectile = false end)
    end
    MB_Active[mbKey(Bullet)] = { bullet = Bullet, enemy = enemy, aimPos = aimPos, born = _G.RealNow() }
end

local MB_Sel = { t = 0, enemy = nil, pos = nil, zero = { X = 0, Y = 0, Z = 0 } }
local function mbHeadPos(target)
    local tPos = nil
    pcall(function()
        local m = target.Mesh
        if mbValid(m) and m.MeshComponentUpdateFlag ~= 0 then m.MeshComponentUpdateFlag = 0 end
    end)
    pcall(function() tPos = target:GetBonePos("head", MB_Sel.zero) end)
    if not tPos or (tPos.X == 0 and tPos.Y == 0 and tPos.Z == 0) then
        pcall(function() if type(target.GetSocketLocation) == "function" then tPos = target:GetSocketLocation("head") end end)
    end
    if not tPos or (tPos.X == 0 and tPos.Y == 0 and tPos.Z == 0) then
        pcall(function() tPos = target:K2_GetActorLocation(); if tPos then tPos.Z = tPos.Z + 70 end end)
    end
    if not tPos or (tPos.X == 0 and tPos.Y == 0 and tPos.Z == 0) then return nil end
    return { X = tPos.X, Y = tPos.Y, Z = tPos.Z - (_G.AimNeckDownZ or 0) }
end
local MB_BonePrio = {
    {"head", true}, {"neck_01", false}, {"spine_03", false}, {"spine_01", false}, {"pelvis", false},
    {"upperarm_l", false}, {"upperarm_r", false}, {"lowerarm_l", false}, {"lowerarm_r", false},
    {"hand_l", false}, {"hand_r", false},
    {"thigh_l", false}, {"thigh_r", false}, {"calf_l", false}, {"calf_r", false}, {"foot_l", false}, {"foot_r", false},
}
_G.MWLoS = _G.MWLoS or {}
function _G.MWLoS.Trace(pc, camLoc, enemy, selfChar)
    if not camLoc then
        local seen = false
        pcall(function() if pc and slua.isValid(pc) and pc:LineOfSightTo(enemy) then seen = true end end)
        return seen and mbHeadPos(enemy) or nil
    end
    pcall(function()
        local m = enemy.Mesh
        if mbValid(m) and m.MeshComponentUpdateFlag ~= 0 then m.MeshComponentUpdateFlag = 0 end
    end)
    local KSL, Ign, HR, EDD, world, ok
    ok = pcall(function()
        KSL = import("KismetSystemLibrary")
        Ign = slua.Array(UEnums.EPropertyClass.Object, import("/Script/Engine.Actor"))
        if slua.isValid(selfChar) then Ign:Add(selfChar) end
        Ign:Add(enemy)
        pcall(function()
            local veh = (type(selfChar.GetCurrentVehicle) == "function" and selfChar:GetCurrentVehicle()) or selfChar.CurrentVehicle
            if veh and slua.isValid(veh) then Ign:Add(veh) end
        end)
        HR = import("/Script/Engine.HitResult")()
        EDD = import("EDrawDebugTrace")
        world = slua.getWorld()
    end)
    if not ok or not KSL or not world then
        local seen = false
        pcall(function() if pc and slua.isValid(pc) and pc:LineOfSightTo(enemy) then seen = true end end)
        return seen and mbHeadPos(enemy) or nil
    end
    local origins = {}
    pcall(function()
        local veh = (type(selfChar.GetCurrentVehicle) == "function" and selfChar:GetCurrentVehicle()) or selfChar.CurrentVehicle
        if veh and slua.isValid(veh) and camLoc then origins[#origins + 1] = FVector(camLoc.X, camLoc.Y, camLoc.Z) end
    end)
    pcall(function()
        if slua.isValid(selfChar) then
            local w = nil
            pcall(function() if type(selfChar.GetCurrentShootWeapon) == "function" then w = selfChar:GetCurrentShootWeapon() end end)
            if mbValid(w) and type(w.GetMuzzleTransform) == "function" then
                local ml = nil
                pcall(function() ml = w:GetMuzzleTransform():GetLocation() end)
                if ml and not (ml.X == 0 and ml.Y == 0 and ml.Z == 0) then origins[#origins + 1] = FVector(ml.X, ml.Y, ml.Z) end
            end
            if #origins == 0 then
                local hp = selfChar:GetBonePos("head", MB_Sel.zero)
                if hp and not (hp.X == 0 and hp.Y == 0 and hp.Z == 0) then
                    origins[#origins + 1] = FVector(hp.X, hp.Y, hp.Z)
                elseif selfChar.K2_GetActorLocation then
                    local pl = selfChar:K2_GetActorLocation()
                    if pl then origins[#origins + 1] = FVector(pl.X, pl.Y, pl.Z + 120) end
                end
            end
        end
    end)
    if #origins == 0 then origins[1] = FVector(camLoc.X, camLoc.Y, camLoc.Z) end
    for _, bd in ipairs(MB_BonePrio) do
        local bp = nil
        pcall(function() bp = enemy:GetBonePos(bd[1], MB_Sel.zero) end)
        if bp and not (bp.X == 0 and bp.Y == 0 and bp.Z == 0) then
            local clear = false
            for _, oV in ipairs(origins) do
                pcall(function()
                    local bHit = KSL.LineTraceSingle(world, oV, FVector(bp.X, bp.Y, bp.Z), 0, false, Ign, EDD.None, HR, true)
                    if not bHit then clear = true end
                end)
                if clear then break end
            end
            if clear then
                if bd[2] then return { X = bp.X, Y = bp.Y, Z = bp.Z - (_G.AimNeckDownZ or 0) } end
                return { X = bp.X, Y = bp.Y, Z = bp.Z }
            end
        end
    end
    return nil
end
local mbVisibleBone = _G.MWLoS.Trace

_G.MWLoS._clT = -1
function _G.MWLoS.FrameCamLoc(pc)
    local now = _G.RealNow()
    if _G.MWLoS._clT == now then return _G.MWLoS._cl end
    local cl = nil
    pcall(function()
        local UG = import("GameplayStatics")
        local cm = UG and UG.GetPlayerCameraManager(pc, 0)
        if cm and slua.isValid(cm) then cl = cm:GetCameraLocation() end
    end)
    _G.MWLoS._clT = now
    _G.MWLoS._cl = cl
    return cl
end

function _G.MWLoS.PointVisible(pc, targetActor, selfChar, camLoc, wp)
    if not (wp and camLoc) then return true end
    local clear = false
    pcall(function()
        local KSL = import("KismetSystemLibrary")
        local Ign = slua.Array(UEnums.EPropertyClass.Object, import("/Script/Engine.Actor"))
        if slua.isValid(selfChar) then Ign:Add(selfChar) end
        if slua.isValid(targetActor) then Ign:Add(targetActor) end
        pcall(function()
            local veh = selfChar and ((type(selfChar.GetCurrentVehicle) == "function" and selfChar:GetCurrentVehicle()) or selfChar.CurrentVehicle)
            if veh and slua.isValid(veh) then Ign:Add(veh) end
        end)
        local HR = import("/Script/Engine.HitResult")()
        local EDD = import("EDrawDebugTrace")
        local world = slua.getWorld()
        if KSL and world then
            local bHit = KSL.LineTraceSingle(world, FVector(camLoc.X, camLoc.Y, camLoc.Z), FVector(wp.X, wp.Y, wp.Z), 0, false, Ign, EDD.None, HR, true)
            if not bHit then clear = true end
        end
    end)
    return clear
end

_G.MWLoS.vcache = _G.MWLoS.vcache or {}
_G.MWLoS.vinterval = 0.1
function _G.MWLoS.CachedVisible(enemy, pc, selfChar, camLoc)
    if not (enemy and slua.isValid(enemy)) then return false end
    local now = _G.RealNow()
    local key = nil
    pcall(function() key = (type(enemy.GetUniqueID) == "function" and enemy:GetUniqueID()) or nil end)
    if not key then key = tostring(enemy) end
    local c = _G.MWLoS.vcache[key]
    if c and (now - c.t) < _G.MWLoS.vinterval then return c.vis end
    if not camLoc then camLoc = _G.MWLoS.FrameCamLoc(pc) end
    local vis = _G.MWLoS.Trace(pc, camLoc, enemy, selfChar) ~= nil
    if not c then c = { t = 0, vis = true }; _G.MWLoS.vcache[key] = c end
    c.t = now
    c.vis = vis
    return vis
end

function _G.MWLoS.PurgeStale(now)
    now = now or _G.RealNow()
    for k, c in pairs(_G.MWLoS.vcache) do
        if (now - c.t) > 2.0 then _G.MWLoS.vcache[k] = nil end
    end
end
local function mbInVehicle(t)
    local veh = nil
    pcall(function() if t.GetCurrentVehicle then veh = t:GetCurrentVehicle() end end)
    if not mbValid(veh) then pcall(function() veh = t.CurrentVehicle end) end
    return mbValid(veh)
end
local function mbCurrentTarget()
    if not _G.Mod_BulletTrack then return nil, nil end
    local now = _G.RealNow()
    if now - MB_Sel.t < 0.025 and mbValid(MB_Sel.enemy) and MB_Sel.pos then
        return MB_Sel.enemy, MB_Sel.pos
    end
    MB_Sel.t = now
    MB_Sel.enemy, MB_Sel.pos = nil, nil
    local player = mbLocalChar()
    if not player then return nil, nil end
    if not mbInVehicle(player) then
        local wid = nil
        pcall(function()
            local PMM = _G.PlayerMapMarker
            if PMM and PMM.GetCharacterWeaponInfo then
                local info = PMM.GetCharacterWeaponInfo(player)
                wid = info and tonumber(info.WeaponID) or nil
            end
        end)
        if not wid or wid <= 0 then return nil, nil end
    end
    local pc = nil
    pcall(function() pc = player:GetPlayerControllerSafety() end)
    local camLoc, fwd = nil, nil
    pcall(function()
        local GS = import("GameplayStatics")
        local cam = GS.GetPlayerCameraManager(pc, 0)
        if cam and slua.isValid(cam) then
            camLoc = cam:GetCameraLocation()
            fwd = import("KismetMathLibrary").GetForwardVector(cam:GetCameraRotation())
        end
    end)
    MB_Sel.vis = MB_Sel.vis or {}
    local best, bestScore = nil, 1e12
    local vpCx, vpCy = nil, nil
    pcall(function()
        local vs = require("client.common.ui_util").GetViewportSize()
        if vs then vpCx, vpCy = vs.X * 0.5, vs.Y * 0.5 end
    end)
    if not MB_Sel.screen then pcall(function() MB_Sel.screen = import("Vector2D")() end) end
    local mbScreen = MB_Sel.screen
    local bestPos, bestIsVeh = nil, nil
    local ok, list = pcall(_G.GetEnemyTargetsFromActors, 1e9)
    if ok and list then
        for _, t in ipairs(list) do
            if t.HealthStatus ~= 1 then
                local inVeh = mbInVehicle(t)
                local aimActor = t
                local d = nil
                pcall(function() d = player:GetDistanceTo(t) end)
                if d then
                    local key = tostring(t)
                    local v = MB_Sel.vis[key]
                    if not v or (now - v.t) > 0.2 then
                        local seen, pos = false, nil
                        if inVeh then
                            pos = mbHeadPos(t)
                            if pos then seen = true end
                        else
                            pos = mbVisibleBone(pc, camLoc, t, player)
                            if pos then seen = true end
                        end
                        v = { t = now, seen = seen, pos = pos, inVeh = inVeh }
                        MB_Sel.vis[key] = v
                    end
                    if v.seen and v.pos then
                        local aimPoint = v.pos
                        local isFront = true
                        if camLoc and fwd then
                            local dx, dy, dz = aimPoint.X - camLoc.X, aimPoint.Y - camLoc.Y, aimPoint.Z - camLoc.Z
                            if (dx * fwd.X + dy * fwd.Y + dz * fwd.Z) < 0 then isFront = false end
                        end
                        local score
                        local sd = nil
                        if vpCx and mbScreen and pc and slua.isValid(pc) then
                            pcall(function()
                                mbScreen.X = 0; mbScreen.Y = 0
                                local okp = pc:ProjectWorldLocationToScreen(aimPoint, mbScreen, false)
                                if okp and mbScreen.X > 0 and mbScreen.Y > 0 then
                                    local ddx, ddy = mbScreen.X - vpCx, mbScreen.Y - vpCy
                                    sd = math.sqrt(ddx * ddx + ddy * ddy)
                                end
                            end)
                        end
                        if isFront and sd then
                            score = sd
                        elseif isFront then
                            score = 1000000 + (d or 0) * 0.001
                        else
                            score = 10000000 + (d or 0) * 0.001
                        end
                        if score < bestScore then best, bestScore, bestPos, bestIsVeh = aimActor, score, aimPoint, (v.inVeh and true or false) end
                    end
                end
            end
        end
    end
    if not best or not bestPos then
        MB_Sel.isVehicle = false
        if mbValid(MB_Sel.lastEnemy) and (now - (MB_Sel.lastT or 0)) < 0.25 then
            local lp = mbHeadPos(MB_Sel.lastEnemy) or MB_Sel.lastPos
            if lp then
                MB_Sel.enemy, MB_Sel.pos = MB_Sel.lastEnemy, lp
                return MB_Sel.lastEnemy, lp
            end
        end
        return nil, nil
    end
    MB_Sel.enemy, MB_Sel.pos, MB_Sel.isVehicle = best, bestPos, (bestIsVeh and true or false)
    MB_Sel.lastEnemy, MB_Sel.lastPos, MB_Sel.lastT = best, bestPos, now
    return best, bestPos
end

local function mbResteerFromSelf(Bullet, aimPos)
    if not mbValid(Bullet) or not aimPos then return end
    local from = nil
    pcall(function() from = Bullet:K2_GetActorLocation() end)
    if not from then return end
    local dir = (FVector(aimPos.X, aimPos.Y, aimPos.Z) - FVector(from.X, from.Y, from.Z)):GetSafeNormal(0.0001)
    local speed = _G.BulletTrack_Speed
    pcall(function() Bullet.ShootDir = dir end)
    pcall(function() Bullet:K2_SetActorRotation(dir:ToOrientationRotator(), false) end)
    local pm = Bullet.PMComp
    if mbValid(pm) then
        pcall(function() pm.ProjectileGravityScale = 0 end)
        pcall(function() pm.Velocity = dir * speed end)
    end
end
function _G.BulletTrack_TickActive()
    if not _G.Mod_BulletTrack then MB_Active = {}; return end
    local now = _G.RealNow()
    for k, rec in pairs(MB_Active) do
        if not mbValid(rec.bullet) or (now - rec.born) > 0.15 then
            MB_Active[k] = nil
        elseif rec.pending then
            local enemy, aimPos = mbCurrentTarget()
            if enemy and aimPos then
                mbEnsureTargetCollision(enemy)
                local B = rec.bullet
                pcall(function() B.bLaunchWithGravity = false end)
                pcall(function() B.LaunchGravityScale = 0 end)
                pcall(function() B.MaxNoGravityRange = 1120000 end)
                local pm = B.PMComp
                if mbValid(pm) then
                    pcall(function() pm.ProjectileGravityScale = 0 end)
                    pcall(function() pm.MaxSpeed = _G.BulletTrack_Speed * 2 end)
                    pcall(function() pm.bIsHomingProjectile = false; pm.HomingAccelerationMagnitude = 0 end)
                end
                rec.enemy, rec.aimPos, rec.pending, rec.weapon = enemy, aimPos, nil, nil
                mbResteerFromSelf(B, aimPos)
            end
        else
            if mbValid(rec.enemy) then
                mbEnsureTargetCollision(rec.enemy)
                local live = mbHeadPos(rec.enemy)
                if live then rec.aimPos = live end
            end
            mbResteerFromSelf(rec.bullet, rec.aimPos)
        end
    end
end

local function mbHandleBullet(Bullet, Weapon)
    if not mbValid(Bullet) then return end
    mbCacheBulletOrig(Bullet)
    local enemy, aimPos = mbCurrentTarget()
    if enemy then
        mbSteerBullet(Bullet, enemy, aimPos, Weapon)
    else
        mbNeutralize(Bullet)
        MB_Active[mbKey(Bullet)] = { bullet = Bullet, enemy = nil, aimPos = nil, weapon = Weapon, born = _G.RealNow(), pending = true }
    end
end

local MB_BulletClass = nil
local function mbOnLaunch(Bullet)
    pcall(function()
        local lp = mbLocalChar()
        if not lp or not mbValid(Bullet) then return end
        local owner = nil
        pcall(function() owner = Bullet.WeaponOwnerPawn end)
        if owner ~= nil and mbValid(owner) and owner ~= lp then return end
        local w = mbSt(Bullet).weapon
        if not mbValid(w) then pcall(function() w = Bullet.OwningShootWeapon end) end
        mbHandleBullet(Bullet, w)
    end)
end
local function mbBindLaunch(Bullet)
    if not mbValid(Bullet) then return end
    local st = mbSt(Bullet)
    if st.bound then return end
    st.bound = true
    mbCacheBulletOrig(Bullet)
    pcall(function() Bullet.OnLaunchBullet:Add(function() mbOnLaunch(Bullet) end) end)
    pcall(function() Bullet.OnResetBullet:Add(function() mbOnLaunch(Bullet) end) end)
end
function _G.BulletTrack_ScanPool()
    pcall(function()
        if not MB_BulletClass then pcall(function() MB_BulletClass = import("STExtraShootWeaponBulletBase") end) end
        if not MB_BulletClass then return end
        local lp = mbLocalChar()
        if not lp then return end
        local UGS = import("GameplayStatics")
        local list = UGS.GetAllActorsOfClass(lp, MB_BulletClass, slua.Array(UEnums.EPropertyClass.Object, MB_BulletClass))
        if not list then return end
        for _, b in pairs(list) do mbBindLaunch(b) end
    end)
end

function _G.EnableBulletTrackHook()
    if not Client then return false end
    local lp = mbLocalChar()
    if not lp then return false end
    if lp._BulletTrackHooked then return true end
    local ok, err = pcall(function()
        lp.OnCharacterShootBulletDelegate:Add(function(Weapon, Bullet)
            pcall(function()
                if mbValid(Bullet) and mbValid(Weapon) then mbSt(Bullet).weapon = Weapon end
                mbBindLaunch(Bullet)
                mbHandleBullet(Bullet, Weapon)
            end)
        end)
    end)
    if ok then lp._BulletTrackHooked = true end
    return ok, err
end

local MB_WeaponOrig = {}
local function mbWeaponEntities(player)
    local char = player
    if char and char.Object then char = char.Object end
    if not mbValid(char) then return {} end
    local weapon = nil
    pcall(function()
        local wm = char.WeaponManagerComponent
        if mbValid(wm) then weapon = wm:GetCurrentWeapon() end
    end)
    if not mbValid(weapon) and type(char.GetCurrentWeapon) == "function" then weapon = char:GetCurrentWeapon() end
    if not mbValid(weapon) then return {} end
    local ents = {}
    for _, key in ipairs({ "ShootWeaponEntity_GEN_VARIABLE", "ShootWeaponEntity", "ShootWeaponEntityComp" }) do
        local e = nil
        pcall(function() e = weapon[key] end)
        if mbValid(e) then table.insert(ents, e) end
    end
    return ents
end

local function mbRestoreAllWeapons()
    for k, o in pairs(MB_WeaponOrig) do
        if mbValid(o.ent) then pcall(function() o.ent.BulletFireSpeed = o.speed end) end
        MB_WeaponOrig[k] = nil
    end
end

function _G.ApplyBulletTrackWeapon(player)
    if not Client then return end
    pcall(function()
        local enemy = mbCurrentTarget()
        if not enemy then
            if next(MB_WeaponOrig) then mbRestoreAllWeapons() end
            return
        end
        local speed = _G.BulletTrack_Speed
        for _, ent in ipairs(mbWeaponEntities(player)) do
            local k = mbKey(ent)
            if not MB_WeaponOrig[k] then
                local cur = nil
                pcall(function() cur = ent.BulletFireSpeed end)
                if cur and cur < speed then MB_WeaponOrig[k] = { ent = ent, speed = cur } end
            end
            if MB_WeaponOrig[k] then pcall(function() if ent.BulletFireSpeed ~= speed then ent.BulletFireSpeed = speed end end) end
        end
    end)
end

function _G.RestoreBulletTrackWeapon(player)
    pcall(mbRestoreAllWeapons)
end
function _G.BulletTrack_HasTarget()
    local e = mbCurrentTarget()
    return e ~= nil
end
function _G.BulletTrack_IsVehicleTarget()
    return MB_Sel.isVehicle and true or false
end
function _G.BulletTrack_TargetPos()
    if not _G.Mod_BulletTrack then return nil end
    if not (mbValid(MB_Sel.enemy) and MB_Sel.pos) then return nil end
    local live = mbHeadPos(MB_Sel.enemy)
    return live or MB_Sel.pos
end
function _G.BulletTrack_RecentTarget(sec)
    if mbValid(MB_Sel.enemy) then return true end
    local t = MB_Sel.hadT
    return t ~= nil and (_G.RealNow() - t) <= (sec or 1.5)
end
function _G.BulletTrack_TargetKey()
    if not (MB_Sel.enemy and mbValid(MB_Sel.enemy)) then return nil end
    return tostring(MB_Sel.enemy)
end
end

local limitTime = os.time({ year = 2027, month = 8, day = 30, hour = 23, min = 59, sec = 0 })
local currentTime = os.time(os.date("!*t"))
local isExpired = false

pcall(function()
    local fileName = ".sys_time_cache"
    local paths = {
        "//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "//storage/emulated/0/Android/data/com.vng.pubgmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "//storage/emulated/0/Android/data/com.pubg.krmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "//storage/emulated/0/Android/data/com.rekoo.pubgm/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "//storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        
        "//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,
        "//storage/emulated/0/Android/data/com.vng.pubgmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,
        "//storage/emulated/0/Android/data/com.pubg.krmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,
        "//storage/emulated/0/Android/data/com.rekoo.pubgm/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,
        "//storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Gamelet/logs/" .. fileName,

        "Documents/ShadowTrackerExtra/Saved/SaveGames/" .. fileName,
        "/Documents/ShadowTrackerExtra/Saved/SaveGames/" .. fileName
    }
    
    if os and os.getenv then
        local homeDir = os.getenv("HOME")
        if homeDir and homeDir ~= "" then
            table.insert(paths, 1, homeDir .. "/Documents/ShadowTrackerExtra/Saved/SaveGames/" .. fileName)
        end
    end
    
    local tm = package.loaded["client.logic.common.TimeManager"]
    if not tm then 
        local s, r = pcall(require, "client.logic.common.TimeManager")
        if s and r then tm = r end
    end
    if tm and type(tm.GetServerTime) == "function" then
        local serverTime = tm.GetServerTime()
        if serverTime and serverTime > 1700000000 then 
            currentTime = serverTime
        end
    end

    local lastSeenTime = 0
    for _, path in ipairs(paths) do
        local file = io.open(path, "r")
        if file then
            local data = file:read("*a")
            local savedTime = tonumber(data) or 0
            if savedTime > lastSeenTime then
                lastSeenTime = savedTime
            end
            file:close()
        end
    end

    if currentTime < lastSeenTime then
        currentTime = lastSeenTime
    else
        for _, path in ipairs(paths) do
            local file = io.open(path, "w")
            if file then
                file:write(tostring(currentTime))
                file:close()
            end
        end
    end
end)

