        notify_kick_out_game              = "always",
        kickout_simulator_user_notify     = "always",
        get_emulators_cfg_res             = "always",
    }
    B.BLOCK_SEND = {
        report_simulator_check                   = true,
        get_emulators_cfg_req                    = true,
        cheat_warn_reply                         = true,
        report_general_illegal_click_req         = true,
        get_ban_id_req                           = true,
        accept_credit_pact                       = true,
        credit_punish_return_lobby_user_reaction = true,
