        query_patroller_privilege_level_req      = true,
        query_patroller_stat_info_req            = true,
        set_patrol_broadcast_setting_req         = true,
        kickout_simulator_user_req               = true,
    }
    function B.installNetHook()
        pcall(function()
            local NM = package.loaded and package.loaded["client.network.comm.NetManager"]
            if not NM then NM = require("client.network.comm.NetManager") end
            if not NM or NM._MWBlockHooked then return end
            local orig = NM.OnRecvPkg
            if type(orig) ~= "function" then return end
            local BLOCK = B.BLOCK
            NM.OnRecvPkg = function(id, ...)
                local mode
                pcall(function()
                    local info = NM.FindMsgInfo and NM.FindMsgInfo(id)
                    local name = info and (info.res or info.handler)
                    if name then mode = BLOCK[name] end
                end)
                if mode then
                    local drop = false
                    if mode == "always" then
                        drop = true
                    elseif mode == "ban_flag" then
                        local a2 = select(2, ...)
                        drop = (a2 == true)
                    elseif mode == "ban_reason" then
                        local a1 = select(1, ...)
                        if type(a1) == "string" then local rl = string.lower(a1); drop = (rl:find("ban", 1, true) or rl:find("cheat", 1, true)) and true or false end
                    end
                    if drop then return end
                end
                return orig(id, ...)
            end
            pcall(function()
                local origSend = NM.SendPkg
                if type(origSend) == "function" and not NM._MWSendHooked then
                    local BLOCK_SEND = B.BLOCK_SEND
                    NM.SendPkg = function(sid, ...)
                        local drop = false
                        pcall(function()
                            local info = NM.FindMsgInfo and NM.FindMsgInfo(sid)
                            local rq = info and info.req
                            if rq and BLOCK_SEND[rq] then drop = true end
                        end)
                        if drop then return end
                        return origSend(sid, ...)
                    end
                    NM._MWSendHooked = true
                end
            end)
            NM._MWBlockHooked = true
        end)
    end
end

