local ConfigFileName = "save.dat"
_G.MWSaveSys = { VERSION = 2, MAGIC = "LXSV", unpack = table.unpack or unpack }
_G.MWSaveSys.KEY = { 76, 101, 120, 117, 115, 77, 87, 33, 55, 145, 163, 94, 12, 107, 210, 31, 88, 201, 5, 66, 139, 250, 42, 173 }
_G.LastConfigSaveStr = ""
_G.MWSaveOutfit = _G.MWSaveOutfit

function _G.MWSaveSys.Codec(str, enc)
    local LS = _G.MWSaveSys
    local n, kn = #str, #LS.KEY
    local out, chunk, ci = {}, {}, 0
    for i = 1, n do
        local b = string.byte(str, i)
        local k = (LS.KEY[(i - 1) % kn + 1] + i * 7) % 256
        if enc then b = (b + k) % 256 else b = (b - k) % 256 end
        ci = ci + 1
        chunk[ci] = b
        if ci == 200 then
            out[#out + 1] = string.char(LS.unpack(chunk, 1, ci))
            ci = 0
        end
    end
    if ci > 0 then out[#out + 1] = string.char(LS.unpack(chunk, 1, ci)) end
    return table.concat(out)
end

function _G.MWSaveSys.SortedKeys(t)
    local keys = {}
    for k in pairs(t) do keys[#keys + 1] = tostring(k) end
    table.sort(keys)
    return keys
end

function _G.MWSaveSys.ValueText(v)
    local tv = type(v)
    if tv == "string" then return string.format("%q", v) end
    if tv == "boolean" or tv == "number" then return tostring(v) end
    return nil
end

_G.SaveModSettings = function()
    pcall(function()
        local LS = _G.MWSaveSys
        local parts = { "return {\nV = " .. LS.VERSION .. ",\nMWConfig = {\n" }
        local cfg = _G.MWConfig or {}
        for _, k in ipairs(LS.SortedKeys(cfg)) do
            local vt = LS.ValueText(cfg[k])
            if vt then parts[#parts + 1] = "  [\"" .. k .. "\"] = " .. vt .. ",\n" end
        end
        parts[#parts + 1] = "},\nCustomTextData = {\n"
        local ctd = _G.MWState and _G.MWState.CustomTextData
        if ctd then
            for _, k in ipairs(LS.SortedKeys(ctd)) do
                local vt = LS.ValueText(ctd[k])
                if vt then parts[#parts + 1] = "  [\"" .. k .. "\"] = " .. vt .. ",\n" end
            end
        end
        parts[#parts + 1] = "},\nOutfit = " .. (type(_G.MWSaveOutfit) == "string" and string.format("%q", _G.MWSaveOutfit) or "nil") .. ",\n}"
        local data = table.concat(parts)

        if data == _G.LastConfigSaveStr then return end
        _G.LastConfigSaveStr = data

        local blob = LS.Codec(LS.MAGIC .. data, true)
        for _, path in ipairs(GetConfigPaths(ConfigFileName)) do
            local file = io.open(path, "wb")
            if file then
                file:write(blob)
                file:close()
                break
            end
        end
    end)
end

_G.LoadModSettings = function()
    pcall(function()
        local LS = _G.MWSaveSys
        for _, p in ipairs(GetConfigPaths("settings.txt")) do pcall(os.remove, p) end

        local blob = nil
        for _, path in ipairs(GetConfigPaths(ConfigFileName)) do
            local file = io.open(path, "rb")
            if file then
                blob = file:read("*a")
                file:close()
                break
            end
        end

        local saved = nil
        if blob and #blob > #LS.MAGIC then
            local txt = LS.Codec(blob, false)
            if txt:sub(1, #LS.MAGIC) == LS.MAGIC then
                local fn = load(txt:sub(#LS.MAGIC + 1))
                if fn then
                    local ok, t = pcall(fn)
                    if ok and type(t) == "table" and t.V == LS.VERSION then saved = t end
                end
            end
        end

        local defs = _G.MWDefaultTextData()
        _G.MWState.CustomTextData = _G.MWState.CustomTextData or {}
        local ctd = _G.MWState.CustomTextData
        for k, v in pairs(defs) do if ctd[k] == nil then ctd[k] = v end end

        if saved then
            local extraCfg = { LessRecoil = true, VerticalRecoil = true }
            if type(saved.MWConfig) == "table" then
                for k, v in pairs(saved.MWConfig) do
                    if _G.MWConfig[k] ~= nil or extraCfg[k] then _G.MWConfig[k] = v end
                end
            end
            if type(saved.CustomTextData) == "table" then
                for k, v in pairs(saved.CustomTextData) do
                    if defs[k] ~= nil then ctd[k] = v end
                end
            end
            if type(saved.Outfit) == "string" and #saved.Outfit > 0 then _G.MWSaveOutfit = saved.Outfit end
        end
        _G.MWLang = "EN"
        _G.SaveModSettings()
    end)
end

_G.MWResetSettings = function()
    pcall(function()
        local defs = _G.MWDefaultConfig()
        for k, v in pairs(defs) do _G.MWConfig[k] = v end
        _G.MWConfig.LessRecoil = nil
        _G.MWConfig.VerticalRecoil = nil
        _G.MWState.CustomTextData = _G.MWState.CustomTextData or {}
        local ctd = _G.MWState.CustomTextData
        for k in pairs(ctd) do ctd[k] = nil end
        for k, v in pairs(_G.MWDefaultTextData()) do ctd[k] = v end
        for _, R in pairs(_G.MWMenuRows or {}) do
            pcall(function()
                if R.GetFunc and R.SetFunc then
                    local v = R.GetFunc()
                    if v ~= nil then R.SetFunc(nil, v) end
                end
            end)
        end
        _G.MWLang = "EN"
        _G.SaveModSettings()
    end)
end

local function AutoSaveLoop()
    pcall(function() if _G.SaveModSettings then _G.SaveModSettings() end end)
    pcall(function()
        local okTicker, ticker = pcall(require, "common.time_ticker") 
        if okTicker and ticker and ticker.AddTimerOnce then 
            ticker.AddTimerOnce(3.0, AutoSaveLoop)
        end
    end)
end

if not _G.ModConfigLoaded then
    _G.LoadModSettings()
    AutoSaveLoop()
    _G.ModConfigLoaded = true
end

_G.ReadLiveConfig = function()
    if _G.SaveModSettings then _G.SaveModSettings() end
end


