function _G.InitModMenuTab()
    if _G.ModMenuInitialized then return end
    _G.ModMenuInitialized = true

    _G.MWState.CustomTextData = _G.MWState.CustomTextData or _G.MWDefaultTextData()

    local LocUtil = _G.LocUtil
    if not LocUtil and package.loaded["client.common.LocUtil"] then
        LocUtil = require("client.common.LocUtil")
    end
    
    _G.RebuildMWTextMap()
    local FakeTextMap = _G._FakeTextMap

    if LocUtil and not LocUtil._IsModMenuHooked_V2 then
        local hookFuncs = {"GetLocalizeResStr", "GetText", "GetTextByID", "GetLocalText", "GetLocalizeStr"}
        for _, funcName in ipairs(hookFuncs) do
            if LocUtil[funcName] then
                local old_func = LocUtil[funcName]
                LocUtil[funcName] = function(id)
                    if _G._FakeTextMap and _G._FakeTextMap[id] then
                        return _G._FakeTextMap[id]
                    end
                    if type(id) == "string" and not tonumber(id) then
                        return id
                    end
                    if old_func then
                        return old_func(id)
                    end
                    return ""
                end
            end
        end
        LocUtil._IsModMenuHooked_V2 = true
    end

    
    if not _G._ModMenuDef then
        local AliasMap = require("client.slua.umg.NewSetting.Item.AliasMap")
        local _SpUI = AliasMap.Spacer or { moduleName = "client.slua.umg.NewSetting.Item.Setting_Spacer", path = "/Game/UMG/UI_BP/Setting25/Item/WBP_Setting_Spacer.WBP_Setting_Spacer", isSingleton = false, keyName = "Setting_Spacer", showVisibility = "DontCare" }

