            if type(k) == "string" and string.find(k, "ScreenMarkConfig") and type(cfg) == "table" then 
                ApplyCfg(cfg) 
            end 
        end 
    end)
    _G.MWState.NativeESPReady = true 
    Notify("Native ESP System Initialized") 
end

local function GetAllSkeletalMeshes(enemy, markData)
    local curTime = _G.RealNow()
    if markData and markData.CachedMeshes and markData.CachedMeshTime and (curTime - markData.CachedMeshTime < 3.0) then
        local validMeshes = {}
        for _, cachedMesh in ipairs(markData.CachedMeshes) do
            if Valid(cachedMesh) then table.insert(validMeshes, cachedMesh) end
        end
        markData.CachedMeshes = validMeshes
        return validMeshes
    end

    local meshes = {}
    if Valid(enemy.Mesh) then table.insert(meshes, enemy.Mesh) end
    pcall(function()
        local SkeletalMeshClass = import("SkeletalMeshComponent")
        if SkeletalMeshClass and type(enemy.GetComponentsByClass) == "function" then
            local childs = enemy:GetComponentsByClass(SkeletalMeshClass)
            if childs then
                local count = type(childs.Num) == "function" and childs:Num() or #childs
                for i = 1, count do
                    local comp = type(childs.Get) == "function" and childs:Get(i-1) or childs[i]
                    if Valid(comp) and comp ~= enemy.Mesh then
                        table.insert(meshes, comp)
                    end
                end
            end
        end
    end)
    if markData then
        markData.CachedMeshes = meshes
        markData.CachedMeshTime = curTime
    end
    return meshes
end


local function ApplyColorBodyNew(enemy, markData)
    pcall(function()
        if not _G.ConsoleNewWallReady then
            local KismetSystemLibrary = import("KismetSystemLibrary")
            local world = slua.getWorld()
            if KismetSystemLibrary and world then
                KismetSystemLibrary.ExecuteConsoleCommand(world, "r.EnableDrawDyeingColor 1")
                KismetSystemLibrary.ExecuteConsoleCommand(world, "r.CustomDepth 3")
                KismetSystemLibrary.ExecuteConsoleCommand(world, "r.IdeaOutline.Enable 1")
                KismetSystemLibrary.ExecuteConsoleCommand(world, "r.Highlight.Enable 1")
                _G.ConsoleNewWallReady = true
            end
        end

        local meshes = GetAllSkeletalMeshes(enemy, markData)

        local weapon = nil
        pcall(function() weapon = enemy:GetCurrentWeapon() end)
        if slua.isValid(weapon) and slua.isValid(weapon.Mesh) then
            table.insert(meshes, weapon.Mesh)
        end

        local isBot = markData.AK_IS_BOT or false
        local currentMeshCount = #meshes

        local stateHash = (isBot and "BOT" or "PLAYER") .. "_" .. tostring(currentMeshCount)

        if markData.LastColorNewHash == stateHash and markData.ColorNewApplied then
            return
        end

        markData.LastColorNewHash = stateHash
        markData.ColorNewApplied = true

        local LinearColorClass = import("LinearColor") or _G.FLinearColor
        local c_vis = LinearColorClass and LinearColorClass(0, 100, 0, 1) or {R=0, G=100, B=0, A=1}
        local c_occ = LinearColorClass and LinearColorClass(100, 0, 0, 1) or {R=100, G=0, B=0, A=1}
        local c_bVis = LinearColorClass and LinearColorClass(5, 4, 0, 100) or {R=5, G=4, B=0, A=100}
        local c_bOcc = LinearColorClass and LinearColorClass(100, 0, 0, 100) or {R=100, G=0, B=0, A=100}

        local visColor = isBot and c_bVis or c_vis
        local occColor = isBot and c_bOcc or c_occ
        for _, mesh in ipairs(meshes) do
            if Valid(mesh) then
                pcall(function()
                    if type(mesh.SetDrawDyeing) == "function" then
                        mesh:SetDrawDyeing(true)
                        mesh:SetDrawDyeingMode(1)
                        mesh:SetVisibleDyeingColor(visColor)
                        mesh:SetOccludedDyeingColor(occColor)
                        mesh:SetDyeingColorFadeDistance(99999.0)
                        mesh:SetDyeingColorMinMaxDistance(0.0, 99999.0)
                        mesh:SetDrawHighlight(true)
                        mesh:OverrideHighlightColor(visColor)
                        mesh:SetHighlightCanBeOccluded(false)
                        mesh:SetDrawIdeaOutline(true)
                        mesh:SetIdeaOutlineNew(true)
                        mesh:SetIdeaOutlineOcclusionHighlight(true)
                        mesh:OverrideIdeaOutlineColor(visColor)
                        mesh:SetIdeaOutlineOcclusionColor(occColor)
                        mesh:OverrideIdeaOutlineThickness(20.0)
                        mesh:SetIdeaOverrideOutlineAndOcclusion(true)
                        mesh:SetRenderCustomDepth(true)
                        mesh:SetCustomDepthStencilValue(255)
                    end
                end)
            end
        end
    end)
end

local function UndoColorBodyNew(enemy, markData)
    pcall(function()
        if markData.ColorNewApplied then
            local meshes = GetAllSkeletalMeshes(enemy, markData)
            local weapon = nil
            pcall(function() weapon = enemy:GetCurrentWeapon() end)
            if slua.isValid(weapon) and slua.isValid(weapon.Mesh) then
                table.insert(meshes, weapon.Mesh)
            end

            for _, mesh in ipairs(meshes) do
                if Valid(mesh) then
                    pcall(function()
                        if type(mesh.SetDrawDyeing) == "function" then
                            mesh:SetDrawDyeing(false)
                            mesh:SetDrawHighlight(false)
                            mesh:SetDrawIdeaOutline(false)
                            mesh:SetRenderCustomDepth(false)
                        end
                    end)
                end
            end
            markData.ColorNewApplied = false
            markData.LastColorNewHash = ""
        end
    end)
end

_G.GetEnemyTargetsFromActors = function(radius)
    local result = {}
    local player = GameplayData.GetPlayerCharacter()

    if not slua.isValid(player) then
        return result
    end

    local allCharacters = {}
    if GameplayData.GetAllPlayerCharacters then
        allCharacters = GameplayData.GetAllPlayerCharacters()
    elseif GameplayData.GameCharacters then
        for _, char in pairs(GameplayData.GameCharacters) do table.insert(allCharacters, char) end
    end

    local myTeam = player:GetTeamID()

    for _, actor in pairs(allCharacters) do
        if slua.isValid(actor) and actor ~= player and actor.GetTeamID and actor:IsAlive() then
            if actor:GetTeamID() ~= myTeam then
                local dist = player:GetDistanceTo(actor)
                if dist <= radius then
                    table.insert(result, actor)
                end
            end
        end
    end
    return result
end

_G.AimHeadUpZ = 9
_G.AimNeckDownZ = 8
_G.AimTouch = function(dt)
    pcall(function()
        _G.MWState.AimLineScreenPos = nil
        _G.MWState.AimTouchTarget = nil
        _G.MWState.AimTouchAimPos = nil
        _G.MWState.AimTouchAimPosRaw = nil
        if not _G.MWConfig.AimTouchEnable then return end
        
        local player = GameplayData.GetPlayerCharacter()
        if not slua.isValid(player) then return end
        
        local pc = player:GetPlayerControllerSafety()
        if not slua.isValid(pc) then return end
        
        local isFiring = player.bIsWeaponFiring
        local isADS = player.bIsGunADS
        
        local weapon = player.WeaponManagerComponent and player.WeaponManagerComponent.CurrentWeaponReplicated
        if not weapon and type(player.GetCurrentShootWeapon) == "function" then
            weapon = player:GetCurrentShootWeapon()
        end
        
        local isShotgun = false
        local isSniper = false
        local isMortar = false
        local currentAmmo = 1
        
        if slua.isValid(weapon) then
            local wID = type(weapon.GetWeaponID) == "function" and weapon:GetWeaponID() or 0
            local wBase = 0
            if wID and wID >= 100000 then
                local ds = tostring(math.floor(wID))
                if ds:len() == 10 and ds:sub(1, 1) == "1" then wBase = tonumber(ds:sub(2, 7)) or 0
                else wBase = tonumber(ds:sub(1, 6)) or 0 end
            end
            local wGroup = math.floor(wBase / 1000)
            isSniper = (wGroup == 103)
            isShotgun = (wGroup == 104)
            isMortar = (wBase == 107011)

            if type(weapon.GetCurrentAmmo) == "function" then
                currentAmmo = weapon:GetCurrentAmmo()
            elseif weapon.ShootWeaponComponent and type(weapon.ShootWeaponComponent.GetCurrentAmmo) == "function" then
                currentAmmo = weapon.ShootWeaponComponent:GetCurrentAmmo()
            elseif weapon.CurrentAmmo ~= nil then
                currentAmmo = weapon.CurrentAmmo
            end
        end

        if _G.MWState.IsAutoFiring then
            pcall(function()
                player.bIsWeaponFiring = false
                if type(player.SetIsWeaponFiring) == "function" then player:SetIsWeaponFiring(false) end
                if slua.isValid(pc) and type(pc.SetIsWeaponFiring) == "function" then pc:SetIsWeaponFiring(false) end
                local wepMgr = player.WeaponManagerComponent
                if slua.isValid(wepMgr) then wepMgr.bIsWeaponFiring = false end
            end)
            _G.MWState.IsAutoFiring = false
        end

        if isShotgun and currentAmmo <= 0 then
            return
        end

        local cond = 2
        local prioMode = 1
        local boneIdx = 1
        local speedVal = 50
        local aimLineOnly = false
        local fovVal = 30
        local maxDistMeters = 50
        local useVisCheck = false
        local igKnock = false
        local igBot = false

        if isMortar and _G.MWConfig.AimTouchMortar then
            local isPlaced = false
            pcall(function()
                if weapon and weapon.MortarState == 2 then isPlaced = true end
            end)
            if not isPlaced then return end

            cond = 2
            prioMode = 1
            boneIdx = 4
            speedVal = 100
            fovVal = _G.MWState.CustomTextData.AimTouchMortarFOV or 360
            maxDistMeters = 2000
            useVisCheck = false
            igKnock = false
            igBot = false


        else
            cond = _G.MWState.CustomTextData.AimTouchCond or 1
            if isSniper and isADS and cond == 1 then cond = 2 end
            if isShotgun then cond = 2 end
            aimLineOnly = (cond == 1 and not isFiring)
            prioMode = _G.MWState.CustomTextData.AimTouchPrio or 1
            boneIdx = _G.MWState.CustomTextData.AimTouchBone or 2
            speedVal = _G.MWState.CustomTextData.AimTouchSpeed or 30
            fovVal = _G.MWState.CustomTextData.AimTouchFOV or 30
            maxDistMeters = 1000000
            useVisCheck = _G.MWConfig.AimTouchVisCheck
            igKnock = _G.MWConfig.AimTouchIgKnock
            igBot = _G.MWConfig.AimTouchIgBot
        end

        _G.MWState.ActiveFOVVal = fovVal

        local currentMaxDist = maxDistMeters * 100

        local enemies = _G.GetEnemyTargetsFromActors(currentMaxDist)
        if not enemies then enemies = {} end
        
        local AT = _G._AimTouchCache
        if not AT then
            AT = { FVector2D = import("Vector2D"), GS = import("GameplayStatics"), KML = import("KismetMathLibrary"), zero = {X=0, Y=0, Z=0} }
            AT.tmp2D = AT.FVector2D()
            _G._AimTouchCache = AT
        end
        local FVector2D = AT.FVector2D
        local UGameplayStatics = AT.GS
        local KismetMathLibrary = AT.KML
        local ZERO3 = AT.zero
        local screen = AT.tmp2D
        
        local camManager = UGameplayStatics.GetPlayerCameraManager(pc, 0)
        if not slua.isValid(camManager) then return end
        
        local camLoc = camManager:GetCameraLocation()
        if not camLoc then return end
        
        local ui_util = require("client.common.ui_util")
        if not ui_util then return end
        
        local viewportSize = ui_util.GetViewportSize()
        if not viewportSize then return end
        
        local centerX = viewportSize.X * 0.5
        local centerY = viewportSize.Y * 0.5
        
        local FOV_RADIUS = (fovVal / 100.0) * (viewportSize.X / 2.0)
        
        local bestTarget = nil
        local bestScore = 99999999
        local bestIsVehicle = false
        
        local selBoneName = "head"
        local boneZAdj = 0
        if boneIdx == 1 then selBoneName = "head"; boneZAdj = _G.AimHeadUpZ or 0
        elseif boneIdx == 5 then selBoneName = "head"; boneZAdj = -(_G.AimNeckDownZ or 0)
        elseif boneIdx == 2 then selBoneName = "spine_03"
        elseif boneIdx == 3 then selBoneName = "spine_01"
        elseif boneIdx == 4 then selBoneName = "pelvis" end

        for i, target in ipairs(enemies) do
            if not slua.isValid(target) then goto continue end
            
            pcall(function()
                local m = target.Mesh
                if slua.isValid(m) and m.MeshComponentUpdateFlag ~= 0 then
                    m.MeshComponentUpdateFlag = 0
                end
            end)
            
            if igKnock and target.HealthStatus == 1 then goto continue end
            
            if igBot then
                local tIsBot = false
                if target.bIsAI == true then tIsBot = true end
                pcall(function() if _G.PlayerMapMarker and _G.PlayerMapMarker.IsAI(target) then tIsBot = true end end)
                local pState = target.PlayerState
                if slua.isValid(pState) and pState.bIsABot then tIsBot = true end
                if tIsBot then goto continue end
            end

            if _G.CachedVehicles then
                local inFighter = false
                for _, vItem in ipairs(_G.CachedVehicles) do
                    if vItem.name and (vItem.name == "FIGHTER JET") and slua.isValid(vItem.act) then
                        pcall(function()
                            local driver = type(vItem.act.GetDriver) == "function" and vItem.act:GetDriver() or nil
                            if slua.isValid(driver) and driver == target then inFighter = true end
                        end)
                        if inFighter then break end
                    end
                end
                if inFighter then goto continue end
            end

            if useVisCheck then
                if not _G.MWLoS.CachedVisible(target, pc, player, camLoc) then goto continue end
            end
            
            local tPos = target:GetBonePos(selBoneName, ZERO3)
            if not tPos or (tPos.X == 0 and tPos.Y == 0 and tPos.Z == 0) then
                if type(target.GetSocketLocation) == "function" then
                    tPos = target:GetSocketLocation(selBoneName)
                end
            end
            if not tPos or (tPos.X == 0 and tPos.Y == 0 and tPos.Z == 0) then
                if type(target.K2_GetActorLocation) == "function" then
                    tPos = target:K2_GetActorLocation()
                    if tPos then
                        if boneIdx == 1 or boneIdx == 5 then tPos.Z = tPos.Z + 70
                        elseif boneIdx == 2 then tPos.Z = tPos.Z + 40
                        elseif boneIdx == 3 then tPos.Z = tPos.Z + 20 end
                    end
                end
            end
            if not tPos or (tPos.X == 0 and tPos.Y == 0 and tPos.Z == 0) then goto continue end
            if boneZAdj ~= 0 then pcall(function() tPos.Z = tPos.Z + boneZAdj end) end
            
            screen.X = 0; screen.Y = 0
            local success = pc:ProjectWorldLocationToScreen(tPos, screen, false)
            if not success or screen.X <= 0 or screen.Y <= 0 then goto continue end
            
            local dx = screen.X - centerX
            local dy = screen.Y - centerY
            local distScreen = math.sqrt(dx*dx + dy*dy)
            
            if distScreen > FOV_RADIUS then goto continue end
            
            local currentScore = distScreen
            if prioMode == 2 then currentScore = player:GetDistanceTo(target)
            elseif prioMode == 3 then currentScore = target.Health or 100
            elseif prioMode == 4 then 
                local hp = target.Health or 100
                local maxhp = target.HealthMax or 100
                if maxhp <= 0 then maxhp = 100 end
                currentScore = hp / maxhp
            end
            
            if currentScore < bestScore then
                bestScore = currentScore
                bestTarget = target
            end
            
            ::continue::
        end

        if _G.CachedVehicles then
            for _, vItem in ipairs(_G.CachedVehicles) do
                local isAimVeh = vItem.name and (vItem.name == "FIGHTER JET")
                if isAimVeh and vItem.hasDriver and slua.isValid(vItem.act) then
                    local veh = vItem.act
                    local vDist = 0
                    pcall(function() vDist = player:GetDistanceTo(veh) end)
                    if vDist > 0 and vDist <= currentMaxDist then
                        if useVisCheck then
                            local now = _G.RealNow()
                            local vId = "aimveh_" .. tostring(veh)
                            local vc = _G.MWLoS.vcache[vId]
                            if not vc or (now - vc.t) >= _G.MWLoS.vinterval then
                                local vcp = nil
                                pcall(function() vcp = veh:K2_GetActorLocation() end)
                                if vcp then vcp = { X = vcp.X, Y = vcp.Y, Z = vcp.Z + 150 } end
                                local seen = _G.MWLoS.PointVisible(pc, veh, player, camLoc, vcp)
                                if not vc then vc = { t = 0, vis = true }; _G.MWLoS.vcache[vId] = vc end
                                vc.t = now; vc.vis = seen
                            end
                            if not vc.vis then goto continue_veh end
                        end

                        local vPos = nil
                        pcall(function() vPos = veh:K2_GetActorLocation() end)
                        if not vPos or (vPos.X == 0 and vPos.Y == 0 and vPos.Z == 0) then goto continue_veh end
                        vPos.Z = vPos.Z + 150

                        screen.X = 0; screen.Y = 0
                        local success = pc:ProjectWorldLocationToScreen(vPos, screen, false)
                        if not success or screen.X <= 0 or screen.Y <= 0 then goto continue_veh end

                        local dx = screen.X - centerX
                        local dy = screen.Y - centerY
                        local distScreen = math.sqrt(dx*dx + dy*dy)

                        if distScreen > FOV_RADIUS then goto continue_veh end

                        local currentScore = distScreen
                        if prioMode == 2 then currentScore = vDist end

                        if currentScore < bestScore then
                            bestScore = currentScore
                            bestTarget = veh
                            bestIsVehicle = true
                        end
                    end
                end
                ::continue_veh::
            end
        end

        if not slua.isValid(bestTarget) then return end

        local finalBonePos
        if bestIsVehicle then
            pcall(function()
                finalBonePos = bestTarget:K2_GetActorLocation()
                if finalBonePos then finalBonePos.Z = finalBonePos.Z + 150 end
            end)
        else
            finalBonePos = bestTarget:GetBonePos(selBoneName, ZERO3)
            if not finalBonePos or (finalBonePos.X == 0 and finalBonePos.Y == 0 and finalBonePos.Z == 0) then
                if type(bestTarget.GetSocketLocation) == "function" then
                    finalBonePos = bestTarget:GetSocketLocation(selBoneName)
                end
            end
            if not finalBonePos or (finalBonePos.X == 0 and finalBonePos.Y == 0 and finalBonePos.Z == 0) then
                if type(bestTarget.K2_GetActorLocation) == "function" then
                    finalBonePos = bestTarget:K2_GetActorLocation()
                    if finalBonePos then
                        if boneIdx == 1 or boneIdx == 5 then finalBonePos.Z = finalBonePos.Z + 70
                        elseif boneIdx == 2 then finalBonePos.Z = finalBonePos.Z + 40
                        elseif boneIdx == 3 then finalBonePos.Z = finalBonePos.Z + 20 end
                    end
                end
            end
        end
        if not finalBonePos or (finalBonePos.X == 0 and finalBonePos.Y == 0 and finalBonePos.Z == 0) then return end
        if boneZAdj ~= 0 then pcall(function() finalBonePos.Z = finalBonePos.Z + boneZAdj end) end
        local rawAimPos = { X = finalBonePos.X, Y = finalBonePos.Y, Z = finalBonePos.Z }

        pcall(function()
            local aimScr = FVector2D()
            if pc:ProjectWorldLocationToScreen(finalBonePos, aimScr, false) and aimScr.X > 0 and aimScr.Y > 0 then
                _G.MWState.AimLineScreenPos = {X = aimScr.X, Y = aimScr.Y, cX = centerX, cY = centerY}
            end
        end)

        if not isMortar and camLoc then
            pcall(function()
                local tvRaw = type(bestTarget.GetVelocity) == "function" and bestTarget:GetVelocity() or nil
                if not tvRaw then return end
                local now = _G.RealNow()
                local key = tostring(bestTarget)
                local pv = _G.MWPredV
                if not pv then pv = {}; _G.MWPredV = pv end
                local fresh = (pv.key == key) and pv.t and (now - pv.t) <= 0.30
                local dt = fresh and (now - pv.t) or nil

                local svx, svy, svz
                if fresh then
                    local a = 0.7
                    svx = pv.vx * (1 - a) + tvRaw.X * a
                    svy = pv.vy * (1 - a) + tvRaw.Y * a
                    svz = pv.vz * (1 - a) + tvRaw.Z * a
                else
                    svx, svy, svz = tvRaw.X, tvRaw.Y, tvRaw.Z
                end

                local sax, say, saz = 0, 0, 0
                if fresh and dt and dt > 0 and pv.vx then
                    local ra = 0.35
                    sax = (pv.ax or 0) * (1 - ra) + ((svx - pv.vx) / dt) * ra
                    say = (pv.ay or 0) * (1 - ra) + ((svy - pv.vy) / dt) * ra
                    saz = (pv.az or 0) * (1 - ra) + ((svz - pv.vz) / dt) * ra
                    local AC = 2000
                    if sax > AC then sax = AC elseif sax < -AC then sax = -AC end
                    if say > AC then say = AC elseif say < -AC then say = -AC end
                    if saz > AC then saz = AC elseif saz < -AC then saz = -AC end
                end

                pv.key, pv.t = key, now
                pv.vx, pv.vy, pv.vz = svx, svy, svz
                pv.ax, pv.ay, pv.az = sax, say, saz

                local sp = math.sqrt(svx * svx + svy * svy + svz * svz)
                if sp <= 30 or sp >= 15000 then return end

                local bs = 80000
                pcall(function()
                    local ent = weapon and ((type(weapon.GetShootWeaponEntityComponent) == "function" and weapon:GetShootWeaponEntityComponent()) or weapon.ShootWeaponEntityComp or weapon.ShootWeaponEntity)
                    if ent and type(ent.BulletFireSpeed) == "number" and ent.BulletFireSpeed > 1000 then bs = ent.BulletFireSpeed end
                end)
                if bs > 100000 then bs = 71500 end

                local LF = 1.2
                local ox, oy, oz = finalBonePos.X, finalBonePos.Y, finalBonePos.Z
                local px, py, pz = ox, oy, oz
                for _ = 1, 4 do
                    local dx, dy, dz = px - camLoc.X, py - camLoc.Y, pz - camLoc.Z
                    local tof = math.sqrt(dx * dx + dy * dy + dz * dz) / bs
                    if tof > 1.5 then tof = 1.5 end
                    local ta = tof; if ta > 0.6 then ta = 0.6 end
                    local h = 0.5 * ta * ta
                    px = ox + svx * tof * LF + sax * h
                    py = oy + svy * tof * LF + say * h
                    pz = oz + svz * tof * LF + saz * h
                end
                finalBonePos.X, finalBonePos.Y, finalBonePos.Z = px, py, pz
            end)
        end

        _G.MWState.AimTouchTarget = bestTarget
        _G.MWState.AimTouchAimPos = { X = finalBonePos.X, Y = finalBonePos.Y, Z = finalBonePos.Z }
        _G.MWState.AimTouchAimPosRaw = rawAimPos
        _G.MWState.AimTouchIsVehicle = bestIsVehicle and true or false
        if not _G.MWConfig.AimTouchEnable then return end

        local rot = KismetMathLibrary.FindLookAtRotation(camLoc, finalBonePos)
        if not rot then return end
        
        local currentRot = pc:GetControlRotation()
        if not currentRot then return end
        
        local deltaYaw = rot.Yaw - currentRot.Yaw
        local deltaPitch = rot.Pitch - currentRot.Pitch
        
        if isADS then
            local camRot = nil
            if type(camManager.GetCameraRotation) == "function" then
                camRot = camManager:GetCameraRotation()
            end
            if camRot then
                deltaYaw = deltaYaw - (camRot.Yaw - currentRot.Yaw)
                deltaPitch = deltaPitch - (camRot.Pitch - currentRot.Pitch)
            end
        end

        if deltaYaw > 180 then deltaYaw = deltaYaw - 360 end
        if deltaYaw < -180 then deltaYaw = deltaYaw + 360 end
        if deltaPitch > 180 then deltaPitch = deltaPitch - 360 end
        if deltaPitch < -180 then deltaPitch = deltaPitch + 360 end
        
        local smoothFactor = 0.0
        if speedVal >= 100 then
            smoothFactor = 1.0
        else
            smoothFactor = (speedVal / 100.0) * 0.3
            if smoothFactor < 0.01 then smoothFactor = 0.01 end
            if dt and dt > 0 then
                local frames = dt * 60.0
                if frames > 4 then frames = 4 end
                smoothFactor = 1.0 - (1.0 - smoothFactor) ^ frames
            end
        end
        
        local finalPitch = currentRot.Pitch + (deltaPitch * smoothFactor)
        local finalYaw = currentRot.Yaw + (deltaYaw * smoothFactor)
        
        
        if isMortar and _G.MWConfig.AimTouchMortar then
            local targetPos = { X = finalBonePos.X, Y = finalBonePos.Y, Z = finalBonePos.Z }
            local launchPos = camLoc
            pcall(function()
                if player.K2_GetActorLocation then
                    local pLoc = player:K2_GetActorLocation()
                    if pLoc then 
                        launchPos = { X = pLoc.X, Y = pLoc.Y, Z = pLoc.Z + 50 } 
                    end
                end
            end)

            local function CalcMortarTrajectory(V, G, tX, tY, tZ)
                local mDx = math.sqrt((tX - launchPos.X)^2 + (tY - launchPos.Y)^2) - 80 
                if mDx < 500 then mDx = 500 end 
                local mDy = tZ - launchPos.Z
                
                local minVSq = G * (mDy + math.sqrt(mDx*mDx + mDy*mDy))
                if (V * V) < minVSq then
                    V = math.sqrt(minVSq) + 100 
                end

                local v2 = V * V
                local root = v2*v2 - G*(G*mDx*mDx + 2*mDy*v2)
                
                if root >= 0 then
                    local angleRad = math.atan((v2 + math.sqrt(root)) / (G * mDx))
                    local deg = math.deg(angleRad)
                    if deg >= 35 and deg <= 89.5 then 
                        return true, deg, mDx / (V * math.cos(angleRad)), mDx
                    end
                end
                return false, 45, 0, mDx
            end

            local vNear, gNear = 9070, 980 * 2.8   
            local vFar, gFar = 12520, 980 * 4.0    
            local vUltra, gUltra = 16800, 980 * 4.5 
            
            local isValid, physAngle, ToF, finalDx = false, 45, 0, 0
            
            local okNear, angNear, tofNear, dxN = CalcMortarTrajectory(vNear, gNear, targetPos.X, targetPos.Y, targetPos.Z)
            local okFar, angFar, tofFar, dxF = CalcMortarTrajectory(vFar, gFar, targetPos.X, targetPos.Y, targetPos.Z)
            local okUltra, angUltra, tofUltra, dxU = CalcMortarTrajectory(vUltra, gUltra, targetPos.X, targetPos.Y, targetPos.Z)

            if okNear and dxN <= 25000 then
                isValid, physAngle, ToF, finalDx = okNear, angNear, tofNear, dxN
            elseif okFar and dxF <= 40000 then
                isValid, physAngle, ToF, finalDx = okFar, angFar, tofFar, dxF
            elseif okUltra then
                isValid, physAngle, ToF, finalDx = okUltra, angUltra, tofUltra, dxU
            elseif okNear then
                isValid, physAngle, ToF, finalDx = okNear, angNear, tofNear, dxN
            end

            local targetCameraPitch = ((physAngle - 45) / 43.0) * 90.0 - 60.0
            local targetCameraYaw = rot.Yaw

            local deltaPitchMortar = targetCameraPitch - currentRot.Pitch
            local deltaYawMortar = targetCameraYaw - currentRot.Yaw

            if deltaPitchMortar > 180 then deltaPitchMortar = deltaPitchMortar - 360 end
            if deltaPitchMortar < -180 then deltaPitchMortar = deltaPitchMortar + 360 end
            if deltaYawMortar > 180 then deltaYawMortar = deltaYawMortar - 360 end
            if deltaYawMortar < -180 then deltaYawMortar = deltaYawMortar + 360 end
            
            finalPitch = currentRot.Pitch + (deltaPitchMortar * smoothFactor)
            finalYaw = currentRot.Yaw + (deltaYawMortar * smoothFactor)
        end



        if aimLineOnly then return end

        local finalRot = { Pitch = finalPitch, Yaw = finalYaw, Roll = 0 }
        pc:SetControlRotation(finalRot, "AimTouch")


    end)
end


