_G.AppliedItemESP = {}

function _G.MWTextOutline(txt, px)
    if not txt or not slua.isValid(txt) then return end
    pcall(function()
        local f = txt.Font
        local o = f.OutlineSettings
        o.OutlineSize = px or 1
        o.OutlineColor = FLinearColor and FLinearColor(0.0, 0.0, 0.0, 1.0) or {R=0, G=0, B=0, A=255}
        f.OutlineSettings = o
        txt.Font = f
    end)
end

_G._RN_off, _G._RN_lastRaw, _G._RN_last = 0, nil, 0
function _G.RealNow()
    local GS = _G._RealNow_GS
    if GS == nil then GS = import("GameplayStatics") or false; _G._RealNow_GS = GS end
    local t = nil
    if GS then
        local w = slua.getWorld()
        if w then
            local ok, v = pcall(GS.GetRealTimeSeconds, w)
            if ok and type(v) == "number" then t = v end
        end
    end
    if not t then t = os.clock() end
    if _G._RN_lastRaw and t < _G._RN_lastRaw - 0.5 then
        _G._RN_off = _G._RN_last - t + 0.001
    end
    _G._RN_lastRaw = t
    local v = t + _G._RN_off
    if v < _G._RN_last then v = _G._RN_last end
    _G._RN_last = v
    return v
end

_G.ItemESP_MaxLabels = 80
_G.RunOptimizedItemAndVehicleESP = function(pc)
    local curTime = _G.RealNow()

    if curTime - _G.LastScanItemTime > 1.0 then
        _G.LastScanItemTime = curTime
        local player = GameplayData.GetPlayerCharacter()
        if not slua.isValid(player) then return end

        if _G._ItemGearWallPrev ~= nil and _G._ItemGearWallPrev ~= _G.MWConfig.EspItem_GearWall then
            _G.AppliedItemESP = {}
        end
        _G._ItemGearWallPrev = _G.MWConfig.EspItem_GearWall

        if _G.MWConfig.EspItem_Master then
            _G._ItemESP_PickupClass = _G._ItemESP_PickupClass or import("PickUpWrapperActor") or import("STPickupWrapperActor")
            local APickUpWrapperActor = _G._ItemESP_PickupClass
            if APickUpWrapperActor then
                local Actors = Game:GetActorsByClass(APickUpWrapperActor)
                _G.CachedItems = {}
                local candidates = {}
                local seenApplied = {}
                if Actors then
                    local count = Actors:Num() or 0
                    local SMClass = _G._ItemESP_SMClass or import("StaticMeshComponent"); _G._ItemESP_SMClass = SMClass
                    for i = 0, count - 1 do
                        local item = Actors:Get(i)
                        if slua.isValid(item) and not item.bHidden then
                            seenApplied[tostring(item)] = true
                            local dist = player:GetDistanceTo(item)
                            do
                                local itemId = item.DefineID and item.DefineID.TypeSpecificID or item.DefineId
                                local itemData = itemId and ItemDatabase[itemId]
                                if itemData then
                                    local isShow = false
                                    local c = itemData.cat
                                    if c == "AR" then isShow = _G.MWConfig.EspItem_AR
                                    elseif c == "Sniper" then isShow = _G.MWConfig.EspItem_Sniper
                                    elseif c == "SMG" then isShow = _G.MWConfig.EspItem_SMG
                                    elseif c == "Shotgun" then isShow = _G.MWConfig.EspItem_Shotgun
                                    elseif c == "LMG" then isShow = _G.MWConfig.EspItem_LMG
                                    elseif c == "Pistol" then isShow = _G.MWConfig.EspItem_Pistol
                                    elseif c == "Melee" then isShow = _G.MWConfig.EspItem_Melee
                                    elseif c == "Special" then isShow = _G.MWConfig.EspItem_Special
                                    elseif c == "Grenade" then isShow = _G.MWConfig.EspItem_Grenade
                                    elseif c == "Scope" then isShow = _G.MWConfig.EspItem_Scope
                                    elseif c == "Med" then isShow = _G.MWConfig.EspItem_Med
                                    elseif c == "Helmet" or c == "Vest" or c == "Bag" then isShow = _G.MWConfig.EspItem_Gear
                                    elseif c == "GasCan" then isShow = _G.MWConfig.EspItem_GasCan
                                    elseif c == "Ammo" then isShow = _G.MWConfig.EspItem_Ammo
                                    elseif c == "ShopToken" then isShow = _G.MWConfig.EspItem_ShopToken
                                    end

                                    if isShow then
                                        local espName = itemData.label or (_G.MWLang == "EN" and itemData.en) or itemData.name
                                        candidates[#candidates + 1] = {act = item, name = espName, color = itemData.color, d = dist, cat = c, id = itemId, scale = itemData.scale}
                                        local iId = tostring(item)
                                        if not _G.AppliedItemESP[iId] then
                                            local meshes = {}
                                            if item.GetPickupMesh then
                                                local pMesh = item:GetPickupMesh()
                                                if slua.isValid(pMesh) then table.insert(meshes, pMesh) end
                                            end
                                            local childs = item:GetComponentsByClass(SMClass)
                                            if childs then
                                                for _, v in pairs(childs) do
                                                    if slua.isValid(v) and v ~= meshes[1] then table.insert(meshes, v) end
                                                end
                                            end
                                            if not _G.ConsoleNewWallReady then
                                                pcall(function()
                                                    local KSL = import("KismetSystemLibrary")
                                                    local w = slua.getWorld()
                                                    if KSL and w then
                                                        KSL.ExecuteConsoleCommand(w, "r.EnableDrawDyeingColor 1")
                                                        KSL.ExecuteConsoleCommand(w, "r.CustomDepth 3")
                                                        KSL.ExecuteConsoleCommand(w, "r.IdeaOutline.Enable 1")
                                                        KSL.ExecuteConsoleCommand(w, "r.Highlight.Enable 1")
                                                        _G.ConsoleNewWallReady = true
                                                    end
                                                end)
                                            end
                                            local isLv3 = itemId == 502003 or itemId == 503003 or itemId == 501006
                                            for _, mesh in pairs(meshes) do
                                                if isLv3 then pcall(function() mesh:SetRenderCustomDepth(true) end) end
                                                if isLv3 and _G.MWConfig.EspItem_GearWall then
                                                    pcall(function()
                                                        local LC = import("LinearColor") or _G.FLinearColor
                                                        local visColor = LC and LC(0, 22, 100, 100) or nil
                                                        local occColor = LC and LC(100, 0, 0, 100) or nil
                                                        if type(mesh.SetDrawDyeing) == "function" then
                                                            mesh:SetDrawDyeing(true)
                                                            mesh:SetDrawDyeingMode(1)
                                                            mesh:SetVisibleDyeingColor(visColor)
                                                            mesh:SetOccludedDyeingColor(occColor)
                                                            mesh:SetDyeingColorFadeDistance(99999.0)
                                                            mesh:SetDyeingColorMinMaxDistance(0.0, 99999.0)
                                                            mesh:SetDrawHighlight(true)
                                                            mesh:OverrideHighlightColor(visColor)
                                                            mesh:SetHighlightCanBeOccluded(false)
                                                            mesh:SetDrawIdeaOutline(true)
                                                            mesh:SetIdeaOutlineNew(true)
                                                            mesh:SetIdeaOutlineOcclusionHighlight(true)
                                                            mesh:OverrideIdeaOutlineColor(visColor)
                                                            mesh:SetIdeaOutlineOcclusionColor(occColor)
                                                            mesh:OverrideIdeaOutlineThickness(1.0)
                                                            mesh:SetIdeaOverrideOutlineAndOcclusion(true)
                                                            mesh:SetRenderCustomDepth(true)
                                                            mesh:SetCustomDepthStencilValue(255)
                                                        end
                                                    end)
                                                elseif isLv3 and not _G.MWConfig.EspItem_GearWall then
                                                    pcall(function()
                                                        if type(mesh.SetDrawDyeing) == "function" then
                                                            mesh:SetDrawDyeing(false)
                                                            mesh:SetDrawHighlight(false)
                                                            mesh:SetDrawIdeaOutline(false)
                                                        end
                                                    end)
                                                end
                                                local numMat = 9
                                                pcall(function() if type(mesh.GetNumMaterials) == "function" then numMat = mesh:GetNumMaterials() or 9 end end)
                                                if numMat > 9 then numMat = 9 end
                                                for mi = 0, numMat - 1 do
                                                    local mid = mesh:CreateAndSetMaterialInstanceDynamic(mi)
                                                    if slua.isValid(mid) then
                                                        local colorVisible = (isLv3 and _G.MWConfig.EspItem_GearWall) and {R = 255, G = 0, B = 200, A = 10} or {R = 50, G = 50, B = 0, A = 10}
                                                        pcall(function()
                                                            mid:SetVectorParameterValue("LightColor", colorVisible)
                                                            mid:SetVectorParameterValue("ParaScaleOffset", {R = 3, G = 3, B = 0, A = 0})
                                                            mid:SetScalarParameterValue("RimLight", 999)
                                                            mid:SetScalarParameterValue("Brightness", 999)
                                                            mid:SetScalarParameterValue("Exposure", 999)
                                                        end)
                                                    end
                                                end
                                            end
                                            _G.AppliedItemESP[iId] = true
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                for k in pairs(_G.AppliedItemESP) do
                    if not seenApplied[k] then _G.AppliedItemESP[k] = nil end
                end
                table.sort(candidates, function(a, b) return a.d < b.d end)
                local maxN = _G.ItemESP_MaxLabels or 80
                for i = 1, math.min(#candidates, maxN) do _G.CachedItems[#_G.CachedItems + 1] = candidates[i] end
            end

            if _G.MWConfig.EspItem_DeadBox then pcall(function()
                local APlayerTombBox = import("PlayerTombBox")
                if APlayerTombBox then
                    local deadBoxes = Game:GetActorsByClass(APlayerTombBox)
                    if deadBoxes then
                        local dbCount = deadBoxes:Num() or 0
                        for i = 0, dbCount - 1 do
                            local box = deadBoxes:Get(i)
                            if slua.isValid(box) then
                                local bt = 0
                                pcall(function() bt = box.BoxType or 0 end)
                                if bt == 1 then
                                    local espName = (_G.MWLang == "EN" and "Airdrop") or "Airdrop"
                                    table.insert(_G.CachedItems, {act = box, name = espName, color = {R=255, G=0, B=0, A=255}, isBox = true, kind = "airdrop", off = {X=0, Y=0, Z=60}})
                                else
                                    local espName = (_G.MWLang == "EN" and "Dead Box") or "Dead Box"
                                    table.insert(_G.CachedItems, {act = box, name = espName, color = {R=255, G=210, B=0, A=255}, isBox = true, off = {X=0, Y=0, Z=60}})
                                end
                            end
                        end
                    end
                end
            end) end
        else
            _G.AppliedItemESP = {}
            _G.CachedItems = {}
        end
    end

end


local PlayerMapMarker = {}

local RedBoxOverlay = {
    bActive = false,
    MainContainer = nil,
    WidgetSlot = nil,
    TextBlockPlayer = nil,
    TextBlockBot = nil,
    Width = 220,
    Height = 32,
    OffsetY = 10,
    PlayerCount = 0,
    BotCount = 0,
    FontSize = 14,
    TextScaleValue = 1.0,
    NumLayers = 1,
    Red = 0.0,
    Green = 0.0,
    Blue = 0.0,
    LayerAlpha = 0.40,
    _CachedTextPlayer = "",
    _CachedTextBot = "",
    _CachedPosVec = nil
}

RedBoxOverlay.ImgW, RedBoxOverlay.ImgH = 168, 44
RedBoxOverlay.ImgIcon = 32
RedBoxOverlay.ImgFont = 20
function RedBoxOverlay._MakeText(Container, str, color, size)
    local FSlateColor = RedBoxOverlay._SlateColor
    if FSlateColor == nil then FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor") or false; RedBoxOverlay._SlateColor = FSlateColor end
    local t = nil
    pcall(function() t = CGame:NewObjectFromPath("/Script/UMG.TextBlock", Container) end)
    if not t or not slua.isValid(t) then return nil end
    pcall(function()
        t:SetText(str)
        if FSlateColor then t:SetColorAndOpacity(FSlateColor(color)) else t:SetColorAndOpacity(color) end
        if t.Font then local font = t.Font; font.Size = size; t.Font = font end
        _G.MWTextOutline(t, 1)
        pcall(function() t:SetShadowColorAndOpacity(FLinearColor(0.0, 0.0, 0.0, 0.8)) end)
        pcall(function() t:SetShadowOffset(FVector2D(1, 1)) end)
        t:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
    end)
    return t
end

function RedBoxOverlay.CreateImage()
    local ParentCanvas = PlayerMapMarker.ESPCanvas
    if not ParentCanvas or not slua.isValid(ParentCanvas) then
        if not PlayerMapMarker.InitESPCanvas() then return false end
        ParentCanvas = PlayerMapMarker.ESPCanvas
    end
    if not ParentCanvas or not slua.isValid(ParentCanvas) then return false end
    local Container = nil
    pcall(function() Container = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", ParentCanvas) end)
    if not Container or not slua.isValid(Container) then return false end
    local W, H = RedBoxOverlay.ImgW, RedBoxOverlay.ImgH
    local IC = RedBoxOverlay.ImgIcon
    local iy = (H - IC) * 0.5
    local bg = _G.MWIconImageAt(Container, 0, 0, W, H, "cnt_bg", 0, 0, 0)
    local ip = _G.MWIconImageAt(Container, 12, iy, IC, IC, "cnt_p", 0, 0, 1)
    local ib = _G.MWIconImageAt(Container, W * 0.5 + 12, iy, IC, IC, "cnt_b", 0, 0, 1)
    if not (bg and ip and ib) then
        pcall(function() Container:RemoveFromParent() end)
        return false
    end
    pcall(function() ip.w:SetColorAndOpacity(RedBoxOverlay.ColorLime) end)
    pcall(function() ib.w:SetColorAndOpacity(RedBoxOverlay.ColorYellow) end)
    local white = RedBoxOverlay.ColorWhite
    local numP = RedBoxOverlay._MakeText(Container, tostring(RedBoxOverlay.PlayerCount), white, RedBoxOverlay.ImgFont)
    local numB = RedBoxOverlay._MakeText(Container, tostring(RedBoxOverlay.BotCount), white, RedBoxOverlay.ImgFont)
    local function place(t, x)
        if not t then return end
        local sl = nil
        pcall(function() sl = Container:AddChildToCanvas(t) end)
        if sl then pcall(function() sl:SetAutoSize(true); sl:SetAlignment(FVector2D(0.5, 0.5)); sl:SetPosition(FVector2D(x, H * 0.5)); sl:SetZOrder(2) end) end
    end
    place(numP, 12 + IC + 22); place(numB, W * 0.5 + 12 + IC + 22)
    RedBoxOverlay.TextBlockPlayer = nil; RedBoxOverlay.TextBlockBot = nil
    RedBoxOverlay.NumPlayer = numP; RedBoxOverlay.NumBot = numB
    local function half(x0, wantBot, icon, num)
        local function fx(p)
            local sc = p and 0.9 or 1.0
            for _, w in ipairs({ icon and icon.w, num }) do
                pcall(function()
                    if w and slua.isValid(w) then
                        w:SetRenderTransformPivot(FVector2D(0.5, 0.5))
                        w:SetRenderScale(FVector2D(sc, sc))
                    end
                end)
            end
        end
        pcall(function()
            local FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor")
            local btn = CGame:NewObjectFromPath("/Script/UMG.Button", Container)
            if not btn or not slua.isValid(btn) then return end
            local tr = FLinearColor(0, 0, 0, 0)
            pcall(function() btn:SetBackgroundColor(tr) end)
            pcall(function() btn.WidgetStyle.Normal.TintColor = FSlateColor(tr) end)
            pcall(function() btn.WidgetStyle.Hovered.TintColor = FSlateColor(tr) end)
            pcall(function() btn.WidgetStyle.Pressed.TintColor = FSlateColor(tr) end)
            pcall(function() btn:SetBrushColor(tr) end)
            pcall(function() btn.bIsFocusable = false end)
            pcall(function() btn.IsFocusable = false end)
            btn.OnPressed:Add(function() fx(true) end)
            btn.OnReleased:Add(function() fx(false) end)
            btn.OnClicked:Add(function() RedBoxOverlay.LookAtNearest(wantBot) end)
            local sl = Container:AddChildToCanvas(btn)
            if sl then pcall(function() sl:SetAutoSize(false); sl:SetPosition(FVector2D(x0, 0)); sl:SetSize(FVector2D(W * 0.5, H)); sl:SetZOrder(5) end) end
            pcall(function() btn:SetWidgetVisibility(UEnums.ESlateVisibility.Visible) end)
        end)
    end
    half(0, false, ip, numP)
    half(W * 0.5, true, ib, numB)
    RedBoxOverlay._NumPColor = nil; RedBoxOverlay._NumBColor = nil
    RedBoxOverlay._NumPColorT = nil; RedBoxOverlay._NumBColorT = nil
    local MainSlot = nil
    pcall(function() MainSlot = ParentCanvas:AddChildToCanvas(Container) end)
    if not MainSlot then return false end
    RedBoxOverlay.MainContainer = Container
    RedBoxOverlay.WidgetSlot = MainSlot
    pcall(function()
        MainSlot:SetAutoSize(false)
        MainSlot:SetZOrder(999)
        MainSlot:SetAlignment(FVector2D(0.5, 0.0))
        MainSlot:SetSize(FVector2D(W, H))
        local FAnchors = FAnchors or import("Anchors") or import("/Script/SlateCore.Anchors")
        if FAnchors then MainSlot:SetAnchors(FAnchors(0.5, 0, 0.5, 0)) end
        MainSlot:SetPosition(FVector2D(0, 35))
    end)
    RedBoxOverlay._LastY = nil
    RedBoxOverlay.UpdatePosition()
    return true
end

function RedBoxOverlay.Create()
    return RedBoxOverlay.CreateImage()
end

RedBoxOverlay.ColorWhite = FLinearColor and FLinearColor(1.0, 1.0, 1.0, 1.0) or {R=255, G=255, B=255, A=255}
RedBoxOverlay.ColorLime = FLinearColor and FLinearColor(0.0, 1.0, 0.0, 1.0) or {R=0, G=255, B=0, A=255}
RedBoxOverlay.ColorYellow = FLinearColor and FLinearColor(1.0, 0.82, 0.0, 1.0) or {R=255, G=210, B=0, A=255}

function RedBoxOverlay._SetNum(txt, value, colorKey, activeColor)
    if not txt or not slua.isValid(txt) then return end
    local str = tostring(value)
    local sKey = colorKey .. "T"
    if RedBoxOverlay[sKey] ~= str then RedBoxOverlay[sKey] = str; pcall(txt.SetText, txt, str) end
    local color = (value > 0) and activeColor or RedBoxOverlay.ColorWhite
    if RedBoxOverlay[colorKey] ~= color then
        RedBoxOverlay[colorKey] = color
        local FSlateColor = RedBoxOverlay._SlateColor
        pcall(function() if FSlateColor then txt:SetColorAndOpacity(FSlateColor(color)) else txt:SetColorAndOpacity(color) end end)
    end
end

function RedBoxOverlay.SetCounts(players, bots)
    if RedBoxOverlay.PlayerCount == players and RedBoxOverlay.BotCount == bots then return end
    RedBoxOverlay.PlayerCount = players or 0
    RedBoxOverlay.BotCount = bots or 0
    RedBoxOverlay._SetNum(RedBoxOverlay.NumPlayer, RedBoxOverlay.PlayerCount, "_NumPColor", RedBoxOverlay.ColorLime)
    RedBoxOverlay._SetNum(RedBoxOverlay.NumBot, RedBoxOverlay.BotCount, "_NumBColor", RedBoxOverlay.ColorYellow)
end

function RedBoxOverlay.UpdatePosition()
    local Slot = RedBoxOverlay.WidgetSlot
    if not Slot or not slua.isValid(Slot) then return end
    local PC = PlayerMapMarker.GetMyPlayerController()
    local hudY = 35
    local hh = RedBoxOverlay.ImgH
    if slua.isValid(PC) then
        local fromX, fromY = PlayerMapMarker.GetSnapLineStartPos(PC)
        if fromY and fromY > 0 then hudY = fromY - hh end
    end
    if RedBoxOverlay._LastY == hudY then return end
    RedBoxOverlay._LastY = hudY
    local FVector2D = import("Vector2D") or FVector2D
    pcall(function() Slot:SetPosition(FVector2D(0, hudY)) end)
end

function RedBoxOverlay.LookAtNearest(wantBot)
    pcall(function()
        local pc = PlayerMapMarker.GetMyPlayerController()
        if not pc or not slua.isValid(pc) then return end
        local AllChars = PlayerMapMarker.GetAllCharacters()
        if not AllChars then return end
        local MyKey = PlayerMapMarker.GetMyPlayerKey()
        local MyChar = nil
        pcall(function()
            local GDP = PlayerMapMarker.GetGameplayData()
            if GDP and GDP.GetLocalCharacter then MyChar = GDP.GetLocalCharacter() elseif pc.GetPawn then MyChar = pc:GetPawn() end
        end)
        local MyTeamID = PlayerMapMarker.GetTeamID(MyChar)
        local camLoc = nil
        pcall(function()
            local GS = import("GameplayStatics")
            local cm = GS and GS.GetPlayerCameraManager(pc, 0)
            if cm then camLoc = cm:GetCameraLocation() end
        end)
        if not camLoc then camLoc = PlayerMapMarker.GetMyLocation() end
        if not camLoc then return end
        local best, bestD = nil, nil
        for PlayerKey, Character in pairs(AllChars) do
            if Character and slua.isValid(Character)
                and not PlayerMapMarker.IsMe(Character, PlayerKey, MyKey)
                and PlayerMapMarker.IsAlive(Character) then
                local isAI = PlayerMapMarker.IsAI(Character) and true or false
                if isAI == (wantBot and true or false) then
                    local sameTeam = false
                    if MyTeamID ~= nil then sameTeam = (PlayerMapMarker.GetTeamID(Character) == MyTeamID) end
                    if not sameTeam then
                        local loc = nil
                        pcall(function() loc = Character:K2_GetActorLocation() end)
                        if loc then
                            local dx, dy, dz = loc.X - camLoc.X, loc.Y - camLoc.Y, loc.Z - camLoc.Z
                            local d = dx * dx + dy * dy + dz * dz
                            if not bestD or d < bestD then best, bestD = loc, d end
                        end
                    end
                end
            end
        end
        if not best then return end
        local KML = import("KismetMathLibrary")
        local FV = _G.FVector or import("Vector")
        if not (KML and FV) then return end
        local rot = KML.FindLookAtRotation(camLoc, FV(best.X, best.Y, best.Z + 60))
        if not rot then return end
        local cur = nil
        pcall(function() cur = pc:GetControlRotation() end)
        pc:SetControlRotation(FRotator(rot.Pitch, rot.Yaw, (cur and cur.Roll) or 0), "AimTouch")
    end)
end

function RedBoxOverlay.Start()
    if RedBoxOverlay.bActive and RedBoxOverlay.MainContainer and _G.MWWidgetLive(RedBoxOverlay.MainContainer) then return end
    if RedBoxOverlay.MainContainer then RedBoxOverlay.Stop() end
    if RedBoxOverlay.Create() then
        RedBoxOverlay.bActive = true
        pcall(function() RedBoxOverlay.MainContainer:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
    end
end

function RedBoxOverlay.Stop()
    RedBoxOverlay.bActive = false
    if RedBoxOverlay.MainContainer and slua.isValid(RedBoxOverlay.MainContainer) then
        pcall(function()
            RedBoxOverlay.MainContainer:RemoveFromParent()
            RedBoxOverlay.MainContainer:ConditionalBeginDestroy()
        end)
    end
    RedBoxOverlay.MainContainer = nil
    RedBoxOverlay.WidgetSlot = nil
    RedBoxOverlay._LastY = nil
    RedBoxOverlay.TextBlockPlayer = nil
    RedBoxOverlay.TextBlockBot = nil
    RedBoxOverlay.NumPlayer = nil
    RedBoxOverlay.NumBot = nil
    RedBoxOverlay._NumPColor = nil ; RedBoxOverlay._NumBColor = nil
    RedBoxOverlay._NumPColorT = nil ; RedBoxOverlay._NumBColorT = nil
    RedBoxOverlay._CachedPosVec = nil
end

_G.RedBoxOverlay = RedBoxOverlay


