_G._MWIconTex = _G._MWIconTex or {}
function _G.MWB64Decode(b64)
    local out = {}
    local map = _G._MWB64Map
    if not map then
        map = {}
        local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        for i = 1, 64 do map[chars:byte(i)] = i - 1 end
        _G._MWB64Map = map
    end
    local n, i = #b64, 1
    while i <= n do
        local a, b, c, d = map[b64:byte(i)], map[b64:byte(i + 1)], map[b64:byte(i + 2)], map[b64:byte(i + 3)]
        if a == nil or b == nil then break end
        local v = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
        out[#out + 1] = string.char(math.floor(v / 65536) % 256)
        if c ~= nil then out[#out + 1] = string.char(math.floor(v / 256) % 256) end
        if d ~= nil then out[#out + 1] = string.char(v % 256) end
        i = i + 4
    end
    return table.concat(out)
end

function _G.MWIconResetCache()
    _G._MWIconTex = {}
    _G._LineImgFailedT = nil
    _G._FOVImgFailed = nil
    _G._FOVImgFailedT = nil
    _G._HeadRingFailedT = nil
end

_G.MWIconPreload = { keys = nil, idx = 0, gen = nil, holders = {}, PerFrame = 2 }
function _G.MWIconPreload.Reset()
    local P = _G.MWIconPreload
    P.keys = nil; P.idx = 0; P.gen = nil; P.holders = {}
end
function _G.MWIconPreload.Tick()
    local P, H = _G.MWIconPreload, _G.MWHud
    if not H or not H.canvas then if P.gen then P.Reset() end return end
    if P.gen ~= H.gen then
        P.Reset(); P.gen = H.gen
        P.keys = {}
        for k in pairs(_G.MWIconB64) do P.keys[#P.keys + 1] = k end
        table.sort(P.keys)
    end
    if not P.keys or P.idx >= #P.keys then return end
    local canvas = H.canvas
    if not slua.isValid(canvas) then return end
    for _ = 1, P.PerFrame do
        P.idx = P.idx + 1
        local key = P.keys[P.idx]
        if not key then return end
        local tex = _G.MWIconTexture(key)
        if tex then
            pcall(function()
                local img = CGame:NewObjectFromPath("/Script/UMG.Image", canvas)
                if not img or not slua.isValid(img) then return end
                img:SetBrushFromTexture(tex, false)
                img:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                local slot = canvas:AddChildToCanvas(img)
                if slot then pcall(function() slot:SetAutoSize(false); slot:SetSize(FVector2D(1, 1)); slot:SetPosition(FVector2D(-50, -50)) end) end
                if not PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs = {} end
                PlayerMapMarker._ProtectedWidgetStrs[tostring(img)] = true
                P.holders[#P.holders + 1] = img
            end)
        end
    end
end

function _G.MWIconTexture(key)
    local cached = _G._MWIconTex[key]
    if cached ~= nil then
        if cached == false then return nil end
        if type(cached) == "number" then
            if _G.RealNow() < cached then return nil end
        elseif slua.isValid(cached) then return cached end
        _G._MWIconTex[key] = nil
    end
    local b64 = _G.MWIconB64[key]
    if not b64 then _G._MWIconTex[key] = false return nil end
    local tex = nil
    local written = {}
    pcall(function()
        local bytes = _G.MWB64Decode(b64)
        _G._MWIconLoadN = (_G._MWIconLoadN or 0) + 1
        local fname = "mw_icon_" .. key .. "_" .. tostring(_G._MWIconLoadN) .. ".png"
        for _, path in ipairs(GetConfigPaths(fname)) do
            local f = io.open(path, "wb")
            if f then f:write(bytes) f:close() written[1] = path break end
        end
        local LT = import("LoadTexture")
        local BH = import("BusinessHelper")
        if not LT then return end
        for _, path in ipairs(written) do
            local cands = { path }
            pcall(function() if BH and BH.GetMobileBasePath then local mp = BH.GetMobileBasePath(path); if mp and mp ~= "" then cands[#cands + 1] = mp end end end)
            for _, cp in ipairs(cands) do
                pcall(function() tex = LT.GetTexture2DFromDiskFile(cp) end)
                if tex and slua.isValid(tex) then return end
                tex = nil
            end
        end
    end)
    for _, path in ipairs(written) do pcall(os.remove, path) end
    if tex and slua.isValid(tex) then _G._MWIconTex[key] = tex return tex end
    _G._MWIconTex[key] = _G.RealNow() + 3.0
    return nil
end

function _G.MWIconImageAt(canvas, x, y, w, h, key, ax, ay, z)
    local tex = _G.MWIconTexture(key)
    if not tex then return nil end
    local img = nil
    pcall(function() img = CGame:NewObjectFromPath("/Script/UMG.Image", canvas) end)
    if not img or not slua.isValid(img) then return nil end
    local ok = false
    pcall(function() img:SetBrushFromTexture(tex, false); ok = true end)
    if not ok then return nil end
    pcall(function() img:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end)
    local slot = nil
    pcall(function() slot = canvas:AddChildToCanvas(img) end)
    if slot then
        pcall(function() slot:SetAutoSize(false) end)
        pcall(function() slot:SetSize(FVector2D and FVector2D(w, h) or {X=w, Y=h}) end)
        pcall(function() slot:SetPosition(FVector2D and FVector2D(x, y) or {X=x, Y=y}) end)
        pcall(function() slot:SetAlignment(FVector2D and FVector2D(ax or 0, ay or 0) or {X=ax or 0, Y=ay or 0}) end)
        pcall(function() slot:SetZOrder(z or 0) end)
    end
    if not PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs = {} end
    PlayerMapMarker._ProtectedWidgetStrs[tostring(img)] = true
    return { w = img, slot = slot, key = key }
end

function _G.MWIconImage(canvas, cx, cy, size, key)
    local tex = _G.MWIconTexture(key)
    if not tex then return nil end
    local img = nil
    pcall(function() img = CGame:NewObjectFromPath("/Script/UMG.Image", canvas) end)
    if not img or not slua.isValid(img) then return nil end
    local ok = false
    pcall(function() img:SetBrushFromTexture(tex, false); ok = true end)
    if not ok then return nil end
    pcall(function() img:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end)
    local slot = nil
    pcall(function() slot = canvas:AddChildToCanvas(img) end)
    if slot then
        pcall(function() slot:SetAutoSize(false) end)
        pcall(function() slot:SetSize(FVector2D and FVector2D(size, size) or {X=size, Y=size}) end)
        pcall(function() slot:SetPosition(FVector2D and FVector2D(cx, cy) or {X=cx, Y=cy}) end)
        pcall(function() slot:SetAlignment(FVector2D and FVector2D(0.5, 0.5) or {X=0.5, Y=0.5}) end)
        pcall(function() slot:SetZOrder(999) end)
    end
    if not PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs = {} end
    PlayerMapMarker._ProtectedWidgetStrs[tostring(img)] = true
    return { w = img, slot = slot, key = key }
end

function _G.MWWidgetLive(w)
    if not w or not slua.isValid(w) then return false end
    local ok, parent = pcall(w.GetParent, w)
    if not ok or not parent or not slua.isValid(parent) then return false end
    return true
end

function _G.MWIconSet(item, key)
    if not item or not item.w or not slua.isValid(item.w) or item.key == key then return end
    local tex = _G.MWIconTexture(key)
    if not tex then return end
    pcall(function() item.w:SetBrushFromTexture(tex, false) end)
    item.key = key
end


local SpeedHackButton = {
    _created = false,
    _held = false,
    _segments = {},
    _label = nil,
    _labelSlot = nil,
    _button = nil,
    _buttonSlot = nil,
    _centerX = 0,
    _centerY = 0,
    _radius = 35,
}

function SpeedHackButton._LevelText()
    return "Speed"
end

function SpeedHackButton.UpdateLabel()
    local txt = SpeedHackButton._label
    if not txt or not slua.isValid(txt) then return end
    local want = SpeedHackButton._LevelText()
    if SpeedHackButton._labelText == want then return end
    SpeedHackButton._labelText = want
    pcall(function() txt:SetText(want) end)
end

function SpeedHackButton.Create()
    if SpeedHackButton._created and SpeedHackButton._img and _G.MWWidgetLive(SpeedHackButton._img.w) then return true end
    SpeedHackButton._created = false
    SpeedHackButton._segments = {}
    SpeedHackButton._shown = nil

    local canvas = PlayerMapMarker.ESPCanvas
    if not canvas or not Game:IsValid(canvas) then
        if not PlayerMapMarker.InitESPCanvas() then return false end
        canvas = PlayerMapMarker.ESPCanvas
    end
    if not canvas then return false end

    local FLinearColor = import("LinearColor") or FLinearColor
    local FVector2D = import("Vector2D") or FVector2D
    local FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor")

    local PC = PlayerMapMarker.GetMyPlayerController()
    local w, h = 1920, 1080
    pcall(function() if PC then w, h = PlayerMapMarker.GetDynamicViewportSize(PC) end end)
    local R = SpeedHackButton._radius
    local cx = w * 0.03 + R
    local cy = h * 0.25
    SpeedHackButton._centerX = cx
    SpeedHackButton._centerY = cy

    SpeedHackButton._img = _G.MWIconImage(canvas, cx, cy, R * 2 + 6, "speed_off")
    local segments = {}
    SpeedHackButton._segments = segments

    pcall(function()
        local txt = CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas)
        if not txt or not slua.isValid(txt) then return end
        txt:SetText(SpeedHackButton._LevelText())
        SpeedHackButton._labelText = SpeedHackButton._LevelText()
        local white = FLinearColor(1.0, 1.0, 1.0, 0.9)
        if FSlateColor then txt:SetColorAndOpacity(FSlateColor(white)) else txt:SetColorAndOpacity(white) end
        _G.MWTextOutline(txt, 1)
        if txt.Font then
            local font = txt.Font
            font.Size = 13
            txt.Font = font
        end
        pcall(function() txt:SetJustification(1) end)
        txt:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
        local txtSlot = canvas:AddChildToCanvas(txt)
        if txtSlot then
            pcall(function() txtSlot:SetAutoSize(true) end)
            pcall(function() txtSlot:SetPosition(FVector2D(cx, cy + R + 6)) end)
            pcall(function() txtSlot:SetAlignment(FVector2D(0.5, 0.0)) end)
            pcall(function() txtSlot:SetZOrder(1001) end)
        end
        SpeedHackButton._label = txt
        SpeedHackButton._labelSlot = txtSlot
        if not PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs = {} end
        PlayerMapMarker._ProtectedWidgetStrs[tostring(txt)] = true
    end)

    pcall(function()
        local btn = CGame:NewObjectFromPath("/Script/UMG.Button", canvas)
        if not btn or not slua.isValid(btn) then return end
        local transparent = FLinearColor(0, 0, 0, 0)
        pcall(function() btn:SetBackgroundColor(transparent) end)
        pcall(function() btn.WidgetStyle.Normal.TintColor = FSlateColor(transparent) end)
        pcall(function() btn.WidgetStyle.Hovered.TintColor = FSlateColor(transparent) end)
        pcall(function() btn.WidgetStyle.Pressed.TintColor = FSlateColor(transparent) end)
        pcall(function() btn:SetBrushColor(transparent) end)
        pcall(function() btn.bIsFocusable = false end)
        pcall(function() btn.IsFocusable = false end)
        btn.OnPressed:Add(function()
            SpeedHackButton._held = true
            SpeedHackButton._UpdateColor(true)
        end)
        btn.OnReleased:Add(function()
            SpeedHackButton._held = false
            SpeedHackButton._UpdateColor(false)
        end)
        local btnSlot = canvas:AddChildToCanvas(btn)
        if btnSlot then
            local btnSize = R * 2 + 20
            pcall(function() btnSlot:SetAutoSize(false) end)
            pcall(function() btnSlot:SetPosition(FVector2D(cx, cy)) end)
            pcall(function() btnSlot:SetSize(FVector2D(btnSize, btnSize)) end)
            pcall(function() btnSlot:SetAlignment(FVector2D(0.5, 0.5)) end)
            pcall(function() btnSlot:SetZOrder(1000) end)
        end
        SpeedHackButton._button = btn
        SpeedHackButton._buttonSlot = btnSlot
        if not PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs = {} end
        PlayerMapMarker._ProtectedWidgetStrs[tostring(btn)] = true
    end)

    SpeedHackButton._created = true
    SpeedHackButton._shown = nil
    return true
end


function SpeedHackButton.IsHeld()
    if not SpeedHackButton._created then return false end
    return SpeedHackButton._held
end

function SpeedHackButton._UpdateColor(isHeld)
    if SpeedHackButton._img then _G.MWIconSet(SpeedHackButton._img, isHeld and "speed_on" or "speed_off") end
    local FLinearColor = import("LinearColor") or FLinearColor
    local color
    if isHeld then
        color = FLinearColor(0.1, 0.75, 0.15, 0.55)
    else
        color = FLinearColor(0.3, 0.3, 0.3, 0.5)
    end
    for _, seg in ipairs(SpeedHackButton._segments) do
        if seg.Widget and slua.isValid(seg.Widget) then
            pcall(function() seg.Widget:SetBrushColor(color) end)
        end
    end
end

function SpeedHackButton.Show()
    if not SpeedHackButton._created or not (SpeedHackButton._img and _G.MWWidgetLive(SpeedHackButton._img.w)) then SpeedHackButton.Create() end
    SpeedHackButton.UpdateLabel()
    if SpeedHackButton._shown == true then return end
    SpeedHackButton._shown = true
    if SpeedHackButton._img and slua.isValid(SpeedHackButton._img.w) then pcall(function() SpeedHackButton._img.w:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end) end
    for _, seg in ipairs(SpeedHackButton._segments) do
        if seg.Widget and slua.isValid(seg.Widget) then
            pcall(function() seg.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end)
        end
    end
    if SpeedHackButton._label and slua.isValid(SpeedHackButton._label) then
        pcall(function() SpeedHackButton._label:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end)
    end
    if SpeedHackButton._button and slua.isValid(SpeedHackButton._button) then
        pcall(function() SpeedHackButton._button:SetWidgetVisibility(UEnums.ESlateVisibility.Visible) end)
    end
end

function SpeedHackButton.Hide()
    SpeedHackButton._held = false
    if SpeedHackButton._shown == false then return end
    SpeedHackButton._shown = false
    if SpeedHackButton._img and slua.isValid(SpeedHackButton._img.w) then pcall(function() SpeedHackButton._img.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
    for _, seg in ipairs(SpeedHackButton._segments) do
        if seg.Widget and slua.isValid(seg.Widget) then
            pcall(function() seg.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
        end
    end
    if SpeedHackButton._label and slua.isValid(SpeedHackButton._label) then
        pcall(function() SpeedHackButton._label:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    end
    if SpeedHackButton._button and slua.isValid(SpeedHackButton._button) then
        pcall(function() SpeedHackButton._button:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    end
end

_G.SpeedHackButton = SpeedHackButton


