    BulletTrackButton._colorOn = nil

    local canvas = PlayerMapMarker.ESPCanvas
    if not canvas or not Game:IsValid(canvas) then
        if not PlayerMapMarker.InitESPCanvas() then return false end
        canvas = PlayerMapMarker.ESPCanvas
    end
    if not canvas then return false end

    local FLinearColor = import("LinearColor") or FLinearColor
    local FVector2D = import("Vector2D") or FVector2D
    local FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor")

    local PC = PlayerMapMarker.GetMyPlayerController()
    local w, h = 1920, 1080
    pcall(function() if PC then w, h = PlayerMapMarker.GetDynamicViewportSize(PC) end end)
    local R = BulletTrackButton._radius
    local cx = w * 0.03 + R + (R * 2 + 30)
    local cy = h * 0.25

    BulletTrackButton._img = _G.MWIconImage(canvas, cx, cy, R * 2 + 6, "mb_off")
    local segments = {}
    BulletTrackButton._segments = segments

    pcall(function()
        local txt = CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas)
        if not txt or not slua.isValid(txt) then return end
        txt:SetText("Bullet Track")
        local white = FLinearColor(1.0, 1.0, 1.0, 0.9)
        if FSlateColor then txt:SetColorAndOpacity(FSlateColor(white)) else txt:SetColorAndOpacity(white) end
        _G.MWTextOutline(txt, 1)
        if txt.Font then
            local font = txt.Font
            font.Size = 13
            txt.Font = font
        end
        pcall(function() txt:SetJustification(1) end)
        txt:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
        local txtSlot = canvas:AddChildToCanvas(txt)
        if txtSlot then
            pcall(function() txtSlot:SetAutoSize(true) end)
            pcall(function() txtSlot:SetPosition(FVector2D(cx, cy + R + 6)) end)
            pcall(function() txtSlot:SetAlignment(FVector2D(0.5, 0.0)) end)
            pcall(function() txtSlot:SetZOrder(1001) end)
        end
        BulletTrackButton._label = txt
        BulletTrackButton._labelSlot = txtSlot
        if not PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs = {} end
        PlayerMapMarker._ProtectedWidgetStrs[tostring(txt)] = true
    end)

    pcall(function()
        local btn = CGame:NewObjectFromPath("/Script/UMG.Button", canvas)
        if not btn or not slua.isValid(btn) then return end
        local transparent = FLinearColor(0, 0, 0, 0)
        pcall(function() btn:SetBackgroundColor(transparent) end)
        pcall(function() btn.WidgetStyle.Normal.TintColor = FSlateColor(transparent) end)
        pcall(function() btn.WidgetStyle.Hovered.TintColor = FSlateColor(transparent) end)
        pcall(function() btn.WidgetStyle.Pressed.TintColor = FSlateColor(transparent) end)
        pcall(function() btn:SetBrushColor(transparent) end)
        pcall(function() btn.bIsFocusable = false end)
        pcall(function() btn.IsFocusable = false end)
        btn.OnClicked:Add(function()
            _G.MWConfig.BulletTrack = not _G.MWConfig.BulletTrack
            BulletTrackButton.Sync()
        end)
        local btnSlot = canvas:AddChildToCanvas(btn)
        if btnSlot then
            local btnSize = R * 2 + 20
            pcall(function() btnSlot:SetAutoSize(false) end)
            pcall(function() btnSlot:SetPosition(FVector2D(cx, cy)) end)
            pcall(function() btnSlot:SetSize(FVector2D(btnSize, btnSize)) end)
            pcall(function() btnSlot:SetAlignment(FVector2D(0.5, 0.5)) end)
            pcall(function() btnSlot:SetZOrder(1000) end)
        end
        BulletTrackButton._button = btn
        BulletTrackButton._buttonSlot = btnSlot
        if not PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs = {} end
        PlayerMapMarker._ProtectedWidgetStrs[tostring(btn)] = true
    end)

    BulletTrackButton._created = true
    return true
end


function BulletTrackButton.Sync()
    local on = _G.MWConfig.BulletTrack and true or false
    if BulletTrackButton._colorOn == on then return end
    BulletTrackButton._colorOn = on
    if BulletTrackButton._img then _G.MWIconSet(BulletTrackButton._img, on and "mb_on" or "mb_off") end
    local FLinearColor = import("LinearColor") or FLinearColor
    local color = on and FLinearColor(0.1, 0.75, 0.15, 0.55) or FLinearColor(0.3, 0.3, 0.3, 0.5)
    for _, seg in ipairs(BulletTrackButton._segments) do
        if seg.Widget and slua.isValid(seg.Widget) then
            pcall(function() seg.Widget:SetBrushColor(color) end)
        end
    end
end

function BulletTrackButton.Show()
    if not BulletTrackButton.Create() then return end
    BulletTrackButton.Sync()
    if BulletTrackButton._shown == true then return end
    BulletTrackButton._shown = true
    if BulletTrackButton._img and slua.isValid(BulletTrackButton._img.w) then pcall(function() BulletTrackButton._img.w:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end) end
    for _, seg in ipairs(BulletTrackButton._segments) do
        if seg.Widget and slua.isValid(seg.Widget) then
            pcall(function() seg.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end)
        end
    end
    if BulletTrackButton._label and slua.isValid(BulletTrackButton._label) then
        pcall(function() BulletTrackButton._label:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end)
    end
    if BulletTrackButton._button and slua.isValid(BulletTrackButton._button) then
        pcall(function() BulletTrackButton._button:SetWidgetVisibility(UEnums.ESlateVisibility.Visible) end)
    end
end

function BulletTrackButton.Hide()
    if not BulletTrackButton._created then return end
    if BulletTrackButton._shown == false then return end
    BulletTrackButton._shown = false
    if BulletTrackButton._img and slua.isValid(BulletTrackButton._img.w) then pcall(function() BulletTrackButton._img.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
    for _, seg in ipairs(BulletTrackButton._segments) do
        if seg.Widget and slua.isValid(seg.Widget) then
            pcall(function() seg.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
        end
    end
    if BulletTrackButton._label and slua.isValid(BulletTrackButton._label) then
        pcall(function() BulletTrackButton._label:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    end
    if BulletTrackButton._button and slua.isValid(BulletTrackButton._button) then
        pcall(function() BulletTrackButton._button:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    end
end

_G.BulletTrackButton = BulletTrackButton
end

