function PlayerMapMarker._NewLabelText(canvas, fontSize, color, ax, ay)
    local txt = nil
    pcall(function() txt = CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas) end)
    if not txt or not slua.isValid(txt) then return nil end
    local FSlateColor = PlayerMapMarker._SlateColorClass
    if FSlateColor == nil then FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor") or false; PlayerMapMarker._SlateColorClass = FSlateColor end
    pcall(function() txt:SetText("") end)
    pcall(function() if FSlateColor then txt:SetColorAndOpacity(FSlateColor(color)) else txt:SetColorAndOpacity(color) end end)
    pcall(function() local f = txt.Font; f.Size = fontSize; txt.Font = f end)
    _G.MWTextOutline(txt, 1)
    pcall(function() txt:SetJustification(1) end)
    pcall(function() txt:SetShadowColorAndOpacity(PlayerMapMarker.LabelShadow) end)
    pcall(function() txt:SetShadowOffset(FVector2D and FVector2D(1, 1) or {X=1, Y=1}) end)
    pcall(function() txt:SetRenderTransformPivot(FVector2D and FVector2D(ax, ay) or {X=ax, Y=ay}) end)
    pcall(function() txt:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    local slot = nil
    pcall(function() slot = canvas:AddChildToCanvas(txt) end)
    if slot then
        pcall(function() slot:SetAutoSize(true) end)
        pcall(function() slot:SetAlignment(FVector2D and FVector2D(ax, ay) or {X=ax, Y=ay}) end)
        pcall(function() slot:SetZOrder(4) end)
    end
    if not PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs = {} end
    PlayerMapMarker._ProtectedWidgetStrs[tostring(txt)] = true
    return { w = txt, slot = slot, vis = false, text = nil, sc = nil, pos = FVector2D and FVector2D(0, 0) or {X=0, Y=0}, scv = FVector2D and FVector2D(1, 1) or {X=1, Y=1}, x = nil, y = nil }
end

function PlayerMapMarker._NewWeaponIcon(canvas, z)
    local img = nil
    pcall(function() img = CGame:NewObjectFromPath("/Script/UMG.Image", canvas) end)
    if not img or not slua.isValid(img) then return nil end
    pcall(function() img:SetRenderTransformPivot(FVector2D and FVector2D(1.0, 1.0) or {X=1, Y=1}) end)
    pcall(function() img:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    local slot = nil
    pcall(function() slot = canvas:AddChildToCanvas(img) end)
    if slot then
        pcall(function() slot:SetAutoSize(false) end)
        pcall(function() slot:SetSize(FVector2D and FVector2D(PlayerMapMarker.WpnIconW, PlayerMapMarker.WpnIconH) or {X=PlayerMapMarker.WpnIconW, Y=PlayerMapMarker.WpnIconH}) end)
        pcall(function() slot:SetAlignment(FVector2D and FVector2D(1.0, 1.0) or {X=1, Y=1}) end)
        pcall(function() slot:SetZOrder(z or 4) end)
    end
    if not PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs = {} end
    PlayerMapMarker._ProtectedWidgetStrs[tostring(img)] = true
    return { w = img, slot = slot, vis = false, sc = nil, pos = FVector2D and FVector2D(0, 0) or {X=0, Y=0}, scv = FVector2D and FVector2D(1, 1) or {X=1, Y=1}, x = nil, y = nil, loadedID = nil, ok = false }
end

function PlayerMapMarker._NewTeamDot(canvas)
    local b = nil
    pcall(function() b = CGame:NewObjectFromPath("/Script/UMG.Border", canvas) end)
    if not b or not slua.isValid(b) then return nil end
    pcall(function() b:SetRenderTransformPivot(FVector2D and FVector2D(1.0, 0.5) or {X=1, Y=0.5}) end)
    pcall(function() b:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    local slot = nil
    pcall(function() slot = canvas:AddChildToCanvas(b) end)
    if slot then
        pcall(function() slot:SetAutoSize(false) end)
        pcall(function() slot:SetSize(FVector2D and FVector2D(PlayerMapMarker.TeamDotSize, PlayerMapMarker.TeamDotSize) or {X=PlayerMapMarker.TeamDotSize, Y=PlayerMapMarker.TeamDotSize}) end)
        pcall(function() slot:SetAlignment(FVector2D and FVector2D(1.0, 0.5) or {X=1, Y=0.5}) end)
        pcall(function() slot:SetZOrder(4) end)
    end
    if not PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs = {} end
    PlayerMapMarker._ProtectedWidgetStrs[tostring(b)] = true
    return { w = b, slot = slot, vis = false, color = nil, sc = nil, pos = FVector2D and FVector2D(0, 0) or {X=0, Y=0}, scv = FVector2D and FVector2D(1, 1) or {X=1, Y=1}, x = nil, y = nil }
end

function PlayerMapMarker._LabelSet(item, show, x, y, sc)
    if not item or not item.w or not slua.isValid(item.w) then return end
    if not show then
        if item.vis ~= false then item.vis = false; item.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end
        return
    end
    if item.vis ~= true then item.vis = true; item.w:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end
    if item.slot and (item.x ~= x or item.y ~= y) then
        item.x, item.y = x, y
        item.pos.X, item.pos.Y = x, y
        item.slot:SetPosition(item.pos)
    end
    if sc and item.sc ~= sc then
        item.sc = sc
        item.scv.X, item.scv.Y = sc, sc
        item.w:SetRenderScale(item.scv)
    end
end

function PlayerMapMarker._LabelText(item, text)
    if not item or not item.w or item.text == text then return end
    item.text = text
    pcall(item.w.SetText, item.w, text)
end

function PlayerMapMarker._LabelColor(item, color)
    if not item or not item.w or item.color == color then return end
    item.color = color
    local FSlateColor = PlayerMapMarker._SlateColorClass
    pcall(function() if FSlateColor then item.w:SetColorAndOpacity(FSlateColor(color)) else item.w:SetColorAndOpacity(color) end end)
end

function PlayerMapMarker.GetLabels(KeyStr)
    local lb = PlayerMapMarker.Labels[KeyStr]
    if lb and lb.name and lb.name.w and slua.isValid(lb.name.w) then return lb end
    local canvas = PlayerMapMarker.ESPCanvas
    if not canvas or not Game:IsValid(canvas) then return nil end
    lb = {
        name  = PlayerMapMarker._NewLabelText(canvas, PlayerMapMarker.LabelFontName, PlayerMapMarker.LabelColorPlayer, 0.5, 0.0),
        dist  = PlayerMapMarker._NewLabelText(canvas, PlayerMapMarker.LabelFontDist, PlayerMapMarker.LabelColorDist, 0.5, 0.0),
        wpn   = PlayerMapMarker._NewLabelText(canvas, PlayerMapMarker.LabelFontWpn, PlayerMapMarker.LabelColorWpn, 0.0, 1.0),
        wicon = PlayerMapMarker._NewWeaponIcon(canvas),
        wsh1 = PlayerMapMarker._NewWeaponIcon(canvas, 3),
        tring = PlayerMapMarker._NewTagImage(canvas, "team_dot", 3, PlayerMapMarker.TeamDotRingSize),
        tdot  = PlayerMapMarker._NewTagImage(canvas, "team_dot", 4),
        wpnT = 0, wpnName = nil, wpnID = nil, distM = nil, teamID = nil,
    }
    if lb.wsh1 then pcall(lb.wsh1.w.SetColorAndOpacity, lb.wsh1.w, PlayerMapMarker.WpnIconOutlineColor) end
    if lb.tring then pcall(lb.tring.w.SetColorAndOpacity, lb.tring.w, PlayerMapMarker.TeamDotRingColor) end
    PlayerMapMarker.Labels[KeyStr] = lb
    return lb
end

PlayerMapMarker._LabelKeys = {"name","dist","wpn","wicon","tdot","tring","wsh1"}

function PlayerMapMarker._WpnOutlineSync(lb)
    if not lb.wicon or not lb.wicon.w or not slua.isValid(lb.wicon.w) then return end
    local iw = (lb.wicon.loadedID == 0) and PlayerMapMarker.FistIconW or PlayerMapMarker.WpnIconW
    local ih = (lb.wicon.loadedID == 0) and PlayerMapMarker.FistIconH or PlayerMapMarker.WpnIconH
    local sz = FVector2D and FVector2D(iw, ih) or {X=iw, Y=ih}
    local sh = lb.wsh1
    if sh and sh.w and slua.isValid(sh.w) then
        pcall(function()
            sh.w:SetBrush(lb.wicon.w.Brush)
            if sh.slot then sh.slot:SetSize(sz) end
            if sh.w.SetDesiredSizeOverride then sh.w:SetDesiredSizeOverride(sz) end
            sh.w:SetColorAndOpacity(PlayerMapMarker.WpnIconOutlineColor)
        end)
        sh.vis = nil
    end
end

function PlayerMapMarker._NewTagImage(canvas, key, z, size)
    size = size or PlayerMapMarker.TeamDotSize
    local img = _G.MWIconImageAt(canvas, 0, 0, size, size, key, 0.5, 1.0, z or 3)
    if not img then return nil end
    pcall(function() img.w:SetRenderTransformPivot(FVector2D and FVector2D(0.5, 1.0) or {X=0.5, Y=1}) end)
    pcall(function() img.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    img.vis = false; img.x = nil; img.y = nil; img.sc = nil; img.color = nil
    img.pos = FVector2D and FVector2D(0, 0) or {X=0, Y=0}
    img.scv = FVector2D and FVector2D(1, 1) or {X=1, Y=1}
    return img
end
function PlayerMapMarker.HideLabels(KeyStr)
    local lb = PlayerMapMarker.Labels[KeyStr]
    if not lb then return end
    for _, k in ipairs(PlayerMapMarker._LabelKeys) do PlayerMapMarker._LabelSet(lb[k], false) end
end

function PlayerMapMarker.RemoveLabels(KeyStr)
    local lb = PlayerMapMarker.Labels[KeyStr]
    if not lb then return end
    for _, k in ipairs(PlayerMapMarker._LabelKeys) do
        local it = lb[k]
        if it and it.w and slua.isValid(it.w) then
            if PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs[tostring(it.w)] = nil end
            pcall(function() it.w:RemoveFromParent() end)
        end
    end
    PlayerMapMarker.Labels[KeyStr] = nil
end

function PlayerMapMarker.ClearAllLabels()
    for KeyStr in pairs(PlayerMapMarker.Labels) do PlayerMapMarker.RemoveLabels(KeyStr) end
    PlayerMapMarker.Labels = {}
end

function PlayerMapMarker._WeaponLabel(Character)
    local info = PlayerMapMarker.GetCharacterWeaponInfo(Character)
    if not info then return nil end
    local n = info.WeaponName
    if type(n) == "string" and n ~= "" then return n end
    local id = tonumber(info.WeaponID)
    if id and id > 0 and ItemDatabase and ItemDatabase[id] then return ItemDatabase[id].name end
    return nil
end

function PlayerMapMarker._LabelsBody(KeyStr, Character, ESPData, cx, y1, y2, sc)
    local cfg = _G.MWConfig
    local lb = PlayerMapMarker.GetLabels(KeyStr)
    if not lb then return end
    local knocked = Character.HealthStatus == 1
    if ESPData then ESPData._Knock = knocked end
    local ts = sc / (PlayerMapMarker.ESPBaseScale or 0.9)
    if ts < PlayerMapMarker.LabelTextMin then ts = PlayerMapMarker.LabelTextMin elseif ts > PlayerMapMarker.LabelTextMax then ts = PlayerMapMarker.LabelTextMax end
    ts = math.floor(ts * 50 + 0.5) / 50
    local gap = PlayerMapMarker.LabelGap
    local isBot = ESPData and ESPData.IsBot or false

    local rowH = 0
    if cfg.EspPlayerWeapon then
        local now = _G.RealNow()
        if now - (lb.wpnT or 0) >= 0.5 then
            lb.wpnT = now
            local info = nil
            pcall(function() info = PlayerMapMarker.GetCharacterWeaponInfo(Character) end)
            local wid = info and tonumber(info.WeaponID) or nil
            local wname = nil
            if info then
                if type(info.WeaponName) == "string" and info.WeaponName ~= "" then wname = info.WeaponName
                elseif wid and wid > 0 and ItemDatabase and ItemDatabase[wid] then wname = ItemDatabase[wid].name end
            end
            lb.wpnName = wname
            if wname then PlayerMapMarker._LabelText(lb.wpn, wname) end
            if lb.wicon and wid and wid > 0 then
                if lb.wicon.loadedID ~= wid then
                    lb.wicon.loadedID = wid
                    local ok = false
                    pcall(function() ok = PlayerMapMarker.ApplyWeaponIconToImage(lb.wicon.w, info) end)
                    lb.wicon.ok = ok and true or false
                    pcall(function()
                        local sz = FVector2D and FVector2D(PlayerMapMarker.WpnIconW, PlayerMapMarker.WpnIconH) or {X=PlayerMapMarker.WpnIconW, Y=PlayerMapMarker.WpnIconH}
                        if lb.wicon.slot then lb.wicon.slot:SetSize(sz) end
                        if lb.wicon.w.SetDesiredSizeOverride then lb.wicon.w:SetDesiredSizeOverride(sz) end
                    end)
                    lb.wicon.vis = nil
                end
            elseif lb.wicon then
                if lb.wicon.loadedID ~= 0 then
                    lb.wicon.loadedID = 0
                    local ok = false
                    pcall(function()
                        local util = require("client.slua_ui_framework.util")
                        local r = util.SetTexture(lb.wicon.w, PlayerMapMarker.FistIconPath, { sync = true, bMatchSize = false })
                        ok = r ~= nil
                        if not ok and lb.wicon.w.SetBrushResourceFromPathSync then lb.wicon.w:SetBrushResourceFromPathSync(PlayerMapMarker.FistIconPath, false); ok = true end
                    end)
                    lb.wicon.ok = ok
                    pcall(function()
                        local sz = FVector2D and FVector2D(PlayerMapMarker.FistIconW, PlayerMapMarker.FistIconH) or {X=PlayerMapMarker.FistIconW, Y=PlayerMapMarker.FistIconH}
                        if lb.wicon.slot then lb.wicon.slot:SetSize(sz) end
                        if lb.wicon.w.SetDesiredSizeOverride then lb.wicon.w:SetDesiredSizeOverride(sz) end
                        lb.wicon.w:SetColorAndOpacity(FLinearColor and FLinearColor(1.0, 1.0, 1.0, 1.0) or {R=1, G=1, B=1, A=1})
                    end)
                    lb.wicon.vis = nil
                end
                lb.wpnName = nil
            end
        end
        local hasIcon = lb.wicon and lb.wicon.ok
        local hasName = lb.wpnName ~= nil
        if hasIcon and lb._outlineID ~= lb.wicon.loadedID then lb._outlineID = lb.wicon.loadedID; PlayerMapMarker._WpnOutlineSync(lb) end
        if hasIcon then
            local iw = (lb.wicon.loadedID == 0) and PlayerMapMarker.FistIconW or PlayerMapMarker.WpnIconW
            local ih = (lb.wicon.loadedID == 0) and PlayerMapMarker.FistIconH or PlayerMapMarker.WpnIconH
            if ih * ts > rowH then rowH = ih * ts end
            local ix, iy = cx - (hasName and 2 or -iw * ts * 0.5), y1 - gap
            PlayerMapMarker._LabelSet(lb.wicon, true, ix, iy, ts)
            local k = PlayerMapMarker.WpnIconOutlineScale
            PlayerMapMarker._LabelSet(lb.wsh1, true, ix + iw * ts * (k - 1) * 0.5, iy + ih * ts * (k - 1) * 0.5, ts * k)
        else
            PlayerMapMarker._LabelSet(lb.wicon, false)
            PlayerMapMarker._LabelSet(lb.wsh1, false)
        end
        if hasName then
            local th = (PlayerMapMarker.LabelFontWpn + 4) * ts
            if th > rowH then rowH = th end
            local dw = 0
            if not hasIcon then pcall(function() local ds = lb.wpn.w:GetDesiredSize(); dw = ds and ds.X or 0 end) end
            PlayerMapMarker._LabelSet(lb.wpn, true, hasIcon and (cx + 2) or (cx - dw * ts * 0.5), y1 - gap, ts)
        else
            PlayerMapMarker._LabelSet(lb.wpn, false)
        end
    else
        PlayerMapMarker._LabelSet(lb.wicon, false); PlayerMapMarker._LabelSet(lb.wpn, false)
        PlayerMapMarker._LabelSet(lb.wsh1, false)
    end

    local teamID = ESPData and ESPData.TeamID
    if cfg.EspPlayerTeam and teamID and lb.tdot then
        local tagY = y1 - gap - ((rowH > 0) and (rowH + PlayerMapMarker.TeamTagGap) or 0)
        if lb.teamID ~= teamID then
            lb.teamID = teamID
            local tc = PlayerMapMarker.GetTeamColor(teamID)
            lb.tdot.color = tc; pcall(lb.tdot.w.SetColorAndOpacity, lb.tdot.w, tc)
            local key = PlayerMapMarker.TeamShapeKeys[(teamID % 4) + 1] or "team_dot"
            _G.MWIconSet(lb.tdot, key)
            if lb.tring then _G.MWIconSet(lb.tring, key) end
        end
        local half = (PlayerMapMarker.TeamDotRingSize - PlayerMapMarker.TeamDotSize) * 0.5 * ts
        PlayerMapMarker._PinSet(lb.tring, true, cx, tagY + half, ts)
        PlayerMapMarker._PinSet(lb.tdot, true, cx, tagY, ts)
    else
        PlayerMapMarker._PinSet(lb.tdot, false); PlayerMapMarker._PinSet(lb.tring, false)
    end

    local nextY = y2 + gap
    if cfg.EspPlayerName then
        local nm = isBot and "BOT" or ((ESPData and ESPData.Name) or "Unknown")
        PlayerMapMarker._LabelText(lb.name, nm)
        PlayerMapMarker._LabelColor(lb.name, knocked and PlayerMapMarker.KnockColor or (isBot and PlayerMapMarker.LabelColorBot or PlayerMapMarker.LabelColorPlayer))
        PlayerMapMarker._LabelSet(lb.name, true, cx, nextY, ts)
        nextY = nextY + (PlayerMapMarker.LabelFontName + 5) * ts
    else
        PlayerMapMarker._LabelSet(lb.name, false)
    end
    if cfg.EspPlayerDistance then
        local d = ESPData and ESPData._DistCm
        if d then
            local m = d / 100
            local key = (m < 1000) and math.floor(m) or (1000000 + math.floor(m / 100))
            if lb.distM ~= key then
                lb.distM = key
                PlayerMapMarker._LabelText(lb.dist, (m < 1000) and string.format("%dm", math.floor(m)) or string.format("%.1fkm", m / 1000))
            end
            PlayerMapMarker._LabelColor(lb.dist, knocked and PlayerMapMarker.KnockColor or PlayerMapMarker.LabelColorDist)
            PlayerMapMarker._LabelSet(lb.dist, true, cx, nextY, ts)
        else
            PlayerMapMarker._LabelSet(lb.dist, false)
        end
    else
        PlayerMapMarker._LabelSet(lb.dist, false)
    end
end

PlayerMapMarker.Skel = {}
PlayerMapMarker.SkelColor = FLinearColor and FLinearColor(0.0, 1.0, 0.0, 1.0) or {R=0, G=255, B=0, A=255}
PlayerMapMarker.SkelThickness = 2.0
PlayerMapMarker.SkelSoft = false
PlayerMapMarker.SkelSoftMul = 2.0
PlayerMapMarker.SkelColorSoft = FLinearColor and FLinearColor(0.0, 1.0, 0.0, 0.35) or {R=0, G=255, B=0, A=90}
PlayerMapMarker.SkelColorBot = FLinearColor and FLinearColor(1.0, 0.9, 0.0, 1.0) or {R=255, G=230, B=0, A=255}
PlayerMapMarker.SkelColorBotSoft = FLinearColor and FLinearColor(1.0, 0.9, 0.0, 0.35) or {R=255, G=230, B=0, A=90}
PlayerMapMarker.SkelColorOcc = FLinearColor and FLinearColor(1.0, 1.0, 1.0, 1.0) or {R=255, G=255, B=255, A=255}
PlayerMapMarker.SkelColorOccSoft = FLinearColor and FLinearColor(1.0, 1.0, 1.0, 0.35) or {R=255, G=255, B=255, A=90}
PlayerMapMarker.SkelVisInterval = 0.2
PlayerMapMarker.SkelBones = {"head","neck_01","spine_03","spine_01","pelvis","upperarm_l","lowerarm_l","hand_l","upperarm_r","lowerarm_r","hand_r","thigh_l","calf_l","foot_l","thigh_r","calf_r","foot_r"}
PlayerMapMarker.SkelHeadCenterCm = 9
PlayerMapMarker.SkelHeadRadiusCm = 10
PlayerMapMarker.SkelHeadMaxR = 250
PlayerMapMarker.SkelLinks = { {18,2},{2,3},{3,4},{4,5},{2,6},{6,7},{7,8},{2,9},{9,10},{10,11},{5,12},{12,13},{13,14},{5,15},{15,16},{16,17} }

function PlayerMapMarker._HeadRingSet(sk, show, cx, cy, r, color)
    local hr = sk.headImg
    if not show then
        if hr and hr.vis ~= false then hr.vis = false; pcall(hr.w.SetWidgetVisibility, hr.w, UEnums.ESlateVisibility.Collapsed) end
        return
    end
    if not hr then
        if _G._HeadRingFailedT and (_G.RealNow() - _G._HeadRingFailedT) < 3.0 then return false end
        local canvas = DrawLine.GetCanvas()
        if not canvas then return false end
        hr = _G.MWIconImageAt(canvas, 0, 0, 10, 10, "head_ring", 0.5, 0.5, 3)
        if not hr then _G._HeadRingFailedT = _G.RealNow() return false end
        _G._HeadRingFailedT = nil
        hr.vis = false; hr.cx = nil; hr.cy = nil; hr.d = nil; hr.color = nil
        hr.pos = FVector2D and FVector2D(0, 0) or {X=0, Y=0}
        hr.size = FVector2D and FVector2D(10, 10) or {X=10, Y=10}
        sk.headImg = hr
    end
    if not slua.isValid(hr.w) then sk.headImg = nil return false end
    local d = math.floor(r * 2 + 0.5)
    if d < 8 then d = 8 end
    local key = (d <= 24) and "head_ring_s" or ((d <= 64) and "head_ring_m" or "head_ring")
    if hr.key ~= key then _G.MWIconSet(hr, key) end
    if hr.cx ~= cx or hr.cy ~= cy then hr.cx, hr.cy = cx, cy; hr.pos.X, hr.pos.Y = cx, cy; pcall(hr.slot.SetPosition, hr.slot, hr.pos) end
    if hr.d ~= d then hr.d = d; hr.size.X, hr.size.Y = d, d; pcall(hr.slot.SetSize, hr.slot, hr.size) end
    if hr.color ~= color then hr.color = color; pcall(hr.w.SetColorAndOpacity, hr.w, color) end
    if hr.vis ~= true then hr.vis = true; pcall(hr.w.SetWidgetVisibility, hr.w, UEnums.ESlateVisibility.HitTestInvisible) end
    return true
end

function PlayerMapMarker.HideSkel(KeyStr)
    local sk = PlayerMapMarker.Skel[KeyStr]
    if not sk then return end
    for _, l in pairs(sk.lines) do DrawLine.Hide(l) end
    for _, l in pairs(sk.under) do DrawLine.Hide(l) end
    PlayerMapMarker._HeadRingSet(sk, false)
end

function PlayerMapMarker.RemoveSkel(KeyStr)
    local sk = PlayerMapMarker.Skel[KeyStr]
    if not sk then return end
    for _, l in pairs(sk.lines) do DrawLine.Remove(l) end
    for _, l in pairs(sk.under) do DrawLine.Remove(l) end
    if sk.headImg and sk.headImg.w and slua.isValid(sk.headImg.w) then pcall(function() sk.headImg.w:RemoveFromParent() end) end
    sk.headImg = nil
    PlayerMapMarker.Skel[KeyStr] = nil
end

function PlayerMapMarker.ClearAllSkel()
    for KeyStr in pairs(PlayerMapMarker.Skel) do PlayerMapMarker.RemoveSkel(KeyStr) end
    PlayerMapMarker.Skel = {}
end

function PlayerMapMarker._SkelForceAnim(Character, sk)
    local now = _G.RealNow()
    if sk.flagT and (now - sk.flagT) < 0.1 then return end
    sk.flagT = now
    local m = Character.Mesh
    if not (m and slua.isValid(m)) then return end
    if m.MeshComponentUpdateFlag ~= 0 then m.MeshComponentUpdateFlag = 0 end
    if m.bEnableUpdateRateOptimizations ~= false then m.bEnableUpdateRateOptimizations = false end
    if m.bEnableUpdateRateOptimization ~= false then m.bEnableUpdateRateOptimization = false end
    if m.bNoSkeletonUpdate then m.bNoSkeletonUpdate = false end
    if m.bPauseAnims then m.bPauseAnims = false end
end

function PlayerMapMarker._SkelBody(KeyStr, Character, PC)
    local sk = PlayerMapMarker.Skel[KeyStr]
    if not sk then sk = { lines = {}, under = {}, pts = {} }; PlayerMapMarker.Skel[KeyStr] = sk end
    pcall(PlayerMapMarker._SkelForceAnim, Character, sk)
    local pts = sk.pts
    local z3 = PlayerMapMarker._Zero3
    if not z3 then z3 = {X=0, Y=0, Z=0}; PlayerMapMarker._Zero3 = z3 end
    local bones = PlayerMapMarker.SkelBones
    local headTopOk, headTopX, headTopY = false, 0, 0
    for i = 1, #bones do
        local pt = pts[i]
        if not pt then pt = { ok = false, x = 0, y = 0 }; pts[i] = pt end
        pt.ok = false
        local wp = Character:GetBonePos(bones[i], z3)
        if wp and not (wp.X == 0 and wp.Y == 0 and wp.Z == 0) then
            if i == 1 then
                local chin = pts[18]
                if not chin then chin = { ok = false, x = 0, y = 0 }; pts[18] = chin end
                local okC, cxp, cyp = PlayerMapMarker.ProjectWorldToCanvasLocalRaw(PC, wp)
                chin.ok = okC and true or false; if okC then chin.x = cxp; chin.y = cyp end
                local baseZ = wp.Z
                local cZ = baseZ + (PlayerMapMarker.SkelHeadCenterCm or 9)
                wp.Z = cZ + (PlayerMapMarker.SkelHeadRadiusCm or 10)
                headTopOk, headTopX, headTopY = PlayerMapMarker.ProjectWorldToCanvasLocalRaw(PC, wp)
                wp.Z = cZ
            end
            local okP, sx, sy = PlayerMapMarker.ProjectWorldToCanvasLocalRaw(PC, wp)
            if okP then pt.x = sx; pt.y = sy; pt.ok = true end
        end
    end
    local visible = PlayerMapMarker._LOS(KeyStr, PC, Character)
    local edB = PlayerMapMarker.ESPWidgets[KeyStr]
    local isBotS = edB and edB.IsBot or false
    local color, tk = (visible and (isBotS and PlayerMapMarker.SkelColorBot or PlayerMapMarker.SkelColor) or PlayerMapMarker.SkelColorOcc), PlayerMapMarker.SkelThickness
    local soft = PlayerMapMarker.SkelSoft
    local colorS, tkS = (visible and (isBotS and PlayerMapMarker.SkelColorBotSoft or PlayerMapMarker.SkelColorSoft) or PlayerMapMarker.SkelColorOccSoft), tk * (PlayerMapMarker.SkelSoftMul or 2.0)
    if Character.HealthStatus == 1 then color = PlayerMapMarker.KnockColor; colorS = PlayerMapMarker.KnockColor end
    local links = PlayerMapMarker.SkelLinks
    for li = 1, #links do
        local a, b = pts[links[li][1]], pts[links[li][2]]
        local line = sk.lines[li]
        if not line then line = DrawLine.Create(3); sk.lines[li] = line end
        local ul = sk.under[li]
        if soft and not ul then ul = DrawLine.Create(2); sk.under[li] = ul end
        local vis = a and b and a.ok and b.ok
        if line then
            if vis then DrawLine.Update(line, a.x, a.y, b.x, b.y, color, tk) else DrawLine.Hide(line) end
        end
        if ul then
            if vis and soft then DrawLine.Update(ul, a.x, a.y, b.x, b.y, colorS, tkS) else DrawLine.Hide(ul) end
        end
    end
    local hp = pts[1]
    if hp and hp.ok and headTopOk then
        local dx, dy = headTopX - hp.x, headTopY - hp.y
        local r = math.sqrt(dx * dx + dy * dy)
        if r < 2 then r = 2 end
        if r > (PlayerMapMarker.SkelHeadMaxR or 250) then
            PlayerMapMarker._HeadRingSet(sk, false)
        else
            PlayerMapMarker._HeadRingSet(sk, true, hp.x, hp.y, r, color)
        end
    else
        PlayerMapMarker._HeadRingSet(sk, false)
    end
end

function PlayerMapMarker._ScreenCenterCanvas(PC)
    local now = _G.RealNow()
    if PlayerMapMarker._CenterT and (now - PlayerMapMarker._CenterT) < 0.5 and PlayerMapMarker._CenterX then
        return PlayerMapMarker._CenterX, PlayerMapMarker._CenterY
    end
    local pw, ph = 0, 0
    pcall(function()
        local vs = FVector2D and FVector2D(0, 0) or {X=0, Y=0}
        PC:GetViewportSize(vs)
        if vs and vs.X and vs.X > 200 then pw, ph = vs.X, vs.Y end
    end)
    if pw <= 200 then
        pcall(function()
            local WLL = import("WidgetLayoutLibrary")
            local vs = WLL.GetViewportSize(PC)
            if vs and vs.X and vs.X > 200 then pw, ph = vs.X, vs.Y end
        end)
    end
    if pw <= 200 then pw, ph = 1920, 1080 end
    PlayerMapMarker._VpPxW, PlayerMapMarker._VpPxH = pw, ph
    local cx, cy = PlayerMapMarker.ScreenPixelToCanvasLocalRaw(PC, pw * 0.5, ph * 0.5)
    PlayerMapMarker._CenterX, PlayerMapMarker._CenterY, PlayerMapMarker._CenterT = cx, cy, now
    return cx, cy
end

PlayerMapMarker.Pins = {}
PlayerMapMarker.PinH = 28
PlayerMapMarker.PinZOff = 45
PlayerMapMarker.PinBobPx = 5
PlayerMapMarker.PinBobPeriod = 1.1
PlayerMapMarker.PinFont = 15
PlayerMapMarker.PinColor = FLinearColor and FLinearColor(1.0, 0.82, 0.0, 1.0) or {R=255, G=210, B=0, A=255}
PlayerMapMarker.AirdropIcon = "airdrop_gift"
PlayerMapMarker.AirdropSize = 32
PlayerMapMarker.AirdropColor = FLinearColor and FLinearColor(1.0, 0.0, 0.0, 1.0) or {R=255, G=0, B=0, A=255}

function PlayerMapMarker._PinSet(item, show, x, y, sc)
    if not item or not item.w or not slua.isValid(item.w) then return end
    if not show then
        if item.vis ~= false then item.vis = false; item.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end
        return
    end
    if item.vis ~= true then item.vis = true; item.w:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end
    if item.slot and (item.x ~= x or item.y ~= y) then item.x, item.y = x, y; item.pos.X, item.pos.Y = x, y; item.slot:SetPosition(item.pos) end
    if sc and item.sc ~= sc then item.sc = sc; item.scv.X, item.scv.Y = sc, sc; item.w:SetRenderScale(item.scv) end
end

function PlayerMapMarker.RemovePin(key)
    local pn = PlayerMapMarker.Pins[key]
    if not pn then return end
    for _, k in ipairs({"img", "txt"}) do
        local it = pn[k]
        if it and it.w and slua.isValid(it.w) then
            if PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs[tostring(it.w)] = nil end
            pcall(function() it.w:RemoveFromParent() end)
        end
    end
    PlayerMapMarker.Pins[key] = nil
end
function PlayerMapMarker.ClearAllPins()
    for key in pairs(PlayerMapMarker.Pins) do PlayerMapMarker.RemovePin(key) end
    PlayerMapMarker.Pins = {}
end

function PlayerMapMarker._PinBody(key, act, PC, MyLoc, now, kind)
    local pn = PlayerMapMarker.Pins[key]
    if pn and pn.kind ~= kind then PlayerMapMarker.RemovePin(key); pn = nil end
    if not pn or not (pn.img and pn.img.w and _G.MWWidgetLive(pn.img.w)) then
        local canvas = PlayerMapMarker.ESPCanvas
        if not canvas or not Game:IsValid(canvas) then
            if not PlayerMapMarker.InitESPCanvas() then return end
            canvas = PlayerMapMarker.ESPCanvas
        end
        local H = PlayerMapMarker.PinH
        local W = math.floor(H * 64 / 88 + 0.5)
        if kind == "airdrop" then H = PlayerMapMarker.AirdropSize; W = H end
        local img = _G.MWIconImageAt(canvas, 0, 0, W, H, (kind == "airdrop") and PlayerMapMarker.AirdropIcon or "crate_pin", 0.5, 1.0, 4)
        if not img then return end
        if kind == "airdrop" then pcall(img.w.SetColorAndOpacity, img.w, PlayerMapMarker.AirdropColor) end
        pcall(function() img.w:SetRenderTransformPivot(FVector2D and FVector2D(0.5, 1.0) or {X=0.5, Y=1}) end)
        pcall(function() img.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
        img.vis = false; img.x = nil; img.y = nil; img.sc = nil
        img.pos = FVector2D and FVector2D(0, 0) or {X=0, Y=0}
        img.scv = FVector2D and FVector2D(1, 1) or {X=1, Y=1}
        local txt = PlayerMapMarker._NewLabelText(canvas, PlayerMapMarker.PinFont, (kind == "airdrop") and PlayerMapMarker.AirdropColor or PlayerMapMarker.PinColor, 0.5, 1.0)
        pn = { img = img, txt = txt, distM = nil, kind = kind, h = H, loc = FVector and FVector(0, 0, 0) or {X=0, Y=0, Z=0} }
        PlayerMapMarker.Pins[key] = pn
    end
    local loc = nil
    pcall(function() loc = act:K2_GetActorLocation() end)
    if not loc then PlayerMapMarker._PinSet(pn.img, false); PlayerMapMarker._LabelSet(pn.txt, false) return end
    loc.Z = loc.Z + PlayerMapMarker.PinZOff
    local bOn, cp = PlayerMapMarker.ProjectWorldToCanvasLocal(PC, loc)
    if not bOn then PlayerMapMarker._PinSet(pn.img, false); PlayerMapMarker._LabelSet(pn.txt, false) return end
    local dcm = MyLoc and PlayerMapMarker._Dist3D(MyLoc, loc) or 2500
    local ts = 2500 / (dcm > 1 and dcm or 1)
    if ts < 0.72 then ts = 0.72 elseif ts > 1.25 then ts = 1.25 end
    ts = math.floor(ts * 50 + 0.5) / 50
    local bob = PlayerMapMarker.PinBobPx * ts * (0.5 + 0.5 * math.sin(now * 2 * math.pi / PlayerMapMarker.PinBobPeriod))
    local tipY = cp.Y - bob
    PlayerMapMarker._PinSet(pn.img, true, cp.X, tipY, ts)
    local m = math.floor(dcm / 100 + 0.5)
    if pn.distM ~= m then
        pn.distM = m
        local ds = (m < 1000) and (m .. "m") or string.format("%.1fkm", m / 1000)
        if kind == "airdrop" then ds = ((_G.MWLang == "EN") and "Airdrop [" or "Airdrop [") .. ds .. "]" end
        PlayerMapMarker._LabelText(pn.txt, ds)
    end
    PlayerMapMarker._LabelSet(pn.txt, true, cp.X, tipY - (pn.h or PlayerMapMarker.PinH) * ts - 4, ts)
end

function _G.CratePin_Tick(pc)
    local seen = nil
    if _G.MWConfig.EspItem_Master and _G.MWConfig.EspItem_DeadBox and _G.CachedItems then
        local MyLoc = PlayerMapMarker.GetMyLocation()
        local now = _G.RealNow()
        for _, cached in ipairs(_G.CachedItems) do
            if cached.isBox and slua.isValid(cached.act) and not cached.act.bHidden then
                seen = seen or {}
                local key = tostring(cached.act)
                seen[key] = true
                pcall(PlayerMapMarker._PinBody, key, cached.act, pc, MyLoc, now, cached.kind)
            end
        end
    end
    for key in pairs(PlayerMapMarker.Pins) do
        if not (seen and seen[key]) then PlayerMapMarker.RemovePin(key) end
    end
end

