PlayerMapMarker.VehIconOutlineColor = FLinearColor and FLinearColor(0.0, 0.0, 0.0, 0.9) or {R=0, G=0, B=0, A=230}
PlayerMapMarker.VehZOff = 180
PlayerMapMarker.VehFont = 15
