PlayerMapMarker.VehKindScale = { heli = 2.0 }
PlayerMapMarker.VehColorOcc = FLinearColor and FLinearColor(0.62, 0.1, 1.0, 1.0) or {R=158, G=26, B=255, A=255}

function PlayerMapMarker.RemoveVehMark(key)
    local vm = PlayerMapMarker.VehMarks[key]
    if not vm then return end
    for _, k in ipairs({"img", "outline", "txt", "hp"}) do
        local it = vm[k]
        if it and it.w and slua.isValid(it.w) then
            if PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs[tostring(it.w)] = nil end
            pcall(function() it.w:RemoveFromParent() end)
        end
    end
    PlayerMapMarker.VehMarks[key] = nil
end
function PlayerMapMarker.ClearAllVehMarks()
    for key in pairs(PlayerMapMarker.VehMarks) do PlayerMapMarker.RemoveVehMark(key) end
    PlayerMapMarker.VehMarks = {}
end

function PlayerMapMarker._VehMarkBody(key, item, PC, MyLoc)
    local vm = PlayerMapMarker.VehMarks[key]
    local iconKey = (item.kind and PlayerMapMarker.VehKindIcon[item.kind]) or ("veh_" .. (item.kind or item.group or "car"))
    if not _G.MWIconB64[iconKey] then iconKey = "veh_car" end
    if not vm or not (vm.img and vm.img.w and _G.MWWidgetLive(vm.img.w)) then
        local canvas = PlayerMapMarker.ESPCanvas
        if not canvas or not Game:IsValid(canvas) then
            if not PlayerMapMarker.InitESPCanvas() then return end
            canvas = PlayerMapMarker.ESPCanvas
        end
        local H = PlayerMapMarker.VehIconH
        local function mk(size, z)
            local im = _G.MWIconImageAt(canvas, 0, 0, size, size, iconKey, 0.5, 1.0, z)
            if not im then return nil end
            pcall(function() im.w:SetRenderTransformPivot(FVector2D and FVector2D(0.5, 1.0) or {X=0.5, Y=1}) end)
            pcall(function() im.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
            im.vis = false; im.x = nil; im.y = nil; im.sc = nil; im.color = nil
            im.pos = FVector2D and FVector2D(0, 0) or {X=0, Y=0}
            im.scv = FVector2D and FVector2D(1, 1) or {X=1, Y=1}
            return im
        end
        local img = mk(H, 4)
        if not img then return end
        local outline = mk(H * PlayerMapMarker.VehIconOutline, 3)
        if outline then pcall(outline.w.SetColorAndOpacity, outline.w, PlayerMapMarker.VehIconOutlineColor) end
        local txt = PlayerMapMarker._NewLabelText(canvas, PlayerMapMarker.VehFont, PlayerMapMarker.VehColors.car, 0.5, 0.0)
        local hp = PlayerMapMarker._NewLabelText(canvas, PlayerMapMarker.VehFont, PlayerMapMarker.VehHPColHigh, 0.5, 0.0)
        vm = { img = img, outline = outline, txt = txt, hp = hp, distM = nil, iconKey = iconKey, hpTxt = nil, hpCol = nil }
        PlayerMapMarker.VehMarks[key] = vm
    end
    if vm.iconKey ~= iconKey then vm.iconKey = iconKey; _G.MWIconSet(vm.img, iconKey); if vm.outline then _G.MWIconSet(vm.outline, iconKey) end end
    local act = item.act
    local loc = nil
    pcall(function() loc = act:K2_GetActorLocation() end)
    if not loc then PlayerMapMarker._PinSet(vm.img, false); PlayerMapMarker._PinSet(vm.outline, false); PlayerMapMarker._LabelSet(vm.txt, false); PlayerMapMarker._LabelSet(vm.hp, false) return end
    loc.Z = loc.Z + PlayerMapMarker.VehZOff
    local bOn, cp = PlayerMapMarker.ProjectWorldToCanvasLocal(PC, loc)
    if not bOn then PlayerMapMarker._PinSet(vm.img, false); PlayerMapMarker._PinSet(vm.outline, false); PlayerMapMarker._LabelSet(vm.txt, false); PlayerMapMarker._LabelSet(vm.hp, false) return end
    local dcm = MyLoc and PlayerMapMarker._Dist3D(MyLoc, loc) or 2500
    local ts = 2500 / (dcm > 1 and dcm or 1)
    if ts < 0.72 then ts = 0.72 elseif ts > 1.25 then ts = 1.25 end
    ts = math.floor(ts * 50 + 0.5) / 50
    local color = item.hasDriver and PlayerMapMarker.VehColorOcc or (PlayerMapMarker.VehColors[item.kind or item.group or "car"] or PlayerMapMarker.VehColors.car)
    if vm.img.color ~= color then vm.img.color = color; pcall(vm.img.w.SetColorAndOpacity, vm.img.w, color) end
    PlayerMapMarker._LabelColor(vm.txt, color)
    local ks = ts * ((item.kind and PlayerMapMarker.VehKindScale[item.kind]) or 1)
    PlayerMapMarker._PinSet(vm.img, true, cp.X, cp.Y - 2, ks)
    PlayerMapMarker._PinSet(vm.outline, true, cp.X, cp.Y - 2 + PlayerMapMarker.VehIconH * (PlayerMapMarker.VehIconOutline - 1) * 0.5 * ks, ks)
    local m = math.floor(dcm / 100 + 0.5)
    if vm.distM ~= m then vm.distM = m; PlayerMapMarker._LabelText(vm.txt, string.format("%s %s", item.name or "", (m < 1000) and (m .. "m") or string.format("%.1fkm", m / 1000))) end
    PlayerMapMarker._LabelSet(vm.txt, true, cp.X, cp.Y + 2, ts)
    local cur, mx = nil, nil
    pcall(function()
        local vc = act.VehicleCommon
        if not slua.isValid(vc) and type(act.GetVehicleCommon) == "function" then vc = act:GetVehicleCommon() end
        if slua.isValid(vc) then
            if type(vc.GetVehicleHP) == "function" then cur = vc:GetVehicleHP() else cur = vc.Hp end
            if type(vc.GetVehicleHPMax) == "function" then mx = vc:GetVehicleHPMax() else mx = vc.HPMax end
        end
    end)
    if vm.hp and type(cur) == "number" and type(mx) == "number" and mx > 0 and cur > 0 then
        local ci, mi = math.floor(cur + 0.5), math.floor(mx + 0.5)
        local t = ci .. "/" .. mi
        if vm.hpTxt ~= t then vm.hpTxt = t; PlayerMapMarker._LabelText(vm.hp, t) end
        local r = cur / mx
        local hc = (r > 0.6) and PlayerMapMarker.VehHPColHigh or ((r > 0.3) and PlayerMapMarker.VehHPColMid or PlayerMapMarker.VehHPColLow)
        if vm.hpCol ~= hc then vm.hpCol = hc; PlayerMapMarker._LabelColor(vm.hp, hc) end
        PlayerMapMarker._LabelSet(vm.hp, true, cp.X, cp.Y + 2 + (PlayerMapMarker.VehFont + PlayerMapMarker.VehHPLineGap) * ts, ts)
    elseif vm.hp then
        PlayerMapMarker._LabelSet(vm.hp, false)
    end
end

function _G.VehMark_Tick(pc)
    local seen = nil
    local c = _G.MWConfig
    if c.EspVehicle and _G.CachedVehicles then
        local MyLoc = PlayerMapMarker.GetMyLocation()
        for _, item in ipairs(_G.CachedVehicles) do
            local veh = item.act
            if slua.isValid(veh) and not veh.bHidden then
                local g = item.group
                local show = (g == "car" and c.EspVeh_Car) or (g == "moto" and c.EspVeh_Moto) or (g == "offroad" and c.EspVeh_Offroad) or (g == "boat" and c.EspVeh_Boat) or ((g ~= "car" and g ~= "moto" and g ~= "offroad" and g ~= "boat") and c.EspVeh_Heavy)
                if show then
                    seen = seen or {}
                    local key = tostring(veh)
                    seen[key] = true
                    pcall(PlayerMapMarker._VehMarkBody, key, item, pc, MyLoc)
                end
            end
        end
    end
    for key in pairs(PlayerMapMarker.VehMarks) do
        if not (seen and seen[key]) then PlayerMapMarker.RemoveVehMark(key) end
    end
end

function PlayerMapMarker.HideBox(KeyStr)
    local box = PlayerMapMarker.BoxLines[KeyStr]
    if box then for i = 1, #box do DrawLine.Hide(box[i]) end end
    PlayerMapMarker.HideLabels(KeyStr)
    PlayerMapMarker.HideSkel(KeyStr)
end

function PlayerMapMarker.RemoveBox(KeyStr)
    local box = PlayerMapMarker.BoxLines[KeyStr]
    if box then
        for i = 1, #box do DrawLine.Remove(box[i]) end
        PlayerMapMarker.BoxLines[KeyStr] = nil
    end
    PlayerMapMarker.RemoveSkel(KeyStr)
end

function PlayerMapMarker.ClearAllBoxes()
    for KeyStr, box in pairs(PlayerMapMarker.BoxLines) do
        for i = 1, #box do DrawLine.Remove(box[i]) end
    end
    PlayerMapMarker.BoxLines = {}
    PlayerMapMarker.ClearAllSkel()
end

function PlayerMapMarker._BoxBody(KeyStr, Character, PC, hx, hy, sc, ESPData)
    local feet = PlayerMapMarker.GetCharacterLocation(Character)
    if not feet then PlayerMapMarker.HideBox(KeyStr) return end
    local hh = 90
    local cap = Character.CapsuleComponent
    if cap and slua.isValid(cap) and cap.GetScaledCapsuleHalfHeight then hh = cap:GetScaledCapsuleHalfHeight() or 90 end
    feet.Z = feet.Z - hh
    local okF, fx, fy = PlayerMapMarker.ProjectWorldToCanvasLocalRaw(PC, feet)
    if not okF then PlayerMapMarker.HideBox(KeyStr) return end
    local h = fy - hy
    if h < 6 then h = 6 end
    if h > (PlayerMapMarker._VpPxH or 1080) * 2 then PlayerMapMarker.HideBox(KeyStr) return end
    local ratio = PlayerMapMarker.BoxRatioStand
    if Character.IsProne and Character:IsProne() then ratio = PlayerMapMarker.BoxRatioProne
    elseif Character.bIsCrouched then ratio = PlayerMapMarker.BoxRatioCrouch end
    local w = h * ratio
    local cx = (hx + fx) * 0.5
    local x1, x2 = cx - w * 0.5, cx + w * 0.5
    local box = PlayerMapMarker.BoxLines[KeyStr]
    if not box then
        box = {}
        for i = 1, PlayerMapMarker.BoxSegs do box[i] = DrawLine.Create(3) end
        PlayerMapMarker.BoxLines[KeyStr] = box
    end
    local y1, y2 = hy, fy
    if _G.MWConfig.EspPlayerBox then
        local c, t = PlayerMapMarker.BoxColor, PlayerMapMarker.BoxThickness
        if Character.HealthStatus == 1 then c = PlayerMapMarker.BoxColorKnock end
        local L = math.min(w, h) * (PlayerMapMarker.BoxCornerFrac or 0.3)
        if L < 3 then L = 3 end
        DrawLine.Update(box[1], x1, y1, x1 + L, y1, c, t)
        DrawLine.Update(box[2], x1, y1, x1, y1 + L, c, t)
        DrawLine.Update(box[3], x2 - L, y1, x2, y1, c, t)
        DrawLine.Update(box[4], x2, y1, x2, y1 + L, c, t)
        DrawLine.Update(box[5], x1, y2, x1 + L, y2, c, t)
        DrawLine.Update(box[6], x1, y2 - L, x1, y2, c, t)
        DrawLine.Update(box[7], x2 - L, y2, x2, y2, c, t)
        DrawLine.Update(box[8], x2, y2 - L, x2, y2, c, t)
    else
        for i = 1, 8 do DrawLine.Hide(box[i]) end
    end
    if _G.MWConfig.EspPlayerHP and Character.HealthStatus ~= 1 then
        local pct = 1
        local hp, mhp = Character.Health, (Character.HealthMax or Character.MaxHealth)
        if type(hp) == "number" and type(mhp) == "number" and mhp > 0 then pct = hp / mhp end
        if pct < 0 then pct = 0 elseif pct > 1 then pct = 1 end
        local bw = h * 0.06
        if bw < PlayerMapMarker.HPBarWidthMin then bw = PlayerMapMarker.HPBarWidthMin elseif bw > PlayerMapMarker.HPBarWidthMax then bw = PlayerMapMarker.HPBarWidthMax end
        local bx = x1 - (PlayerMapMarker.HPBarGap or 3) - bw * 0.5
        DrawLine.Update(box[9], bx, y2, bx, y1, PlayerMapMarker.HPBarBgColor, bw)
        local fillTop = y2 - h * pct
        local hc
        if pct > 0.7 then hc = PlayerMapMarker.HPBarColorHigh
        elseif pct > 0.5 then hc = PlayerMapMarker.HPBarColorMidHi
        elseif pct > 0.25 then hc = PlayerMapMarker.HPBarColorMid
        else hc = PlayerMapMarker.HPBarColorLow end
        if pct > 0.001 then
            DrawLine.Update(box[10], bx, y2, bx, fillTop, hc, bw)
        else
            DrawLine.Hide(box[10])
        end
    else
        DrawLine.Hide(box[9]); DrawLine.Hide(box[10])
    end
    pcall(PlayerMapMarker._LabelsBody, KeyStr, Character, ESPData, cx, y1, y2, sc or (PlayerMapMarker.ESPBaseScale or 0.9))
    if _G.MWConfig.EspPlayerSkeleton then
        pcall(PlayerMapMarker._SkelBody, KeyStr, Character, PC)
    else
        PlayerMapMarker.HideSkel(KeyStr)
    end
end

function PlayerMapMarker.UpdateBox(KeyStr, Character, PC, CanvasPos, bOnScreen, sc, ESPData)
    local c = _G.MWConfig
    if not (c.EspPlayerBox or c.EspPlayerHP or c.EspPlayerName or c.EspPlayerDistance or c.EspPlayerWeapon or c.EspPlayerSkeleton) then
        if PlayerMapMarker.BoxLines[KeyStr] then PlayerMapMarker.RemoveBox(KeyStr) end
        PlayerMapMarker.HideLabels(KeyStr)
        return
    end
    if not bOnScreen or not CanvasPos then PlayerMapMarker.HideBox(KeyStr) return end
    pcall(PlayerMapMarker._BoxBody, KeyStr, Character, PC, CanvasPos.X, CanvasPos.Y, sc, ESPData)
end

function PlayerMapMarker.ScreenPixelToCanvasLocalRaw(PC, screenX, screenY)
    local scaleX = PlayerMapMarker._CanvasScaleX or 1.0
    local scaleY = PlayerMapMarker._CanvasScaleY or 1.0
    local offsetX = PlayerMapMarker._CanvasOffsetX or 0
    local offsetY = PlayerMapMarker._CanvasOffsetY or 0
    return screenX * scaleX + offsetX, screenY * scaleY + offsetY
end

function PlayerMapMarker._ProjSane(x, y)
    local W = PlayerMapMarker._VpPxW or 1920
    local H = PlayerMapMarker._VpPxH or 1080
    if x ~= x or y ~= y then return false end
    if x < -W or x > W * 2 or y < -H or y > H * 2 then return false end
    return true
end

function PlayerMapMarker.ProjectWorldToCanvasLocalRaw(PC, WorldLoc)
    if not IsValid(PC) or not WorldLoc then return false, 0, 0 end
    if not PlayerMapMarker._tempScreenPixelPos then
        PlayerMapMarker._tempScreenPixelPos = FVector2D and FVector2D(0, 0) or {X=0, Y=0}
    end
    local tempPos = PlayerMapMarker._tempScreenPixelPos
    local bOK = false
    pcall(function()
        local res = PC:ProjectWorldLocationToScreen(WorldLoc, tempPos, true)
        if res == true or res == 1 then bOK = true end
    end)
    if not bOK or (tempPos.X == 0 and tempPos.Y == 0) then return false, 0, 0 end
    if not PlayerMapMarker._ProjSane(tempPos.X, tempPos.Y) then return false, 0, 0 end
    local canvasX, canvasY = PlayerMapMarker.ScreenPixelToCanvasLocalRaw(PC, tempPos.X, tempPos.Y)
    return true, canvasX, canvasY
end


function PlayerMapMarker.ClearAllESP()
    PlayerMapMarker._AICache = {}
    RedBoxOverlay.Stop()
    for KeyStr, Data in pairs(PlayerMapMarker.ESPWidgets) do
        PlayerMapMarker.RemoveESPWidget(Data.Widget, KeyStr)
    end
    PlayerMapMarker.ESPWidgets = {}
    PlayerMapMarker.ESPWidgetPtrs = {}
    PlayerMapMarker.ClearAllSnapLines()
    PlayerMapMarker.ClearAllBoxes()
    PlayerMapMarker.ClearAllLabels()
    PlayerMapMarker.ClearAllPins()
    PlayerMapMarker.ClearAllVehMarks()
    if _G.ItemLabels then pcall(_G.ItemLabels.Clear) end
    if PlayerMapMarker.ESPCanvas and Game:IsValid(PlayerMapMarker.ESPCanvas) then
        pcall(function()
            local n = PlayerMapMarker.ESPCanvas:GetChildrenCount()
            for i = n - 1, 0, -1 do
                local child = PlayerMapMarker.ESPCanvas:GetChildAt(i)
                if child and slua.isValid(child) then
                    if PlayerMapMarker.IsOurESPWidget(child) then PlayerMapMarker.ESPCanvas:RemoveChild(child) end
                end
            end
        end)
    end
    PlayerMapMarker.ESPCanvas = nil
    PlayerMapMarker._CanvasXformTime = nil
    PlayerMapMarker._SnapFromTime = nil
    PlayerMapMarker._OBHeadWidgetClass = nil
    PlayerMapMarker._OBHeadWidgetLoadFailed = false
    PlayerMapMarker._bDumpedWidgetChildren = false
    PlayerMapMarker._cachedViewportW = 1920
    PlayerMapMarker._cachedViewportH = 1080
end

function PlayerMapMarker.UpdateESP(AllPlayers, MyLoc)
    if not PlayerMapMarker.bUseScreenESP then return end
    
    PlayerMapMarker.bUseSnapLines = _G.MWConfig.EspPlayerLine

    if not PlayerMapMarker.InitESPCanvas() then
        return
    end

    if PlayerMapMarker._OBHeadWidgetLoadFailed then return end

    local PC = PlayerMapMarker.GetMyPlayerController()
    if IsValid(PC) then
        PlayerMapMarker.UpdateCanvasTransform(PC)
    end

    local fromX, fromY = 0, 0
    if PlayerMapMarker.bUseSnapLines and IsValid(PC) then
        fromX, fromY = PlayerMapMarker.GetSnapLineStartPos(PC)
    end

    local MyKey = PlayerMapMarker.GetMyPlayerKey()
    local SeenKeys = {}
    
    local MyChar = nil
    pcall(function()
        local GDP = PlayerMapMarker.GetGameplayData()
        if GDP and GDP.GetLocalCharacter then
            MyChar = GDP.GetLocalCharacter()
        else
            if PC and PC.GetPawn then MyChar = PC:GetPawn() end
        end
    end)
    local MyTeamID = PlayerMapMarker.GetTeamID(MyChar)
    PlayerMapMarker._ShowAnyUI = PlayerMapMarker._ShowAnyUINow()

    for PlayerKey, Character in pairs(AllPlayers) do
        if IsValid(Character) then
            local bIsMe = PlayerMapMarker.IsMe(Character, PlayerKey, MyKey)
            local bIsAI = PlayerMapMarker.IsAI(Character, PlayerKey)
            local KeyStr = tostring(PlayerKey)
            local Name = PlayerMapMarker.GetPlayerName(Character)

            local Loc = PlayerMapMarker.GetESPLocation(Character)

            local DistStr = ""
            if MyLoc and Loc then
                DistStr = PlayerMapMarker.GetDistanceString(MyLoc, Loc)
            end

            local bSkip = false
            if bIsMe and not PlayerMapMarker.bIncludeMe then bSkip = true end
            if bIsAI and not PlayerMapMarker.bIncludeAI then bSkip = true end
            
            local TeamID = PlayerMapMarker.GetTeamID(Character)
            if MyTeamID ~= nil and TeamID == MyTeamID and not bIsMe then
                bSkip = true
            end

            local bIsAlive = PlayerMapMarker.IsAlive(Character)

            if not bSkip and Loc then
                SeenKeys[KeyStr] = true
                local ESPData = PlayerMapMarker.ESPWidgets[KeyStr]

                local Text = ""
                if _G.MWConfig.EspPlayerName then Text = Name end
                if _G.MWConfig.EspPlayerDistance and DistStr and DistStr ~= "" then
                    if Text ~= "" then Text = string.format("%s [%s]", Text, DistStr) else Text = string.format("[%s]", DistStr) end
                end

                local bOnScreen, CanvasPos = PlayerMapMarker.ProjectWorldToCanvasLocal(PC, Loc)

                if not ESPData then
                    local Widget = PlayerMapMarker.CreateESPWidget()
                    if Widget then
                        if MyLoc then Widget._WantScale = PlayerMapMarker._ScaleForDist(PlayerMapMarker._Dist3D(MyLoc, Loc)) end
                        PlayerMapMarker.ESPWidgets[KeyStr] = {
                            Widget = Widget,
                            Character = Character,
                            Name = Name,
                            LastDistStr = DistStr,
                            TeamID = TeamID,
                            IsBot = bIsAI,
                        }
                        PlayerMapMarker.UpdateESPText(Widget, Text)
                        if bIsAlive then
                            PlayerMapMarker.UpdateESPPositionWithPC(Widget, Loc, PC, CanvasPos)
                            PlayerMapMarker.ApplyTeamColor(Widget, TeamID)
                            local HP = Character.Health or 0
                            local MaxHP = Character.MaxHealth or 120
                            local pct = 0
                            if HP > 0 and MaxHP > 0 then
                                pct = HP / MaxHP
                                if pct > 1 then pct = 1 end
                                if pct < 0 then pct = 0 end
                            end
                            PlayerMapMarker.UpdateESPHealth(Widget, pct)
                            PlayerMapMarker.AddWeaponIconToESP(Widget, Character)

                            if PlayerMapMarker.bUseSnapLines then
                                PlayerMapMarker.UpdateSnapLine(KeyStr, CanvasPos, bOnScreen, fromX, fromY, bIsAI, PC, Character)
                            else
                                PlayerMapMarker.RemoveSnapLine(KeyStr)
                            end

                        else
                            local Container = Widget.Container or Widget
                            pcall(PlayerMapMarker._SetContainerVis, Widget, Container, UEnums.ESlateVisibility.Collapsed)
                            PlayerMapMarker.UpdateESPHealth(Widget, 0)
                            PlayerMapMarker.RemoveSnapLine(KeyStr)
                        end
                    end
                else
                    ESPData.Character = Character
                    ESPData.Name = Name
                    ESPData.LastDistStr = DistStr
                    ESPData.IsBot = bIsAI
                    if bIsAlive then
                        ESPData.TeamID = TeamID
                        PlayerMapMarker.ApplyTeamColor(ESPData.Widget, TeamID)
                        
                        PlayerMapMarker.UpdateESPText(ESPData.Widget, Text)
                        PlayerMapMarker.UpdateESPPositionWithPC(ESPData.Widget, Loc, PC, CanvasPos)
                        local HP = Character.Health or 0
                        local MaxHP = Character.MaxHealth or 120
                        local pct = 0
                        if HP > 0 and MaxHP > 0 then
                            pct = HP / MaxHP
                            if pct > 1 then pct = 1 end
                            if pct < 0 then pct = 0 end
                        end
                        PlayerMapMarker.UpdateESPHealth(ESPData.Widget, pct)
                        PlayerMapMarker.AddWeaponIconToESP(ESPData.Widget, Character)

                        if PlayerMapMarker.bUseSnapLines then
                            PlayerMapMarker.UpdateSnapLine(KeyStr, CanvasPos, bOnScreen, fromX, fromY, bIsAI, PC, Character)
                        else
                            PlayerMapMarker.RemoveSnapLine(KeyStr)
                        end

                    else
                        local Container = ESPData.Widget.Container or ESPData.Widget
                        pcall(PlayerMapMarker._SetContainerVis, ESPData.Widget, Container, UEnums.ESlateVisibility.Collapsed)
                        PlayerMapMarker.UpdateESPHealth(ESPData.Widget, 0)
                        PlayerMapMarker.RemoveSnapLine(KeyStr)
                    end
                end
            end
        end
    end

    for KeyStr, Data in pairs(PlayerMapMarker.ESPWidgets) do
        if not SeenKeys[KeyStr] then
            PlayerMapMarker.RemoveESPWidget(Data.Widget, KeyStr)
            PlayerMapMarker.ESPWidgets[KeyStr] = nil
        end
    end

end

function PlayerMapMarker.UpdateESPLight()
    if not PlayerMapMarker.bUseScreenESP then
        if RedBoxOverlay and RedBoxOverlay.bActive then RedBoxOverlay.UpdatePosition() end
        return
    end

    PlayerMapMarker.bUseSnapLines = _G.MWConfig.EspPlayerLine
    if not PlayerMapMarker.ESPCanvas or not Game:IsValid(PlayerMapMarker.ESPCanvas) then return end
    local PC = PlayerMapMarker.GetMyPlayerController()
    if not IsValid(PC) then return end

    PlayerMapMarker.UpdateCanvasTransform(PC)

    if RedBoxOverlay and RedBoxOverlay.bActive then RedBoxOverlay.UpdatePosition() end

    local fromX, fromY = 0, 0
    if PlayerMapMarker.bUseSnapLines then fromX, fromY = PlayerMapMarker.GetSnapLineStartPos(PC) end

    PlayerMapMarker._ShowAnyUI = PlayerMapMarker._ShowAnyUINow()
    local VIS_HIDE = UEnums.ESlateVisibility.Collapsed
    local MyLocL = PlayerMapMarker.GetMyLocation()

    for KeyStr, ESPData in pairs(PlayerMapMarker.ESPWidgets) do
        local Widget = ESPData.Widget
        local Character = ESPData.Character
        local Container = Widget and Widget.Container or nil
        if type(Container) ~= "userdata" or not slua.isValid(Container) then Container = nil end

        if Widget and Character and IsValid(Character) then
            local bIsAlive = PlayerMapMarker.IsAlive(Character)
            if not bIsAlive then
                if Container then pcall(PlayerMapMarker._SetContainerVis, Widget, Container, VIS_HIDE) end
                PlayerMapMarker.RemoveSnapLine(KeyStr)
                PlayerMapMarker.HideBox(KeyStr)
            else
                if Container and not Widget._OpacitySet then
                    pcall(Container.SetRenderOpacity, Container, 1.0)
                    Widget._OpacitySet = true
                end

                local Loc = PlayerMapMarker.GetESPLocation(Character)
                if Loc then
                    local onScreen = false
                    do
                        local tp = PlayerMapMarker._ProjTmp
                        local okP, _ = PlayerMapMarker.ProjectWorldToCanvasLocal(PC, Loc)
                        if okP and tp then
                            local W, H = PlayerMapMarker._VpPxW or 1920, PlayerMapMarker._VpPxH or 1080
                            onScreen = (tp.X >= 0 and tp.X <= W and tp.Y >= 0 and tp.Y <= H)
                        end
                    end
                    local sc = PlayerMapMarker.ESPBaseScale or 0.9
                    if MyLocL then
                        local dcm = PlayerMapMarker._Dist3D(MyLocL, Loc)
                        ESPData._DistCm = dcm
                        sc = PlayerMapMarker._ScaleForDist(dcm)
                    end
                    Widget._WantScale = sc
                    local bOnScreen, CanvasPos = PlayerMapMarker.ProjectWorldToCanvasLocal(PC, Loc)
                    if Container then PlayerMapMarker.UpdateESPPositionWithPC(Widget, Loc, PC, CanvasPos) end
                    if PlayerMapMarker.bUseSnapLines then PlayerMapMarker.UpdateSnapLine(KeyStr, CanvasPos, bOnScreen, fromX, fromY, ESPData.IsBot, PC, Character)
                    else PlayerMapMarker.RemoveSnapLine(KeyStr) end
                    PlayerMapMarker.UpdateBox(KeyStr, Character, PC, CanvasPos, bOnScreen, sc, ESPData)
                else
                    PlayerMapMarker.RemoveSnapLine(KeyStr)
                    PlayerMapMarker.HideBox(KeyStr)
                end
            end
        end
    end
end

function PlayerMapMarker.UpdateESPDistances()
    if not PlayerMapMarker.bUseScreenESP then return end
    local MyLoc = PlayerMapMarker.GetMyLocation()
    if not MyLoc then return end
    local PC = PlayerMapMarker.GetMyPlayerController()
    if not IsValid(PC) then return end
    PlayerMapMarker.UpdateCanvasTransform(PC)

    for KeyStr, ESPData in pairs(PlayerMapMarker.ESPWidgets) do
        local Character = ESPData.Character
        local Widget = ESPData.Widget
        local Container = Widget and (Widget.Container or Widget)
        if Character and IsValid(Character) and type(Container) == "userdata" and slua.isValid(Container) then
            local Loc = PlayerMapMarker.GetESPLocation(Character)
            if Loc then
                local Dist = PlayerMapMarker.CalcDistance(MyLoc, Loc)
                ESPData.LastDistance = Dist

                if PlayerMapMarker.bShowDistance then
                    local DistStr = ""
                    if Dist then
                        local Meters = Dist / 100
                        local mKey = (Meters < 1000) and math.floor(Meters) or (1000000 + math.floor(Meters / 100))
                        if ESPData._DistKey ~= mKey then
                            ESPData._DistKey = mKey
                            if Meters < 1000 then ESPData._DistStrC = string.format("%dm", math.floor(Meters))
                            else ESPData._DistStrC = string.format("%.1fkm", Meters / 1000) end
                        end
                        DistStr = ESPData._DistStrC
                    end

                    local Name = ESPData.Name or "Unknown"
                    local Text = ""
                    
                    if _G.MWConfig.EspPlayerName then Text = Name end
                    if _G.MWConfig.EspPlayerDistance and DistStr and DistStr ~= "" then
                        if Text ~= "" then Text = Text .. " [" .. DistStr .. "]" else Text = "[" .. DistStr .. "]" end
                    end
                    
                    ESPData.LastDistStr = DistStr
                    PlayerMapMarker.UpdateESPText(Widget, Text)
                end
            end
        end
    end
end

function PlayerMapMarker.ScanAndUpdate()
    local AllChars = PlayerMapMarker.GetAllCharacters()
    if not AllChars then RedBoxOverlay.SetCounts(0, 0) return 0 end

    local MyKey = PlayerMapMarker.GetMyPlayerKey()
    local MyLoc = PlayerMapMarker.GetMyLocation()

    local MyChar = nil
    pcall(function()
        local GDP = PlayerMapMarker.GetGameplayData()
        if GDP and GDP.GetLocalCharacter then MyChar = GDP.GetLocalCharacter()
        else local PC = PlayerMapMarker.GetMyPlayerController() if PC and PC.GetPawn then MyChar = PC:GetPawn() end end
    end)
    local MyTeamID = PlayerMapMarker.GetTeamID(MyChar)

    local realPlayers = 0
    local botPlayers = 0

    for PlayerKey, Character in pairs(AllChars) do
        if IsValid(Character) then
            local bIsMe = PlayerMapMarker.IsMe(Character, PlayerKey, MyKey)
            local bIsAI = PlayerMapMarker.IsAI(Character)
            local bIsAlive = PlayerMapMarker.IsAlive(Character)

            if bIsAlive and not bIsMe then
                local bIsMyTeam = false
                if MyTeamID ~= nil then
                    local targetTeamID = PlayerMapMarker.GetTeamID(Character)
                    if targetTeamID == MyTeamID then bIsMyTeam = true end
                end
                
                if not bIsMyTeam then
                    if bIsAI then botPlayers = botPlayers + 1
                    else realPlayers = realPlayers + 1 end
                end
            end
        end
    end

    if _G.MWConfig.EspPlayerCount then
        if RedBoxOverlay.bActive then RedBoxOverlay.SetCounts(realPlayers, botPlayers)
        else RedBoxOverlay.Start() end
    else
        if RedBoxOverlay.bActive then RedBoxOverlay.Stop() end
    end

    if PlayerMapMarker.bUseScreenESP then
        PlayerMapMarker.UpdateESP(AllChars, MyLoc)
        return 0
    end
    return 0
end

function PlayerMapMarker._ClearTimers()
    local pc = PlayerMapMarker._ActiveTimerPC
    local hs = PlayerMapMarker._TimerHandles
    PlayerMapMarker._TimerHandles = nil
    if hs and pc and slua.isValid(pc) and pc.RemoveGameTimer then
        for _, h in ipairs(hs) do if h then pcall(pc.RemoveGameTimer, pc, h) end end
    end
end

function PlayerMapMarker.AttachTimers()
    pcall(function()
        local pc = PlayerMapMarker.GetMyPlayerController()
        if not slua.isValid(pc) or not pc.AddGameTimer then
            local now = os.time()
            if PlayerMapMarker._AttachPending then if PlayerMapMarker._AttachPendingTime and (now - PlayerMapMarker._AttachPendingTime) < 2 then return end end
            PlayerMapMarker._AttachPending = true ; PlayerMapMarker._AttachPendingTime = now
            pcall(function() require("timer").SetGameTimer(1.0, false, function() PlayerMapMarker._AttachPending = nil ; PlayerMapMarker._AttachPendingTime = nil ; PlayerMapMarker.AttachTimers() end) end)
            return
        end

        PlayerMapMarker._AttachPending = nil ; PlayerMapMarker._AttachPendingTime = nil
        local now = os.time()
        local lastPC = PlayerMapMarker._ActiveTimerPC
        local lastTick = PlayerMapMarker._ActiveTimerTick
        if lastPC and slua.isValid(lastPC) and lastPC == pc then if lastTick and (now - lastTick) < 5 then return end end

        PlayerMapMarker._ClearTimers()
        PlayerMapMarker._ActiveTimerPC = pc ; PlayerMapMarker._ActiveTimerTick = now
        local hs = {}
        PlayerMapMarker._TimerHandles = hs

        pcall(function() hs[#hs+1] = pc:AddGameTimer(PlayerMapMarker.nUpdateInterval or 0.5, true, function() PlayerMapMarker._ActiveTimerTick = os.time() if PlayerMapMarker.bActive then pcall(PlayerMapMarker.ScanAndUpdate) end end) end)
        if not _G._ESPFrameTickRegistered then
            local okReg = pcall(function()
                local hud = require("game_frontend_hud")
                hud.SetSluaTickListener(function(dt)
                    local PMM = _G.PlayerMapMarker
                    if PMM and PMM.bActive then
                        PMM._ActiveTimerTick = os.time()
                        pcall(PMM.UpdateESPLight)
                    end
                end)
            end)
            if okReg then _G._ESPFrameTickRegistered = true end
        end
        if not _G._ESPFrameTickRegistered then
            pcall(function() hs[#hs+1] = pc:AddGameTimer(PlayerMapMarker._LightUpdateInterval or 0.02, true, function() PlayerMapMarker._ActiveTimerTick = os.time() if PlayerMapMarker.bActive then pcall(PlayerMapMarker.UpdateESPLight) end end) end)
        end
        pcall(function() hs[#hs+1] = pc:AddGameTimer(PlayerMapMarker._DistanceUpdateInterval or 0.1, true, function() PlayerMapMarker._ActiveTimerTick = os.time() if PlayerMapMarker.bActive and PlayerMapMarker.bUseScreenESP and PlayerMapMarker.bShowDistance then pcall(PlayerMapMarker.UpdateESPDistances) end end) end)
        pcall(function() require("timer").SetGameTimer(5.0, false, PlayerMapMarker.AttachTimers) end)
    end)
end

function PlayerMapMarker.Start()
    if PlayerMapMarker.bActive then return end
    PlayerMapMarker.bActive = true
    PlayerMapMarker._FrameCount = 0
    PlayerMapMarker.ScanAndUpdate()
    PlayerMapMarker.AttachTimers()
end

function PlayerMapMarker.Stop()
    PlayerMapMarker.bActive = false
    PlayerMapMarker._FrameCount = 0
    PlayerMapMarker.ClearAllESP()
    pcall(PlayerMapMarker._ClearTimers)
    PlayerMapMarker._ActiveTimerPC = nil ; PlayerMapMarker._ActiveTimerTick = nil
end

_G.PlayerMapMarker = PlayerMapMarker

local FOVCircle_ScaleX = 1.0
local FOVCircle_ScaleY = 1.0
local FOVCircle_OffsetX = 0
local FOVCircle_OffsetY = 0

local function UpdateFOVCanvasTransform(PC)
    local canvas = DrawLine.GetCanvas()
    if not canvas then return end
    local nowC = _G.RealNow()
    if _G._FOVCircle_XformTime and (nowC - _G._FOVCircle_XformTime) < 0.25 then return end
    _G._FOVCircle_XformTime = nowC
    pcall(function()
        local SlateBP = import("SlateBlueprintLibrary")
        if not SlateBP then return end
        local cg = canvas:GetCachedGeometry()
        local absP0 = FVector2D(0, 0)
        local absP1 = FVector2D(1, 0)
        local lp0 = SlateBP.AbsoluteToLocal(cg, absP0)
        local lp1 = SlateBP.AbsoluteToLocal(cg, absP1)
        local dx = lp1.X - lp0.X
        local dy = lp1.Y - lp0.Y
        local scale = math.sqrt(dx * dx + dy * dy)
        if scale < 0.0001 then scale = 1.0 end
        FOVCircle_ScaleX = scale
        FOVCircle_ScaleY = scale
        FOVCircle_OffsetX = lp0.X
        FOVCircle_OffsetY = lp0.Y
    end)
end

function _G.CleanUpFOVCircle()
    _G._FOVCircle_XformTime = nil
    local fi = _G._FOVImg
    if fi and fi.w and slua.isValid(fi.w) then pcall(function() fi.w:RemoveFromParent() end) end
    _G._FOVImg = nil
end

_G.FOVRingColorIdle = FLinearColor and FLinearColor(1.0, 1.0, 1.0, 0.9) or {R=255, G=255, B=255, A=230}
_G.FOVRingColorLock = FLinearColor and FLinearColor(1.0, 1.0, 1.0, 0.9) or {R=255, G=255, B=255, A=230}
local function InitFOVImage()
    local fi = _G._FOVImg
    if fi and fi.w and _G.MWWidgetLive(fi.w) then return fi end
    if fi then _G.CleanUpFOVCircle() end
    local canvas = DrawLine.GetCanvas()
    if not canvas then return nil end
    if _G._FOVImgFailedT and (_G.RealNow() - _G._FOVImgFailedT) < 3.0 then return nil end
    fi = _G.MWIconImageAt(canvas, 0, 0, 100, 100, "fov_ring", 0.5, 0.5, 5)
    if not fi then _G._FOVImgFailedT = _G.RealNow() return nil end
    _G._FOVImgFailedT = nil
    pcall(function() fi.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    fi.vis = false; fi.cx = nil; fi.cy = nil; fi.d = nil; fi.lock = nil
    fi.pos = FVector2D and FVector2D(0, 0) or {X=0, Y=0}
    fi.size = FVector2D and FVector2D(100, 100) or {X=100, Y=100}
    _G._FOVImg = fi
    return fi
end

local function UpdateFOVCircle(fovVal, PC)
    local fi = InitFOVImage()
    if not fi then return end
    UpdateFOVCanvasTransform(PC)
    local vpW, vpH = 0, 0
    local nowV = _G.RealNow()
    if _G._FOV_vpTime and (nowV - _G._FOV_vpTime) < 0.25 and _G._FOV_vpW then
        vpW, vpH = _G._FOV_vpW, _G._FOV_vpH
    else
        pcall(function()
            local ui_util = require("client.common.ui_util")
            local vs = ui_util and ui_util.GetViewportSize()
            if vs and vs.X > 200 then vpW = vs.X vpH = vs.Y end
        end)
        if vpW >= 200 then _G._FOV_vpW, _G._FOV_vpH, _G._FOV_vpTime = vpW, vpH, nowV end
    end
    if vpW < 200 then return end
    local radiusPx = (fovVal / 100.0) * (vpW / 2.0)
    local cx = (vpW / 2) * FOVCircle_ScaleX + FOVCircle_OffsetX
    local cy = (vpH / 2) * FOVCircle_ScaleY + FOVCircle_OffsetY
    local rX = radiusPx * FOVCircle_ScaleX
    local rY = radiusPx * FOVCircle_ScaleY
    do
        local d = math.floor(rX * 2 + 0.5)
        local lock = (_G.MWState and _G.MWState.AimTouchTarget and slua.isValid(_G.MWState.AimTouchTarget)) and true or false
        if fi.cx ~= cx or fi.cy ~= cy then
            fi.cx, fi.cy = cx, cy
            fi.pos.X, fi.pos.Y = cx, cy
            pcall(fi.slot.SetPosition, fi.slot, fi.pos)
        end
        if fi.d ~= d then
            fi.d = d
            fi.size.X, fi.size.Y = d, d
            pcall(fi.slot.SetSize, fi.slot, fi.size)
        end
        if fi.lock ~= lock then
            fi.lock = lock
            pcall(fi.w.SetColorAndOpacity, fi.w, lock and _G.FOVRingColorLock or _G.FOVRingColorIdle)
        end
        if fi.vis ~= true then
            fi.vis = true
            pcall(fi.w.SetWidgetVisibility, fi.w, UEnums.ESlateVisibility.HitTestInvisible)
        end
    end
end

local function HideFOVCircle()
    local fi = _G._FOVImg
    if fi and fi.w and slua.isValid(fi.w) and fi.vis ~= false then
        fi.vis = false
        pcall(fi.w.SetWidgetVisibility, fi.w, UEnums.ESlateVisibility.Collapsed)
    end
end

_G.MinimapESP = { ImgSize = 40, OutlineScale = 1.13, targets = { { key = "mini", cfg = "MiniMapWindow", items = {}, _winT = 0 }, { key = "big", cfg = "EntireMapWindow", items = {}, _winT = 0 } } }
_G.MinimapESP.ColorEnemy = FLinearColor and FLinearColor(1.0, 0.0, 0.0, 1.0) or {R=255, G=0, B=0, A=255}
_G.MinimapESP.ColorWedge = FLinearColor and FLinearColor(1.0, 1.0, 1.0, 1.0) or {R=255, G=255, B=255, A=255}
_G.MinimapESP.ColorOutline = FLinearColor and FLinearColor(0.0, 0.0, 0.0, 0.92) or {R=0, G=0, B=0, A=235}

function _G.MinimapESP.GetPanel(T)
    local now = _G.RealNow()
    if T.panel and slua.isValid(T.panel) and T.base and slua.isValid(T.base) and (now - T._winT) < 1.0 then return T.panel, T.base end
    T._winT = now
    local panel, base = nil, nil
    pcall(function()
        local UIManager = _G.UIManager
        if not UIManager or not UIManager.UI_Config_InGame then return end
        local win = UIManager.GetUI(UIManager.UI_Config_InGame[T.cfg])
        local root = win and win.UIRoot
        if not root or not slua.isValid(root) then return end
        if T.key == "big" then
            local shown = false
            pcall(function() shown = root.CurrentMapUIBP and root.CurrentMapUIBP.bIsShow == true end)
            if not shown then return end
        end
        local p = root.CommonFunctionAddPanel
        local b = root.MapUIBase
        if (not b or not slua.isValid(b)) and root.CurrentMapUIBP then b = root.CurrentMapUIBP.CurrentMapUI end
        if p and slua.isValid(p) and b and slua.isValid(b) and _G.MWWidgetLive(p) then panel, base = p, b end
    end)
    if T.panel ~= panel then _G.MinimapESP.Clear(T) end
    T.panel, T.base = panel, base
    return panel, base
end

function _G.MinimapESP._NewImg(panel, key, size, z, color)
    local img = _G.MWIconImageAt(panel, 0, 0, size, size, key, 0.5, 0.5, z)
    if not img then return nil end
    pcall(function()
        local FAnchors = FAnchors or import("Anchors") or import("/Script/SlateCore.Anchors")
        if FAnchors and img.slot then img.slot:SetAnchors(FAnchors(0.5, 0.5, 0.5, 0.5)) end
        img.w:SetRenderTransformPivot(FVector2D and FVector2D(0.5, 0.5) or {X=0.5, Y=0.5})
        img.w:SetColorAndOpacity(color)
        img.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
    end)
    img.vis = false; img.x = nil; img.y = nil; img.sc = nil; img.color = color; img.ang = nil
    img.pos = FVector2D and FVector2D(0, 0) or {X=0, Y=0}
    img.scv = FVector2D and FVector2D(1, 1) or {X=1, Y=1}
    return img
end

function _G.MinimapESP.Remove(T, key)
    local it = T.items[key]
    if not it then return end
    for _, k in ipairs({"img", "outline", "wedge"}) do
        local im = it[k]
        if im and im.w and slua.isValid(im.w) then
            if PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs[tostring(im.w)] = nil end
            pcall(function() im.w:RemoveFromParent() end)
        end
    end
    T.items[key] = nil
end

function _G.MinimapESP.Clear(T)
    for key in pairs(T.items) do _G.MinimapESP.Remove(T, key) end
    T.items = {}
    for _, it in ipairs(T.free or {}) do T.items["__f"] = it; _G.MinimapESP.Remove(T, "__f") end
    T.free = {}
end

function _G.MinimapESP.TickTarget(T, Lib)
    local M = _G.MinimapESP
    local panel, base = M.GetPanel(T)
    if not panel then return end
    local center, scale = nil, nil
    pcall(function() center = base.LevelLandScapeCenterC; scale = base:GetLevelToMapScale() end)
    if not center or not scale or scale == 0 then return end
    local seen = {}
    for KeyStr, ESPData in pairs(PlayerMapMarker.ESPWidgets) do
        local ch = ESPData.Character
        if ch and IsValid(ch) and PlayerMapMarker.IsAlive(ch) then
            local loc, fwd = nil, nil
            pcall(function() loc = ch:K2_GetActorLocation(); fwd = ch:GetActorForwardVector() end)
            if loc then
                local it = T.items[KeyStr]
                if not it or not (it.img and _G.MWWidgetLive(it.img.w)) then
                    if it then M.Remove(T, KeyStr) end
                    T.free = T.free or {}
                    while #T.free > 0 and not it do
                        local cand = table.remove(T.free)
                        if cand and cand.img and _G.MWWidgetLive(cand.img.w) then it = cand end
                    end
                    if not it then
                        it = { wedge = M._NewImg(panel, "mm_wedge", M.ImgSize, 50, M.ColorWedge), outline = M._NewImg(panel, "mm_dot", M.ImgSize * M.OutlineScale, 51, M.ColorOutline), img = M._NewImg(panel, "mm_dot", M.ImgSize, 52, M.ColorEnemy) }
                        if not it.img then it = nil end
                    end
                    if it then it.img.ang = nil end
                    T.items[KeyStr] = it
                end
                if it then
                    local ok, mp = pcall(Lib.MapCenterToPointVector2D, loc, center, scale)
                    if ok and mp then
                        seen[KeyStr] = true
                        PlayerMapMarker._PinSet(it.img, true, mp.X, mp.Y)
                        PlayerMapMarker._PinSet(it.outline, true, mp.X, mp.Y)
                        PlayerMapMarker._PinSet(it.wedge, true, mp.X, mp.Y)
                        if fwd then
                            local ok2, mp2 = pcall(Lib.MapCenterToPointVector2D, FVector(loc.X + fwd.X * 200, loc.Y + fwd.Y * 200, loc.Z), center, scale)
                            if ok2 and mp2 then
                                local dx, dy = mp2.X - mp.X, mp2.Y - mp.Y
                                if dx * dx + dy * dy > 1e-6 then
                                    local ang = math.floor(math.deg(math.atan(dx, -dy)) + 0.5) % 360
                                    if it.img.ang ~= ang then
                                        it.img.ang = ang
                                        if it.wedge then pcall(it.wedge.w.SetRenderAngle, it.wedge.w, ang) end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    T.free = T.free or {}
    for key, it in pairs(T.items) do
        if not seen[key] then
            PlayerMapMarker._PinSet(it.img, false); PlayerMapMarker._PinSet(it.outline, false); PlayerMapMarker._PinSet(it.wedge, false)
            T.items[key] = nil
            if #T.free < 40 then T.free[#T.free + 1] = it else T.items[key] = it; M.Remove(T, key) end
        end
    end
end

function _G.MinimapESP.Tick()
    local M = _G.MinimapESP
    if not _G.MWHud.Ready() then return end
    if not _G.MWConfig.EspMinimap or not _G.MWConfig.EspPlayer then
        for _, T in ipairs(M.targets) do if next(T.items) then M.Clear(T) end end
        return
    end
    local Lib = M._Lib
    if not Lib then Lib = import("STExtraMapFunctionLibrary") or import("/Script/ShadowTrackerExtra.STExtraMapFunctionLibrary"); M._Lib = Lib end
    if not Lib then return end
    for _, T in ipairs(M.targets) do pcall(M.TickTarget, T, Lib) end
end

_G.ItemLabels = { items = {}, Font = 8, ZOff = 50, MaxPool = 100, ScaleMin = 0.72, ScaleMax = 1.25, ScaleRefCm = 2500, AmmoTextGap = 2,
