local function LMlin(c) if c <= 0.04045 then return c / 12.92 end return ((c + 0.055) / 1.055) ^ 2.4 end
local function LMcol(c) return FLinearColor(LMlin(c[1]), LMlin(c[2]), LMlin(c[3]), c[4]) end
local function LMslate(c)
    local FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor")
    local lc = LMcol(c)
    if FSlateColor then return FSlateColor(lc) end
    return lc
end
function LM.Rows()
    if not _G.MWMenuRows and _G._ModMenuDef then
        _G.MWMenuRows = {}
        for _, cat in ipairs(_G._ModMenuDef.Category or {}) do
            for _, row in ipairs(cat.Stack or {}) do if row.Key then _G.MWMenuRows[row.Key] = row end end
        end
    end
    return _G.MWMenuRows
end
function LM.UIType(R)
    local ok, AM = pcall(require, "client.slua.umg.NewSetting.Item.AliasMap")
    if ok and AM then
        if R.UI == AM.TitleSwitcher then return "title" end
        if R.UI == AM.Slider then return "slider" end
    end
    if R.MinValue ~= nil and R.MaxValue ~= nil then return "slider" end
    if R.ExpandIndex ~= nil then return "title" end
    return "switch"
end
function LM.Label(key)
    local R = LM.Rows() and LM.Rows()[key]
    if not R then return key end
    local t = R.Text
    if type(t) == "number" then return (_G._FakeTextMap and _G._FakeTextMap[t]) or tostring(t) end
    return tostring(t)
end
function LM.OptLabel(id) if type(id) == "number" then return (_G._FakeTextMap and _G._FakeTextMap[id]) or tostring(id) end return tostring(id) end
function LM.Lang() return true end
function LM.Protect(w) if not PlayerMapMarker._ProtectedWidgetStrs then PlayerMapMarker._ProtectedWidgetStrs = {} end; PlayerMapMarker._ProtectedWidgetStrs[tostring(w)] = true end
function LM.Rect(x, y, w, h, c, z, list)
    local k = LM.k
    local b = nil
    pcall(function() b = CGame:NewObjectFromPath("/Script/UMG.Border", LM.root) end)
    if not b or not slua.isValid(b) then return nil end
    pcall(function() b:SetBrushColor(LMcol(c)) end)
    pcall(function() b:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end)
    local slot = nil
    pcall(function() slot = LM.root:AddChildToCanvas(b) end)
    if slot then pcall(function() slot:SetAutoSize(false); slot:SetPosition(FVector2D(x * k, y * k)); slot:SetSize(FVector2D(w * k, h * k)); slot:SetZOrder(z or 1) end) end
    LM.Protect(b)
    local it = { w = b, slot = slot }
    if list then list[#list + 1] = it end
    return it
end
function LM.Img(key, x, y, w, h, c, z, list, angle)
    local k = LM.k
    local it = _G.MWIconImageAt(LM.root, x * k, y * k, w * k, h * k, key, 0, 0, z or 5)
