    if angle then pcall(function() it.w:SetRenderTransformPivot(FVector2D(0.5, 0.5)); it.w:SetRenderAngle(angle) end) end
    if list then list[#list + 1] = it end
    return it
end
function LM.Text(str, x, y, size, c, ax, ay, z, list, outline)
