    if slot then pcall(function() slot:SetAutoSize(true); slot:SetPosition(FVector2D(x * k, y * k)); slot:SetAlignment(FVector2D(ax or 0, ay or 0)); slot:SetZOrder(z or 6) end) end
    LM.Protect(t)
