        pcall(function() btn.WidgetStyle.Normal.TintColor = FSlateColor(tr) end)
        pcall(function() btn.WidgetStyle.Hovered.TintColor = FSlateColor(tr) end)
        pcall(function() btn.WidgetStyle.Pressed.TintColor = FSlateColor(tr) end)
        pcall(function() btn:SetBrushColor(tr) end)
        pcall(function() btn.bIsFocusable = false end)
        pcall(function() btn.IsFocusable = false end)
        if onClick then btn.OnClicked:Add(function() pcall(onClick) end) end
        if onPress then btn.OnPressed:Add(function() pcall(onPress) end) end
        if onRelease then btn.OnReleased:Add(function() pcall(onRelease) end) end
        local slot = LM.root:AddChildToCanvas(btn)
        if slot then pcall(function() slot:SetAutoSize(false); slot:SetPosition(FVector2D(x * k, y * k)); slot:SetSize(FVector2D(w * k, h * k)); slot:SetZOrder(z or 10) end) end
        pcall(function() btn:SetWidgetVisibility(UEnums.ESlateVisibility.Visible) end)
        LM.Protect(btn)
        local it = { w = btn, slot = slot }
        if list then list[#list + 1] = it end
    end)
    return btn
end
function LM.Clear(list)
    for _, it in ipairs(list) do
        if it.w and slua.isValid(it.w) then pcall(function() it.w:RemoveFromParent() end) end
    end
    for i = #list, 1, -1 do list[i] = nil end
end
function LM.RoundRect(x, y, w, h, r, c, z, list, leftOnly)
    LM.Rect(x + r, y, w - (leftOnly and r or 2 * r), r, c, z, list)
    LM.Rect(x, y + r, w, h - 2 * r, c, z, list)
    LM.Rect(x + r, y + h - r, w - (leftOnly and r or 2 * r), r, c, z, list)
    LM.Img("ui_corner", x, y, r, r, c, z, list, 0)
    LM.Img("ui_corner", x, y + h - r, r, r, c, z, list, 270)
    if not leftOnly then
        LM.Img("ui_corner", x + w - r, y, r, r, c, z, list, 90)
        LM.Img("ui_corner", x + w - r, y + h - r, r, r, c, z, list, 180)
    end
end
function LM.ExpireText()
    local d = nil
    pcall(function()
        local e = _G.__MW_EXPIRY
        if type(e) == "string" then
            local yr, mn, dy = e:match("^(%d+)-(%d+)-(%d+)$")
            if yr then d = string.format("%02d/%02d/%s", tonumber(dy), tonumber(mn), yr) end
        end
    end)
    if not d then pcall(function() d = os.date("%d/%m/%Y", limitTime) end) end
    return "Expire: " .. tostring(d or "Unknown")
end
function LM.Create(pc)
    if LM.root and _G.MWWidgetLive(LM.root) then return true end
    LM.root = nil; LM.items = {}; LM.content = {}; LM.drop = {}; LM.drag = nil
    if not PlayerMapMarker.InitESPCanvas() then return false end
    local canvas = PlayerMapMarker.ESPCanvas
    if not canvas or not Game:IsValid(canvas) then return false end
    local W, H = 1920, 1080
    pcall(function() W, H = PlayerMapMarker.GetDynamicViewportSize(pc) end)
    local k = math.min(H * 0.75 / 678, W * 0.73 / 1104)
    LM.k = k
    local mw, mh = 1104 * k, 678 * k
    local root = nil
    pcall(function() root = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", canvas) end)
    if not root or not slua.isValid(root) then return false end
    local rs = nil
    pcall(function() rs = canvas:AddChildToCanvas(root) end)
    local cx, cy = W * 0.5, H * 0.5
    pcall(function() local a, b = PlayerMapMarker._ScreenCenterCanvas(pc); if a and b then cx, cy = a, b end end)
    if rs then pcall(function() rs:SetAutoSize(false); rs:SetPosition(FVector2D(cx - mw * 0.5, cy - mh * 0.5)); rs:SetSize(FVector2D(mw, mh)); rs:SetZOrder(1200) end) end
    LM.Protect(root)
    LM.root, LM.rootSlot = root, rs
    LM.RoundRect(0, 0, 1104, 678, 14, LM.C.win, 1, LM.items)
    LM.Button(0, 0, 1104, 678, 2, LM.items, function() end)
    LM.RoundRect(0, 0, 267, 678, 14, LM.C.side, 3, LM.items, true)
    LM.Img("ui_logo", 21, 44, 82, 82, nil, 5, LM.items)
    LM.Text("PUBG", 111, 44, 28, LM.C.cyan, 0, 0, 6, LM.items, true)
    LM.Text("MW", 146, 82, 28, LM.C.logoWhite, 0.5, 0, 6, LM.items, true)
    LM.Text(LM.ExpireText(), 133, 652, 20, LM.C.navText, 0.5, 0.5, 6, LM.items)
    do
        local xs = 30
        local xx, xy = 1104 - 18 - xs, (63 - xs) * 0.5
        local xi = LM.Img("ui_close", xx, xy, xs, xs, nil, 6, LM.items)
        LM.Button(xx - 8, xy - 8, xs + 16, xs + 16, 12, LM.items,
            function()
                pcall(function() if _G.FpsButton then _G.FpsButton.open = false end end)
                LM.SetOpen(false, pc)
            end,
            function() LM.FxScale(xi, 0.9) end,
            function() LM.FxScale(xi, 1.0) end)
    end
    LM.BuildNav()
    LM.BuildTabs()
    LM.BuildContent()
    pcall(function() root:SetWidgetVisibility(LM.open and UEnums.ESlateVisibility.Visible or UEnums.ESlateVisibility.Collapsed) end)
    return true
end
LM.nav = {}
function LM.FxScale(it, sc)
    pcall(function()
        if it and it.w and slua.isValid(it.w) then
            it.w:SetRenderTransformPivot(FVector2D(0.5, 0.5))
            it.w:SetRenderScale(FVector2D(sc, sc))
        end
    end)
end
function LM.FxTint(it, c)
    pcall(function() if it and it.w and slua.isValid(it.w) then it.w:SetColorAndOpacity(LMslate(c)) end end)
end
function LM.FxRemove(it)
    pcall(function() if it and it.w and slua.isValid(it.w) then it.w:RemoveFromParent() end end)
end
function LM.BuildNav()
    LM.Clear(LM.nav)
    for i, sec in ipairs(LM.Layout) do
        local y = 224 + (i - 1) * 60
        local on = (i == LM.sec)
        if on then
            LM.Rect(0, y, 267, 60, LM.C.navOn, 4, LM.nav)
            LM.Rect(0, y, 4, 60, LM.C.cyan, 5, LM.nav)
        end
        local ic = LM.Img(sec.icon, 44, y + 14, 32, 32, nil, 5, LM.nav)
        local baseC = on and LM.C.cyan or LM.C.navText
        local tx = LM.Text(sec.name, 90, y + 30, 26, baseC, 0, 0.5, 6, LM.nav)
        local hl = nil
        LM.Button(0, y, 267, 60, 10, LM.nav,
            function() LM.sec = i; LM.tab = 1; LM.BuildNav(); LM.BuildTabs(); LM.BuildContent() end,
            function()
                if not on then hl = LM.Rect(0, y, 267, 60, LM.C.navOn, 4, LM.nav) end
                LM.FxScale(ic, 0.9); LM.FxScale(tx, 0.9); LM.FxTint(tx, LM.C.cyan)
            end,
            function()
                LM.FxRemove(hl); hl = nil
                LM.FxScale(ic, 1.0); LM.FxScale(tx, 1.0); LM.FxTint(tx, baseC)
            end)
    end
end
LM.tabs = {}
function LM.BuildTabs()
    LM.Clear(LM.tabs)
    local sec = LM.Layout[LM.sec]
    local x0, tw = 267, 154
    for i, tab in ipairs(sec.tabs) do
        local x = x0 + (i - 1) * tw
        local on = (i == LM.tab)
        local baseC = on and LM.C.cyan or LM.C.tabText
        local tx = LM.Text(LM.Lang() and tab.en or tab.vn, x + tw * 0.5, 31, 22, baseC, 0.5, 0.5, 6, LM.tabs)
        if on then LM.Rect(x, 60, tw, 3, LM.C.cyan, 5, LM.tabs) end
        local hl = nil
        LM.Button(x, 0, tw, 63, 10, LM.tabs,
            function() LM.tab = i; LM.BuildTabs(); LM.BuildContent() end,
            function()
                if not on then hl = LM.Rect(x, 4, tw, 56, LM.C.navOn, 4, LM.tabs) end
                LM.FxScale(tx, 0.9); LM.FxTint(tx, LM.C.cyan)
            end,
            function()
                LM.FxRemove(hl); hl = nil
                LM.FxScale(tx, 1.0); LM.FxTint(tx, baseC)
            end)
    end
end
LM.RowH, LM.Font, LM.Check, LM.TitleH, LM.SliderH = 38, 21, 28, 30, 64
LM.InfoLH = 26
function LM.DeviceInfo()
    local ok, list = pcall(LM.DeviceInfoRaw)
    if ok and type(list) == "table" and #list > 0 then return list end
    local plat, model, osv = "", "", ""
    pcall(function() plat = tostring(Client.GetDevicePlatformName()) end)
    pcall(function() model = tostring(Client.GetDeviceModel()) end)
    pcall(function() osv = tostring(Client.GetOSVersion()) end)
    return { { "Device", model }, { "System", plat .. " " .. osv }, { "Info", "Error: " .. tostring(list):sub(1, 28) } }
end
function LM.DeviceInfoRaw()
    local function raw(fn)
        local r = nil
        pcall(function() if Client and type(Client[fn]) == "function" then r = Client[fn]() end end)
        return r
    end
    local function g(fn)
        local r = raw(fn)
        if r == nil then return "" end
        r = tostring(r)
        if r == "nil" then return "" end
        return r
    end
    local function num(fn) return tonumber(raw(fn)) end
    local function yn(fn) local r = raw(fn); if r == nil then return "" end return r and "Yes" or "No" end
    local function orU(v) if v == nil or v == "" then return "Unknown" end return v end
    local function mb(v, unit)
        if not v then return "" end
        if unit == "GB" then return string.format("%.1f GB", v / 1024) end
        return string.format("%d MB", math.floor(v))
    end

    local plat, model, name, make = g("GetDevicePlatformName"), g("GetDeviceModel"), g("GetDeviceName"), g("GetDeviceMake")
    local osv, app = g("GetOSVersion"), g("GetAppVersion")
    local dev = model ~= "" and model or name
    if plat == "Android" and make ~= "" and dev ~= "" and not dev:lower():find(make:lower(), 1, true) then dev = make .. " " .. dev end
    if dev == "" then dev = "Unknown" end
    local sysName = plat
    if plat == "IOS" then sysName = dev:find("^iPad") and "iPadOS" or "iOS" end
    if sysName == "" then sysName = "Unknown" end
    local isAndroid = (plat == "Android")

    local cores, hz = num("GetCPUCoreCount"), num("GetCPUMaxFrequency")
    local cpu = g("GetCpuType")
    local cpuLine = cpu
    if cores then cpuLine = (cpuLine ~= "" and (cpuLine .. " ") or "") .. math.floor(cores) .. " cores" end
    if hz and hz > 0 then cpuLine = cpuLine .. string.format(" @ %.2f GHz", hz / 1e9) end

    local usedMB = nil
    pcall(function() local st = raw("GetMemoryStats"); if st and st.UsedPhysical then usedMB = st.UsedPhysical / 1024 / 1024 end end)
    local ram = num("GetMemorySize")
    local ramLine = ram and mb(ram, "GB") or ""
    if usedMB then ramLine = ramLine .. (ramLine ~= "" and " / " or "") .. string.format("used %d MB", math.floor(usedMB)) end

    local gl = g("GetGLType"); local glv = g("GetGLVersion")
    local gfx = gl .. ((glv ~= "" and glv ~= gl) and (" " .. glv) or "")

    local notch = ""
    pcall(function()
        local n = raw("GetNotchSize")
        if type(n) == "table" then
            local t = {}
            for i = 1, math.min(#n, 4) do t[#t + 1] = tostring(math.floor(tonumber(n[i]) or 0)) end
            notch = table.concat(t, " / ")
        elseif n ~= nil then notch = tostring(n) end
    end)

    local carrier = g("GetTelecomSvr")
    if carrier == "" then carrier = g("GetOperator") end
    if carrier == "" then
        local cj = g("GetCarrierInfo")
        if cj ~= "" then carrier = cj end
    end

    local emu = yn("IsEmulator")
    local emuName = g("GetEmulatorName")
    if emu == "Yes" and emuName ~= "" then emu = "Yes (" .. emuName .. ")" end

    local lang = g("GetCurrentLanguage"); local sysLang = g("GetSystemLanguage")
    local langLine = lang
    if sysLang ~= "" and sysLang ~= lang then langLine = langLine .. " / sys " .. sysLang end

    local sw, sh = num("GetScreenWidth"), num("GetScreenHight")
    local pw, ph = num("GetPhysicalScreenWidth"), num("GetPhysicalScreenHeight")
    local lvl = g("GetTCDeviceLevel"); local exact = g("GetExactDeviceLevel")
    local lvlLine = lvl
    if exact ~= "" and exact ~= lvl then lvlLine = lvlLine .. " / " .. exact end

    local list = {
        { "Device",     dev },
        { "Nick Name",  orU(g("GetDeivceNickName")) },
        { "Hardware",   orU(g("GetPhoneType")) },
        { "System",     sysName .. (osv ~= "" and (" " .. osv) or "") },
        { "Version",    orU(app) },
        { "Language",   orU(langLine) },
        { "CPU",        orU(cpuLine) },
        { "GPU",        orU(g("GetGPUFamily")) },
        { "RAM",        orU(ramLine) },
        { "Free Space", orU(mb(num("GetDeviceFreeSpace"), "GB")) },
        { "Graphics",   orU(gfx) },
        { "Vulkan",     orU(yn("IsSupportVulkan")) },
        { "Dev Level",  orU(lvlLine) },
        { "Quality",    orU(g("GetDeviceQualityLevel")) },
        { "Low Memory", orU(yn("IsLowMemoryDevice")) },
        { "Screen",     (sw and sh) and (math.floor(sw) .. " x " .. math.floor(sh)) or "Unknown" },
        { "Physical",   (pw and ph) and (math.floor(pw) .. " x " .. math.floor(ph)) or "Unknown" },
        { "Density",    orU(g("GetScreenDensity")) },
        { "Notch",      orU(notch) },
        { "Network",    orU(g("GetNetWorkType")) },
        { "Local IP",   orU(g("GetIpAddr")) },
        { "IP Region",  orU(g("GetIPRegion")) },
        { "Region",     orU(g("GetPublishRegion")) },
        { "Carrier",    orU(carrier) },
        { "VPN",        orU(yn("GetIsPlayerUsingVPN")) },
        { "Time Zone",  orU(g("GetTimezoneName")) },
        { "Server IP",  orU(g("GetDSConnectionIP")) },
        { "Emulator",   orU(emu) },
        { "Gyroscope",  orU(yn("IsDeviceSupportGyrSensor")) },
        { "Bluetooth",  orU(yn("IsUsingBluetooth")) },
        { "Device ID",  orU(g("GetPhoneDeviceID")) },
        { "Ad ID",      orU(g("GetPhoneAdvertisingID")) },
        { "XID",        orU(g("GetDeviceXID")) },
        { "Login",      orU(g("GetLoginChannel")) },
        { "Game Mode",  orU(g("GetGameModeID")) },
    }
    if isAndroid then
        list[#list + 1] = { "Android SO", orU(g("GetAndroidSOVersion")) }
        list[#list + 1] = { "Google Svc", orU(g("GetGoogleServiceVersionCode")) }
    end
    for _, li in ipairs(list) do
        local v = tostring(li[2])
        if #v > 24 then v = v:sub(1, 24) end
        li[2] = v
    end
    return list
end
function LM.BuildContent()
    LM.CloseDrop(); LM.Clear(LM.content); LM.drag = nil
    local sec = LM.Layout[LM.sec]; local tab = sec.tabs[LM.tab]
    local x, y = 282, 71
    local cw = 809
    local need = 0
    local infoList = nil
    for _, key in ipairs(tab.keys) do
        local R = LM.Rows() and LM.Rows()[key]
        if key:sub(1, 7) == "_title:" or (R and LM.UIType(R) == "title") then need = need + LM.TitleH
        elseif key:sub(1, 6) == "_info:" then
            infoList = infoList or LM.DeviceInfo()
            need = need + 4 + math.ceil(#infoList / 2) * LM.InfoLH
        elseif key:sub(1, 5) == "_btn:" then need = need + LM.RowH + 14
        elseif R and LM.UIType(R) == "slider" then need = need + LM.SliderH
        elseif R then need = need + LM.RowH end
    end
    local avail = 678 - 20 - y
    local f = 1.0
    if need > avail then f = math.max(0.72, avail / need) end
    LM.f = f
    local first = true
    for _, key in ipairs(tab.keys) do
        local R = LM.Rows() and LM.Rows()[key]
        local titleStr = nil
        if key:sub(1, 7) == "_title:" then
            local s = key:sub(8); local vn, en = s:match("^(.-)|(.*)$"); if not vn then vn, en = s, s end
            titleStr = LM.Lang() and en or vn
        elseif R and LM.UIType(R) == "title" then titleStr = LM.Label(key) end
        if titleStr then
            y = y + (first and 2 or 6) * f
            LM.Text(string.upper(titleStr), x, y, 16 * f, LM.C.cyan, 0, 0, 6, LM.content)
            y = y + (LM.TitleH - 6) * f
        elseif key:sub(1, 6) == "_info:" then
            infoList = infoList or LM.DeviceInfo()
            y = y + 4 * f
            local half = math.ceil(#infoList / 2)
            local colW = cw * 0.5
            for i, li in ipairs(infoList) do
                local col = (i > half) and 1 or 0
                local row = (i - 1) % half
                local lx = x + col * colW
                local ly = y + (row + 0.5) * LM.InfoLH * f
                LM.Text(li[1], lx, ly, 17 * f, LM.C.tabText, 0, 0.5, 6, LM.content)
                LM.Text(li[2], lx + 108 * f, ly, 17 * f, LM.C.rowText, 0, 0.5, 6, LM.content)
            end
            y = y + half * LM.InfoLH * f
        elseif key:sub(1, 5) == "_btn:" then
            local id, label = key:sub(6):match("^(.-)|(.*)$")
            if not id then id, label = key:sub(6), key:sub(6) end
            y = y + 14 * f
            local pw, ph = 232 * f, 32 * f
            local rh = LM.RowH * f
            local pill = LM.Img("ui_pill", x, y + (rh - ph) * 0.5, pw, ph, nil, 5, LM.content)
            local lbl = LM.Text(label, x + pw * 0.5, y + rh * 0.5, 19 * f, LM.C.pillText, 0.5, 0.5, 6, LM.content)
            local function setPressed(p)
                local sc = p and 0.93 or 1.0
                pcall(function()
                    if pill and pill.w and slua.isValid(pill.w) then
                        pill.w:SetRenderTransformPivot(FVector2D(0.5, 0.5))
                        pill.w:SetRenderScale(FVector2D(sc, sc))
                        pill.w:SetColorAndOpacity(p and LMcol(LM.C.cyan) or LMcol(LM.C.white))
                    end
                    if lbl and lbl.w and slua.isValid(lbl.w) then
                        lbl.w:SetRenderTransformPivot(FVector2D(0.5, 0.5))
                        lbl.w:SetRenderScale(FVector2D(sc, sc))
                        lbl.w:SetOpacity(p and 0.6 or 1.0)
                    end
                end)
            end
            LM.Button(x, y, pw, rh, 10, LM.content, function()
                if id == "reset" and _G.MWResetSettings then
                    pcall(_G.MWResetSettings)
                    pcall(function() LM.BuildTabs(); LM.BuildContent() end)
                end
            end, function() setPressed(true) end, function() setPressed(false) end)
            y = y + rh
        elseif R then
            if LM.UIType(R) == "slider" then LM.RowSlider(R, key, x, y, cw, f); y = y + LM.SliderH * f
            elseif R.SwitcherText then LM.RowDrop(R, key, x, y, cw, f); y = y + LM.RowH * f
            else LM.RowCheck(R, key, x, y, cw, f); y = y + LM.RowH * f end
        end
        first = false
    end
end
function LM.RowCheck(R, key, x, y, cw, f)
    f = f or 1
    local on = false; pcall(function() on = R.GetFunc() and true or false end)
    local ck = LM.Check * f
    local img = LM.Img(on and "ui_check_on" or "ui_check_off", x, y + (LM.RowH * f - ck) * 0.5, ck, ck, nil, 5, LM.content)
    local tx = LM.Text(LM.Label(key), x + ck + 12 * f, y + LM.RowH * f * 0.5, LM.Font * f, LM.C.rowText, 0, 0.5, 6, LM.content)
    local function grow(p)
        pcall(function()
            if tx and tx.w and slua.isValid(tx.w) then
                tx.w:SetRenderTransformPivot(FVector2D(0, 0.5))
                local sc = p and 1.08 or 1.0
                tx.w:SetRenderScale(FVector2D(sc, sc))
            end
        end)
    end
    LM.Button(x, y, cw, LM.RowH * f, 10, LM.content, function()
        local cur = false; pcall(function() cur = R.GetFunc() and true or false end)
        pcall(function() R.SetFunc(nil, not cur) end)
        local now = false; pcall(function() now = R.GetFunc() and true or false end)
        if img then _G.MWIconSet(img, now and "ui_check_on" or "ui_check_off") end
    end, function() grow(true) end, function() grow(false) end)
end
function LM.RowDrop(R, key, x, y, cw, f)
    f = f or 1
    local vals, texts = R.SwitcherValue or {}, R.SwitcherText or {}
    local function idx()
        local cur = nil; pcall(function() cur = R.GetFunc() end)
        for i, v in ipairs(vals) do if v == cur then return i end end
        return 1
    end
    local pw, ph = 232 * f, 32 * f
    local rh = LM.RowH * f
    local py = y + (rh - ph) * 0.5
    local bw = 1.5 / LM.k
    local aw = ph
    LM.Rect(x, py, pw, ph, LM.C.comboEdge, 5, LM.content)
    LM.Rect(x + bw, py + bw, pw - 2 * bw, ph - 2 * bw, LM.C.comboBg, 6, LM.content)
    LM.Rect(x + pw - aw + bw, py + bw, aw - 2 * bw, ph - 2 * bw, LM.C.comboArrowBg, 6, LM.content)
    LM.Rect(x + pw - aw, py + bw, bw, ph - 2 * bw, LM.C.comboEdge, 7, LM.content)
    local asz = 13 * f
    LM.Img("ui_arrow", x + pw - aw + (aw - asz) * 0.5, py + (ph - asz) * 0.5, asz, asz, LM.C.rowText, 7, LM.content)
    local txt = LM.Text(LM.OptLabel(texts[idx()]), x + 10 * f, y + rh * 0.5, 19 * f, LM.C.pillText, 0, 0.5, 8, LM.content)
    LM.Text(LM.Label(key), x + pw + 14 * f, y + rh * 0.5, LM.Font * f, LM.C.rowText, 0, 0.5, 6, LM.content)
    LM.Button(x, y, pw, rh, 10, LM.content, function()
        LM.OpenDrop(R, vals, texts, idx, txt, x, y, pw, rh, f)
    end)
end
LM.drop = LM.drop or {}
function LM.CloseDrop()
    if LM.drop and #LM.drop > 0 then LM.Clear(LM.drop) end
    LM.drop = {}
end
function LM.OpenDrop(R, vals, texts, idx, txt, x, y, pw, rh, f)
    LM.CloseDrop()
    local n = #vals
    if n == 0 then return end
    local itemH = 34 * f
    local pad = 5 * f
    local panelH = n * itemH + pad * 2
    local panelY = y + rh + 2 * f
    if panelY + panelH > 678 - 12 then panelY = y - 2 * f - panelH end
    local cur = idx()
    LM.Button(0, 0, 1104, 678, 40, LM.drop, function() LM.CloseDrop() end)
    local bw = 1.5 / LM.k
    LM.Rect(x, panelY, pw, panelH, LM.C.dropEdge, 44, LM.drop)
    LM.Rect(x + bw, panelY + bw, pw - 2 * bw, panelH - 2 * bw, LM.C.dropBg, 45, LM.drop)
    for i = 1, n do
        local iy = panelY + pad + (i - 1) * itemH
        local isCur = (i == cur)
        if isCur then LM.Rect(x + 4 * f, iy + 2 * f, pw - 8 * f, itemH - 4 * f, LM.C.navOn, 46, LM.drop) end
        local it = LM.Text(LM.OptLabel(texts[i]), x + 16 * f, iy + itemH * 0.5, 18 * f, isCur and LM.C.cyan or LM.C.rowText, 0, 0.5, 47, LM.drop)
        local hl = nil
        LM.Button(x, iy, pw, itemH, 48, LM.drop, function()
            pcall(function() R.SetFunc(nil, vals[i]) end)
            if txt then pcall(function() txt.w:SetText(LM.OptLabel(texts[idx()])) end) end
            LM.CloseDrop()
        end, function()
            pcall(function() if it and it.w then it.w:SetColorAndOpacity(LMslate(LM.C.cyan)) end end)
            hl = LM.Rect(x + 4 * f, iy + 2 * f, pw - 8 * f, itemH - 4 * f, LM.C.navOn, 46, LM.drop)
        end, function()
            pcall(function() if it and it.w and not isCur then it.w:SetColorAndOpacity(LMslate(LM.C.rowText)) end end)
            if hl and hl.w and slua.isValid(hl.w) then pcall(function() hl.w:RemoveFromParent() end) end
        end)
    end
end
function LM.RowSlider(R, key, x, y, cw, f)
    f = f or 1
    local mn, mx = R.MinValue or 0, R.MaxValue or 100
    local function getv() local v = mn; pcall(function() v = R.GetFunc() or mn end); return v end
    local v = getv()
    local tw = 320 * f
    LM.Text(LM.Label(key), x, y + 14 * f, LM.Font * f, LM.C.rowText, 0, 0.5, 6, LM.content)
    local valTxt = LM.Text(tostring(v), x + tw, y + 14 * f, LM.Font * f, LM.C.rowText, 1, 0.5, 6, LM.content)
    pcall(function()
        local sl = CGame:NewObjectFromPath("/Script/UMG.Slider", LM.root)
        if not sl or not slua.isValid(sl) then return end
        pcall(function() sl:SetSliderBarColor(LMcol(LM.C.track)) end)
        pcall(function() sl:SetSliderHandleColor(FLinearColor(0, 0, 0, 0)) end)
        pcall(function() sl:SetStepSize(1 / math.max(1, (mx - mn))) end)
        pcall(function() sl:SetValue((v - mn) / math.max(1e-6, (mx - mn))) end)
        pcall(function() sl.IsFocusable = false end)
        local ks = 22 * f
        local sy = y + 30 * f
        local function knobX(nv) return x + nv * (tw - ks) end
        local knob = LM.Img("ui_knob", knobX((v - mn) / math.max(1e-6, (mx - mn))), sy + (26 * f - ks) * 0.5, ks, ks, LM.C.knob, 11, LM.content)
        sl.OnValueChanged:Add(function(nv)
            pcall(function()
                local val = math.floor(mn + nv * (mx - mn) + 0.5)
                R.SetFunc(nil, val)
                if valTxt then valTxt.w:SetText(tostring(getv())) end
                if knob and knob.slot then knob.slot:SetPosition(FVector2D(knobX(nv) * LM.k, (sy + (26 * f - ks) * 0.5) * LM.k)) end
            end)
        end)
        pcall(function() sl:SetWidgetVisibility(UEnums.ESlateVisibility.Visible) end)
        local slot = LM.root:AddChildToCanvas(sl)
        if slot then pcall(function() slot:SetAutoSize(false); slot:SetPosition(FVector2D(x * LM.k, (y + 30 * f) * LM.k)); slot:SetSize(FVector2D(tw * LM.k, 26 * f * LM.k)); slot:SetZOrder(10) end) end
        LM.Protect(sl)
        LM.content[#LM.content + 1] = { w = sl, slot = slot }
    end)
end
function LM.Tick(pc)
    if true then return end
    if not LM.open or not LM.root or not LM.drag then return end
    pcall(function()
        local tx, ty, pressed = pc:GetInputTouchState(0, nil, nil, nil)
        if not pressed then LM.drag = nil return end
        local cx = PlayerMapMarker.ScreenPixelToCanvasLocalRaw(pc, tx, ty)
        local rx = cx - (LM.rootSlot and LM.rootSlot:GetPosition().X or 0)
        LM.drag.apply(rx)
    end)
end
function LM.SetOpen(open, pc)
    LM.open = open and true or false
    if not LM.open then LM.CloseDrop() end
    if LM.open then
        if not LM.Create(pc) then return end
        LM.BuildContent()
    end
    if LM.root and slua.isValid(LM.root) then
        pcall(function() LM.root:SetWidgetVisibility(LM.open and UEnums.ESlateVisibility.Visible or UEnums.ESlateVisibility.Collapsed) end)
    end
end
function LM.Reset() LM.root = nil; LM.rootSlot = nil; LM.items = {}; LM.nav = {}; LM.tabs = {}; LM.content = {}; LM.drop = {}; LM.drag = nil end


function _G.MWIsAirVeh(veh)
    if not Valid(veh) then return false end
    local air = false
    pcall(function() if type(veh.IsAirVehicle) == "function" and veh:IsAirVehicle() then air = true end end)
    if air then return true end
    do
        local st = nil
        pcall(function() st = veh.VehicleShapeType end)
        if st ~= nil then
            if not _G.MWAirShapes then
                _G.MWAirShapes = {}
                pcall(function()
                    local E = import("ESTExtraVehicleShapeType")
                    if E then
                        for _, k in ipairs({ "VST_UH60", "VST_HeavyUH60", "VST_Motorglider", "VST_WingMan", "VST_Fighter", "VST_Aircraft", "VST_Pterosaur" }) do
                            if E[k] ~= nil then _G.MWAirShapes[E[k]] = true end
                        end
                    end
                end)
            end
            if _G.MWAirShapes[st] then return true end
        end
    end
    local n = ""
    pcall(function()
        local cls = veh:GetClass()
        if cls then n = cls:GetName() or "" end
    end)
    if n == "" then n = tostring(veh) end
    if n:find("UH60") or n:find("AH6") or n:find("Heli") or n:find("VH_Fighter") or n:find("Motorglider")
        or n:find("Aircraft") or n:find("Plane") or n:find("Glider") or n:find("Fighter")
        or n:find("Pterosaur") or n:find("BioVehicle") or n:find("Jet") or n:find("Wing") then
        return true
    end
    local okP, pm = pcall(function() return veh.PterosaurMoveComponent end)
    if okP and Valid(pm) then return true end
    local okH, hm = pcall(function() return veh.HelicopterVehicleMovement end)
    if okH and Valid(hm) then return true end
    local okA, am = pcall(function() return veh.AircraftMovement end)
    if okA and Valid(am) then return true end
    return false
end

function _G.MWIsHeli(veh)
    if not Valid(veh) then return false end
    local n = ""
    pcall(function()
        local cls = veh:GetClass()
        if cls then n = cls:GetName() or "" end
    end)
    if n == "" then n = tostring(veh) end
    if n:find("Motorglider") or n:find("VH_Fighter") or n:find("Fighter") or n:find("Plane") or n:find("Glider") or n:find("Aircraft")
        or n:find("Pterosaur") or n:find("BioVehicle") or n:find("Jet") or n:find("Wing") then
        return false
    end
    local ok, hm = pcall(function() return veh.HelicopterVehicleMovement end)
    return (ok and Valid(hm)) and true or false
end

function _G.MWVehGrounded(veh)
    if not Valid(veh) then return true end
    local grounded = true
    pcall(function()
        local mc = veh.VehicleMovement or veh.MovementComponent
        if not (mc and Valid(mc)) then return end
        if type(mc.GetNumWheelsNotInAir) == "function" then
            grounded = (tonumber(mc:GetNumWheelsNotInAir()) or 1) > 0
        elseif type(mc.GetNumWheelsOnGround) == "function" then
            local n = mc:GetNumWheelsOnGround()
            grounded = (n == true) or (type(n) == "number" and n > 0)
        elseif type(mc.GetNumWheelsInAir) == "function" then
            grounded = (tonumber(mc:GetNumWheelsInAir()) or 0) < 4
        end
    end)
    return grounded
end

_G.MBReticle = {
    R = 24, RV = 36, T = 2, CH = 40, CHW = 6, DOT = 3, NEAR = 70, RefH = 540, Z = 300,
    ORB = 30, ARWSIZE = 34, ARWGAP = 2,
    LockSec = 0.15, LostSec = 0.6,
    lines = nil, ringImg = nil, arwImg = nil, label = nil,
    shown = false, colP = nil, colV = nil, colU = nil, colR = nil, colR2 = nil, scr = nil,
    colRingP = nil, colRingV = nil,
    key = nil, lockT = nil, lastX = nil, lastY = nil, lastVeh = false, lostT = nil,
    corners = { {-1,-1}, {1,-1}, {-1,1}, {1,1} },
}
function _G.MBReticle.Reset()
    local M = _G.MBReticle
    local DL = _G.DrawLine
    if M.lines then for _, l in ipairs(M.lines) do pcall(DL.Remove, l) end end
    local function rmimg(it)
        if it and it.w and slua.isValid(it.w) then
            if _G.PlayerMapMarker._ProtectedWidgetStrs then _G.PlayerMapMarker._ProtectedWidgetStrs[tostring(it.w)] = nil end
            pcall(function() it.w:RemoveFromParent() end)
        end
    end
    rmimg(M.ringImg); rmimg(M.arwImg)
    if M.label and M.label.w then pcall(function() M.label.w:RemoveFromParent() end) end
    M.lines, M.ringImg, M.arwImg, M.label = nil, nil, nil, nil
    M.shown, M.key, M.lockT, M.lastX, M.lastY, M.lostT = false, nil, nil, nil, nil, nil
end
function _G.MBReticle.HideAll()
    local M = _G.MBReticle
    if not M.shown then return end
    local DL = _G.DrawLine
    if M.lines then for _, l in ipairs(M.lines) do pcall(DL.Hide, l) end end
    if M.ringImg and M.ringImg.w then pcall(function() M.ringImg.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
    if M.arwImg and M.arwImg.w then pcall(function() M.arwImg.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end
    if M.label then pcall(_G.PlayerMapMarker._LabelSet, M.label, false) end
    M.shown = false
end
function _G.MBReticle.Tick(pc)
    local M = _G.MBReticle
    local DL = _G.DrawLine
    if not DL then return end
    if not (pc and slua.isValid(pc)) then M.HideAll(); return end
    local PMM = _G.PlayerMapMarker
    local now = (_G.RealNow and _G.RealNow()) or os.clock()
    if not M.colP then pcall(function() M.colP = FLinearColor(0, 1, 0, 1) end) end
    if not M.colV then pcall(function() M.colV = FLinearColor(1.0, 0.29, 0.04, 1) end) end
    if not M.colU then pcall(function() M.colU = FLinearColor(0, 0, 0, 0.55) end) end
    if not M.colR then pcall(function() M.colR = FLinearColor(1, 0.03, 0.03, 1) end) end
    if not M.colR2 then pcall(function() M.colR2 = FLinearColor(1, 0.03, 0.03, 0.3) end) end
    if not M.colRingP then pcall(function() M.colRingP = FLinearColor(0, 1, 0, 0.32) end) end
    if not M.colRingV then pcall(function() M.colRingV = FLinearColor(1.0, 0.29, 0.04, 0.32) end) end
    if not M.scr then pcall(function() M.scr = FVector2D(0, 0) end) end
    if not M.lines then
        M.lines = {}
        for i = 1, 8 do M.lines[i] = DL.Create(M.Z + 1) end
        if not M.lines[8] then M.Reset(); return end
    end
    local has = _G.BulletTrack_HasTarget and _G.BulletTrack_HasTarget()
    local ux0, uy0 = PMM._ScreenCenterCanvas(pc)
    local W = PMM._VpPxW or 1920
    local H = PMM._VpPxH or 1080
    local sc = H / M.RefH
    local S2C = PMM.ScreenPixelToCanvasLocalRaw
    local ux, uy = W * 0.5, H * 0.5
    local tx, ty, col, isVeh = nil, nil, nil, false
    if has then
        local key = _G.BulletTrack_TargetKey and _G.BulletTrack_TargetKey() or "?"
        if key ~= M.key then M.key = key; M.lockT = now end
        M.lostT = nil
        isVeh = _G.BulletTrack_IsVehicleTarget() and true or false
        col = isVeh and M.colV or M.colP
        local tp = _G.BulletTrack_TargetPos and _G.BulletTrack_TargetPos()
        if tp and M.scr then
            pcall(function()
                M.scr.X = 0; M.scr.Y = 0
                local okp = pc:ProjectWorldLocationToScreen(FVector(tp.X, tp.Y, tp.Z), M.scr, false)
                if okp then tx, ty = M.scr.X, M.scr.Y end
            end)
            if not tx then
                pcall(function()
                    local GS = import("GameplayStatics")
                    local KML = import("KismetMathLibrary")
                    local cam = GS.GetPlayerCameraManager(pc, 0)
                    if not (cam and slua.isValid(cam)) then return end
                    local cl = cam:GetCameraLocation()
                    local rot = cam:GetCameraRotation()
                    local rv, uv = KML.GetRightVector(rot), KML.GetUpVector(rot)
                    local rx, ry, rz = tp.X - cl.X, tp.Y - cl.Y, tp.Z - cl.Z
                    local sx = rx * rv.X + ry * rv.Y + rz * rv.Z
                    local sy = -(rx * uv.X + ry * uv.Y + rz * uv.Z)
                    local d = math.sqrt(sx * sx + sy * sy)
                    if d < 1 then sx, sy, d = 0, 1, 1 end
                    tx, ty = ux + sx / d * W * 2, uy + sy / d * W * 2
                end)
            end
        end
        if tx then M.lastX, M.lastY, M.lastVeh = tx, ty, isVeh end
    else
        M.key, M.lastX, M.lastY, M.lostT = nil, nil, nil, nil
        M.HideAll(); return
    end
    if not tx then M.HideAll(); return end
    local T = math.max(1, M.T * sc)
    local age = now - (M.lockT or now)
    local k = math.min(1, age / M.LockSec)
    local shrink = 1.6 - 0.6 * k
    local R = (isVeh and M.RV or M.R) * sc * shrink
    local L = R * 0.45
    local inside = tx >= 0 and tx <= W and ty >= 0 and ty <= H
    local li = 0
    for _, cxy in ipairs(M.corners) do
        local sx, sy = cxy[1], cxy[2]
        local ox, oy = tx + sx * R, ty + sy * R
        local segs = { { ox, oy, ox - sx * L, oy }, { ox, oy, ox, oy - sy * L } }
        for _, sg in ipairs(segs) do
            li = li + 1
            if inside then
                local ax, ay = S2C(pc, sg[1], sg[2])
                local bx, by = S2C(pc, sg[3], sg[4])
                if ax and bx then
                    pcall(DL.Update, M.lines[li], ax, ay, bx, by, col, T)
                end
            else
                pcall(DL.Hide, M.lines[li])
            end
        end
    end
    do
        local canvas = DL.GetCanvas()
        if canvas then
            if not M.ringImg or not _G.MWWidgetLive(M.ringImg.w) then
                if M.ringImg and M.ringImg.w then pcall(function() M.ringImg.w:RemoveFromParent() end) end
                M.ringImg = _G.MWIconImageAt(canvas, 0, 0, 10, 10, "mb_ring", 0.5, 0.5, M.Z)
                if M.ringImg then M.ringImg.pos = FVector2D(0, 0); M.ringImg._sz = nil end
            end
            if not M.arwImg or not _G.MWWidgetLive(M.arwImg.w) then
                if M.arwImg and M.arwImg.w then pcall(function() M.arwImg.w:RemoveFromParent() end) end
                M.arwImg = _G.MWIconImageAt(canvas, 0, 0, 10, 10, "mb_arrow2", 0.5, 0.5, M.Z + 1)
                if M.arwImg then M.arwImg.pos = FVector2D(0, 0); M.arwImg.scv = FVector2D(1, 1); M.arwImg._sz = nil
                    pcall(function() M.arwImg.w:SetRenderTransformPivot(FVector2D(0.5, 0.5)) end) end
            end
        end
        local p = 0.5 + 0.5 * math.sin(now * 5)
        local orbR = M.ORB * sc
        local ringCol = isVeh and M.colRingV or M.colRingP
        if M.ringImg and M.ringImg.w and slua.isValid(M.ringImg.w) then
            local rs = orbR / 0.40
            if M.ringImg._sz ~= rs then M.ringImg._sz = rs; pcall(function() M.ringImg.slot:SetSize(FVector2D(rs, rs)) end) end
            local ax, ay = S2C(pc, ux, uy)
            if ax then M.ringImg.pos.X, M.ringImg.pos.Y = ax, ay; pcall(function() M.ringImg.slot:SetPosition(M.ringImg.pos) end) end
            pcall(function() M.ringImg.w:SetColorAndOpacity(ringCol) end)
            pcall(function() M.ringImg.w:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end)
        end
        local dx, dy = tx - ux, ty - uy
        local d = math.sqrt(dx * dx + dy * dy)
        if M.arwImg and M.arwImg.w and slua.isValid(M.arwImg.w) then
            if d < M.NEAR * sc then
                pcall(function() M.arwImg.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
            else
                local nx, ny = dx / d, dy / d
                local as = M.ARWSIZE * sc
                if M.arwImg._sz ~= as then M.arwImg._sz = as; pcall(function() M.arwImg.slot:SetSize(FVector2D(as, as)) end) end
                local cxp, cyp = ux + nx * (orbR + M.ARWGAP * sc), uy + ny * (orbR + M.ARWGAP * sc)
                local ax, ay = S2C(pc, cxp, cyp)
                if ax then M.arwImg.pos.X, M.arwImg.pos.Y = ax, ay; pcall(function() M.arwImg.slot:SetPosition(M.arwImg.pos) end) end
                local ang = math.deg(math.atan(nx, -ny))
                pcall(function() if type(M.arwImg.w.SetRenderAngle) == "function" then M.arwImg.w:SetRenderAngle(ang) else M.arwImg.w:SetRenderTransformAngle(ang) end end)
                local scv = 1 + p * 0.16
                M.arwImg.scv.X, M.arwImg.scv.Y = scv, scv
                pcall(function() M.arwImg.w:SetRenderScale(M.arwImg.scv) end)
                pcall(function() M.arwImg.w:SetColorAndOpacity(col) end)
                pcall(function() M.arwImg.w:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end)
            end
        end
    end
    M.shown = true
end

_G.MBHitX = { SIZE = 200, GAP = 0.32, TH = 3, DUR = 0.35, POP = 0.08, RefH = 540, Z = 310,
    imgs = nil, t = nil, shown = false, pcKey = nil,
    quads = { {-1,-1,-135}, {1,-1,-45}, {-1,1,135}, {1,1,45} } }
function _G.MBHitX.Reset()
    local M = _G.MBHitX
    if M.imgs then
        for _, it in ipairs(M.imgs) do
            if it and it.w and slua.isValid(it.w) then
                if _G.PlayerMapMarker._ProtectedWidgetStrs then _G.PlayerMapMarker._ProtectedWidgetStrs[tostring(it.w)] = nil end
                pcall(function() it.w:RemoveFromParent() end)
            end
        end
    end
    M.imgs, M.shown = nil, false
end
function _G.MBHitX.Hide()
    local M = _G.MBHitX
    if not M.shown then return end
    if M.imgs then for _, it in ipairs(M.imgs) do pcall(function() it.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end) end end
    M.shown = false
end
function _G.MBHitX.OnDamage()
    if not _G.Mod_BulletTrack then return end
    if not (_G.BulletTrack_RecentTarget and _G.BulletTrack_RecentTarget(1.5)) then return end
    _G.MBHitX.t = _G.RealNow()
end
function _G.MBHitX.Tick(pc)
    local M = _G.MBHitX
    local DL = _G.DrawLine
    if not DL then return end
    if not (pc and slua.isValid(pc)) then M.Hide(); return end
    local key = tostring(pc)
    if M.pcKey ~= key then
        M.pcKey = key
        pcall(function() pc.OnDamageToOther:Add(function() pcall(_G.MBHitX.OnDamage) end) end)
    end
    if not M.t then M.Hide(); return end
    local now = _G.RealNow()
    local age = now - M.t
    if age > M.DUR then M.t = nil; M.Hide(); return end
    local PMM = _G.PlayerMapMarker
    PMM._ScreenCenterCanvas(pc)
    local W = PMM._VpPxW or 1920
    local H = PMM._VpPxH or 1080
    local sc = H / M.RefH
    local S2C = PMM.ScreenPixelToCanvasLocalRaw
    local ux, uy = W * 0.5, H * 0.5
    local size = M.SIZE * sc
    local gap = size * M.GAP
    local len = size * 0.5 - gap
    local th = math.max(2, M.TH * sc)
    if not M.imgs or not _G.MWWidgetLive(M.imgs[1] and M.imgs[1].w) then
        M.Reset()
        local canvas = DL.GetCanvas()
        if not canvas then return end
        M.imgs = {}
        for i, q in ipairs(M.quads) do
            local ic = _G.MWIconImageAt(canvas, 0, 0, len, th, "hitx_stroke", 0, 0.5, M.Z)
            if not ic then M.Reset(); return end
            pcall(function() ic.w:SetRenderTransformPivot(FVector2D(0, 0.5)) end)
            local rotated = false
            pcall(function() if type(ic.w.SetRenderAngle) == "function" then ic.w:SetRenderAngle(q[3]); rotated = true end end)
            if not rotated then pcall(function() ic.w:SetRenderTransformAngle(q[3]) end) end
            ic.pos = FVector2D(0, 0); ic.scv = FVector2D(1, 1)
            M.imgs[i] = ic
        end
    end
    local k = age / M.DUR
    local alpha = 1 - k * k
    local scale = 1.3 - 0.3 * math.min(1, age / M.POP)
    local col = nil
    pcall(function() col = FLinearColor(0, 1, 0, alpha) end)
    local d = 0.70710678
    for i, q in ipairs(M.quads) do
        local it = M.imgs[i]
        local x1, y1 = ux + q[1] * gap * d, uy + q[2] * gap * d
        local ax, ay = S2C(pc, x1, y1)
        if ax and it and it.w and slua.isValid(it.w) then
            it.pos.X, it.pos.Y = ax, ay
            pcall(function() it.slot:SetPosition(it.pos) end)
            it.scv.X, it.scv.Y = scale, scale
            pcall(function() it.w:SetRenderScale(it.scv) end)
            if col then pcall(function() it.w:SetColorAndOpacity(col) end) end
            if not M.shown then pcall(function() it.w:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible) end) end
        end
    end
    M.shown = true
end

function _G.AimFrameTick(dt)
    if isExpired then return end
    local pc = GameplayData.GetPlayerController()
    if not Valid(pc) then return end
    local localPlayer = pc:GetPlayerCharacterSafety()
    if not Valid(localPlayer) then return end
    pcall(_G.MWHud.Refresh)
    pcall(_G.MWIconPreload.Tick)
    pcall(_G.MinimapESP.Tick)
    pcall(_G.MBReticle.Tick, pc)
    pcall(_G.MBHitX.Tick, pc)
    pcall(_G.BulletTrack_TickActive)
    local inMatch = true
    pcall(function() if GameStatus and GameStatus.IsInFightingNotMainCity then inMatch = GameStatus.IsInFightingNotMainCity() and true or false end end)
    if inMatch and _G.MWHud.Ready() then
        pcall(_G.HideWatermark.Tick, pc)
        pcall(_G.FpsButton.Tick, pc, dt)
    end
    pcall(_G.ItemLabels.Tick, pc, localPlayer)
    pcall(_G.MWMenu.Tick, pc)

    pcall(function()
        local veh = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
        if not _G.MWConfig.VehicleInstantStop then return end
        if not Valid(veh) then return end
        if type(veh.GetDriver) == "function" then
            local drv = veh:GetDriver()
            if not Valid(drv) or drv ~= localPlayer then return end
        end
        if _G.MWIsAirVeh(veh) then return end
        if not _G.MWVehGrounded(veh) then return end
        local mc = veh.VehicleMovement or veh.MovementComponent
        if not Valid(mc) then return end
        local throttle = mc.RawThrottleInput
        if throttle == nil then
            throttle = mc.ThrottleInput or 0
            if type(mc.GetThrottleInput) == "function" then throttle = mc:GetThrottleInput() end
        end
        if math.abs(throttle) < 0.05 then return end
        local fwd = 0
        if type(mc.GetForwardSpeed) == "function" then fwd = mc:GetForwardSpeed() or 0 end
        if (throttle < 0 and fwd > 80) or (throttle > 0 and fwd < -80) then
            local rc = veh.RootComponent or (type(veh.K2_GetRootComponent) == "function" and veh:K2_GetRootComponent())
            if Valid(rc) and type(rc.SetAllPhysicsLinearVelocity) == "function" then
                local v = nil
                pcall(function() v = veh:GetVelocity() end)
                rc:SetAllPhysicsLinearVelocity(FVector(0, 0, v and v.Z or 0), false)
            end
        end
    end)

    pcall(function()
        if not _G.MWConfig.FullGrip then return end
        local veh = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
        if not Valid(veh) then return end
        if type(veh.GetDriver) == "function" then
            local drv = veh:GetDriver()
            if not Valid(drv) or drv ~= localPlayer then return end
        end
        local vc = veh.VehicleCommon
        if not slua.isValid(vc) and type(veh.GetVehicleCommon) == "function" then vc = veh:GetVehicleCommon() end
        local mov = veh.VehicleMovement or veh.MovementComponent
        if slua.isValid(vc) then
            local wnum = 0
            pcall(function() wnum = (type(vc.GetWheelsHPNum) == "function" and vc:GetWheelsHPNum()) or (vc.WheelsCurrentHP and vc.WheelsCurrentHP:Num()) or 0 end)
            for i = 0, wnum - 1 do
                local destroyed = false
                pcall(function() destroyed = type(vc.IsWheelDestroyed) == "function" and vc:IsWheelDestroyed(i) == true end)
                if destroyed then
                    pcall(function() if vc.RestoreWheel then vc:RestoreWheel(i) end end)
                    pcall(function() if mov and slua.isValid(mov) and mov.EnableVehicleWheel then mov:EnableVehicleWheel(i, true) end end)
                end
            end
            pcall(function() if vc.RefreshWheelState then vc:RefreshWheelState() end end)
        end
        if slua.isValid(mov) then
            pcall(function() if mov.AntiRollStiffness ~= nil and mov.AntiRollStiffness < 100 then mov.AntiRollStiffness = mov.AntiRollStiffness end end)
            local wheels = mov.WheelHubs or mov.Wheels
            if wheels and type(wheels.Num) == "function" then
                _G.MWState._gripMax = _G.MWState._gripMax or {}
                local store = _G.MWState._gripMax
                for i = 0, wheels:Num() - 1 do
                    local w = wheels:Get(i)
                    if slua.isValid(w) then
                        local key = tostring(w)
                        local rec = store[key]
                        if not rec then rec = { lat = 0, lng = 0 }; store[key] = rec end
                        local lat = tonumber(w.LatStiffValue) or 0
                        local lng = tonumber(w.LongStiffValue) or 0
                        if lat > rec.lat then rec.lat = lat end
                        if lng > rec.lng then rec.lng = lng end
                        if rec.lat > 0 then w.LatStiffValue = rec.lat end
                        if rec.lng > 0 then w.LongStiffValue = rec.lng end
                        pcall(function() local tc = w.TireConfig; if slua.isValid(tc) and (tonumber(tc.FrictionScale) or 0) < 3 then tc.FrictionScale = 3.0 end end)
                    end
                end
            end
        end
    end)

    pcall(_G.CratePin_Tick, pc)
    pcall(_G.VehMark_Tick, pc)

    if _G.MWConfig.AimTouchEnable then
        _G.AimTouch(dt)
    end

    pcall(function()
        if _G.MWConfig.AimTouchEnable and _G.MWConfig.AimTouchShowFOV then
            local curFOV = (_G.MWState and _G.MWState.CustomTextData and _G.MWState.CustomTextData.AimTouchFOV) or 30
            UpdateFOVCircle(curFOV, pc)
        else
            HideFOVCircle()
        end

        UpdateFOVCanvasTransform(pc)
        local aimData = _G.MWState.AimLineScreenPos
        if aimData and _G.MWConfig.AimTouchEnable and _G.MWConfig.AimTouchShowFOV then
            if _G._AimLineWidget and not _G.MWWidgetLive(_G._AimLineWidget.Widget) then DrawLine.Remove(_G._AimLineWidget); _G._AimLineWidget = nil end
            if not _G._AimLineWidget then
                _G._AimLineWidget = DrawLine.Create(10)
            end
            if _G._AimLineWidget then
                local fromX = aimData.cX * FOVCircle_ScaleX + FOVCircle_OffsetX
                local fromY = aimData.cY * FOVCircle_ScaleY + FOVCircle_OffsetY
                local toX = aimData.X * FOVCircle_ScaleX + FOVCircle_OffsetX
                local toY = aimData.Y * FOVCircle_ScaleY + FOVCircle_OffsetY
                if not _G._AimLineColor then _G._AimLineColor = {R=255, G=0, B=0, A=255} end
                DrawLine.Update(_G._AimLineWidget, fromX, fromY, toX, toY, _G._AimLineColor, 3.0)
            end
        else
            if _G._AimLineWidget then
                DrawLine.Hide(_G._AimLineWidget)
            end
        end
    end)
end

if not _G._AimFrameTickRegistered then
    local okReg = pcall(function()
        local hud = require("game_frontend_hud")
        hud.SetSluaTickListener(function(dt)
            if _G.AimFrameTick then pcall(_G.AimFrameTick, dt) end
        end)
    end)
    if okReg then _G._AimFrameTickRegistered = true end
end

local function MainLoop()
    if isExpired then return end

    if _G.MWState.CustomTextData == nil then
        _G.MWState.CustomTextData = _G.MWDefaultTextData()
    end

    local okData, GameplayData = pcall(require, "GameLua.GameCore.Data.GameplayData") 
    if not okData or not GameplayData then return end 
    local pc = GameplayData.GetPlayerController() 
    local localPlayer = nil
    if Valid(pc) then localPlayer = pc:GetPlayerCharacterSafety() end 

    if not Valid(localPlayer) then 
        if _G.PlayerMapMarker and type(_G.PlayerMapMarker.Stop) == "function" then
            _G.PlayerMapMarker.Stop()
        end
        if _G.MWHud then _G.MWHud.ForceReset() end
        if _G.RedBoxOverlay and type(_G.RedBoxOverlay.Stop) == "function" then
            _G.RedBoxOverlay.Stop()
        end
        if _G.CleanUpFOVCircle then _G.CleanUpFOVCircle() end
        if _G._AimLineWidget then DrawLine.Remove(_G._AimLineWidget) _G._AimLineWidget = nil end
        _G.MWState.AimLineScreenPos = nil
        
        if _G.MWState.TrackedMarks then
            for markId, _ in pairs(_G.MWState.TrackedMarks) do
                SafeRemoveMark(markId)
            end
        end
        _G.MWState.TrackedMarks = {} 
        
        for key, data in pairs(_G.MWState.EnemyMarks) do
            if data and data.MIDs then
                for meshStr, midTable in pairs(data.MIDs) do
                    for k, _ in pairs(midTable) do midTable[k] = nil end
                end
                data.MIDs = nil
            end
            if data and data.MIDs_V3 then
                for meshStr, midTable in pairs(data.MIDs_V3) do
                    for k, _ in pairs(midTable) do midTable[k] = nil end
                end
                data.MIDs_V3 = nil
            end
        end
        
        _G.MWState.EnemyMarks = {}
        _G.MWState.PrevGraphicsState = {}
        
        return
    end

    local Cached_PPM = _G._ML_PPM
    if not (Cached_PPM and slua.isValid(Cached_PPM)) then
        Cached_PPM = nil
        pcall(function() Cached_PPM = import("PostProcessManager").GetInstance() end)
        _G._ML_PPM = Cached_PPM
    end
    local Cached_SecurityCommonUtils = _G._ML_SecUtils
    if not Cached_SecurityCommonUtils then
        pcall(function() Cached_SecurityCommonUtils = require("GameLua.Mod.BaseMod.Common.Security.SecurityCommonUtils") end)
        _G._ML_SecUtils = Cached_SecurityCommonUtils
    end
    local Cached_MyHUD = pc and pc.MyHUD or nil

    if _G.MWConfig.UnlockFPS then
        InitializeGraphicsUnlock()
        pcall(function()
            local now = _G.RealNow()
            if now - (_G.MWState.LastFPSEnforce or 0) < 2 then return end
            _G.MWState.LastFPSEnforce = now
            local hud = slua_GameFrontendHUD
            local cfg = hud and hud:GetUserSettings()
            if not cfg then return end
            if cfg.BattleFPS ~= 8 then
                pcall(function() hud:BeginModifyUserSettings() end)
                cfg.BattleFPS = 8
                pcall(function() hud:FinishModifyUserSettings() end)
            end
            local lib = import("STExtraBlueprintFunctionLibrary")
            local cur = lib and lib.GetConsoleVariableFloatValue("t.MaxFPS") or 0
            if cur < 120 then
                local gi = require("client.common.ui_util").GetGameInstance()
                if gi then gi:ExecuteCMD("t.MaxFPS", "240"); gi:ExecuteCMD("r.FrameRateLimit", "240") end
            end
        end)
    end

    pcall(function()
        local now = _G.RealNow()
        if now - (_G.MWState.LastFullResEnforce or 0) < 2 then return end
        _G.MWState.LastFullResEnforce = now
        local lib = import("STExtraBlueprintFunctionLibrary")
        local gi = require("client.common.ui_util").GetGameInstance()
        if not gi then return end
        do
            local plat = ""
            pcall(function() plat = tostring(Client.GetDevicePlatformName()) end)
            local isIOS = (plat == "IOS")
            local target = isIOS and 3.0 or 1.5
            local cur = -1
            pcall(function() cur = lib and lib.GetConsoleVariableFloatValue("r.MobileContentScaleFactor") or -1 end)
            local heartbeat = (now - (_G.MWState.LastFullResForce or 0)) >= 10
            if math.abs(cur - target) > 0.01 or heartbeat then
                _G.MWState.LastFullResForce = now
                local ok = false
                if isIOS and gi.SetMobileContentScaleFactorIOS then ok = pcall(function() gi:SetMobileContentScaleFactorIOS(target) end)
                elseif gi.SetMobileContentScaleFactorAOS then ok = pcall(function() gi:SetMobileContentScaleFactorAOS(target) end) end
                if not ok then pcall(function() gi:SetMobileContentScaleFactor(target) end) end
            end
            if lib then
                local sp = lib.GetConsoleVariableFloatValue("r.ScreenPercentage") or 100
                if sp > 0 and sp < 100 then gi:ExecuteCMD("r.ScreenPercentage", "100") end
            end
            _G.MWState.FullResApplied = true
        end
    end)
    InitializeNativeESP()
    ShowMWVIPMenu()

    if _G.MWConfig.EspItem_Master then
        _G.RunOptimizedItemAndVehicleESP(pc)
    end

    if _G.MWConfig.EspPlayer then
        if _G.PlayerMapMarker and not _G.PlayerMapMarker.bActive then
            _G.PlayerMapMarker.Start()
        end
    else
        if _G.PlayerMapMarker and _G.PlayerMapMarker.bActive then
            _G.PlayerMapMarker.Stop()
        end
    end

    if _G.MWConfig.IpadView and _G.MWState.CustomTextData then
        pcall(function()
            local targetTPP = _G.MWState.CustomTextData.IpadViewFOV2 or 110
            local uTPPCam = localPlayer.ThirdPersonCameraComponent
            if Valid(uTPPCam) and not localPlayer.bIsWeaponAiming then
                if uTPPCam.FieldOfView ~= targetTPP then uTPPCam.FieldOfView = targetTPP end
            end
        end)
    else
        pcall(function()
            local uTPPCam = localPlayer.ThirdPersonCameraComponent
            if Valid(uTPPCam) and not localPlayer.bIsWeaponAiming then
                if uTPPCam.FieldOfView ~= 90 then uTPPCam.FieldOfView = 90 end
            end
        end)
    end


    if _G.MWConfig.IpadViewVehicle and _G.MWState.CustomTextData then
        pcall(function()
            local currentVehicle = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
            if Valid(currentVehicle) then
                local targetFOV = _G.MWState.CustomTextData.IpadVehicleFOV2 or 100
                if currentVehicle.Camera then
                    local vCam = currentVehicle.Camera
                    if Valid(vCam) and vCam.FieldOfView ~= targetFOV then
                        vCam.FieldOfView = targetFOV
                    end
                end
                local GS = import("GameplayStatics")
                local camMgr = GS and GS.GetPlayerCameraManager and GS.GetPlayerCameraManager(pc, 0)
                if camMgr and slua.isValid(camMgr) then
                    camMgr:SetFOV(targetFOV)
                end
            end
        end)
    end



    if not _G._AimFrameTickRegistered then _G.AimFrameTick(nil) end

    if not _G.LastGlowTime or (_G.RealNow() - _G.LastGlowTime) > 0.5 then
        _G.LastGlowTime = _G.RealNow()
        if _G.ApplyWeaponGlow then _G.ApplyWeaponGlow(localPlayer) end
    end


    if _G.MWConfig.ModSkin then
        local curTime = _G.RealNow()
        if not _G.LastSkinUpdateTime or (curTime - _G.LastSkinUpdateTime) > 2.5 then
            _G.LastSkinUpdateTime = curTime
            pcall(function()
                local isAlive = type(localPlayer.IsAlive) == "function" and localPlayer:IsAlive() or true
                if isAlive then
                    if _G.HandlePetLogic then _G.HandlePetLogic() end
                    
                    if _G.MWConfig.SkinDeadBox and _G.DeadBox_TemperRequest and _G.NeedCheckDeadBoxTimer > 0 then
                        _G.DeadBox_TemperRequest(pc)
                    end

                    if _G.AddOutfit then
                        if _G.AddOutfit.isInRealMatch() then
                            _G.AddOutfitLobbyRestored = false 
                            
                            local ticker = require("common.time_ticker")
                            if ticker and ticker.AddTimerOnce then
                                _G.AddOutfit.matchApplyAllSlots(localPlayer)
                                ticker.AddTimerOnce(0.2, function()
                                    if slua.isValid(localPlayer) and _G.AddOutfit.isInRealMatch() then 
                                        _G.AddOutfit.matchApplyHat(localPlayer) 
                                    end
                                end)
                                ticker.AddTimerOnce(0.4, function()
                                    if slua.isValid(localPlayer) and _G.AddOutfit.isInRealMatch() then 
                                        _G.AddOutfit.matchApplyWeaponSkin(localPlayer) 
                                    end
                                end)
                                ticker.AddTimerOnce(0.6, function()
                                    if slua.isValid(localPlayer) and _G.AddOutfit.isInRealMatch() and _G.AddOutfit.isCharacterAirborne(localPlayer) then
                                        _G.AddOutfit.applyAirborneSlots(localPlayer, true)
                                    end
                                end)
                            else
                                _G.AddOutfit.matchApplyAllSlots(localPlayer)
                                _G.AddOutfit.matchApplyHat(localPlayer)
                                _G.AddOutfit.matchApplyWeaponSkin(localPlayer)
                                if _G.AddOutfit.isCharacterAirborne(localPlayer) then
                                    _G.AddOutfit.applyAirborneSlots(localPlayer, true)
                                end
                            end
                        else
                            _G.AddOutfit.reapplyLobbyEquipped()
                        end
                    end
                end
            end)
        end
    end

    pcall(_G.MWHiggs.Tick, pc)

    if _G.MWConfig.FlashSpeed then
        pcall(function()
            if not (localPlayer and slua.isValid(localPlayer)) then return end
            if _G.MWFlashSpeedOrig == nil then
                local cur = localPlayer.SpeedScale
                _G.MWFlashSpeedOrig = (type(cur) == "number") and cur or 1.0
            end
            if localPlayer.SpeedScale ~= 10 then localPlayer.SpeedScale = 10 end
        end)
    elseif _G.MWFlashSpeedOrig ~= nil then
        pcall(function()
            if localPlayer and slua.isValid(localPlayer) then localPlayer.SpeedScale = _G.MWFlashSpeedOrig end
        end)
        _G.MWFlashSpeedOrig = nil
    end


    if not _G.MWConfig.FastCar and _G.MWHeliTurn then
        pcall(function()
            for _, o in pairs(_G.MWHeliTurn) do
                if Valid(o.hm) then
                    if type(o.a) == "number" then o.hm.MaxBackWingTorqueVaule = o.a end
                    if type(o.b) == "number" then o.hm.SecondMaxBackWingTorqueVaule = o.b end
                end
            end
            _G.MWHeliTurn = nil
        end)
    end
    if not _G.MWConfig.FastCar and _G.MWTankTurret then
        pcall(function()
            for _, o in pairs(_G.MWTankTurret) do
                if Valid(o.t) and type(o.s) == "number" then o.t.WeaponRotationLagSpeed = o.s end
            end
            _G.MWTankTurret = nil
        end)
    end
    if not _G.MWConfig.FastCar and _G.MWMecha then
        pcall(function()
            for _, o in pairs(_G.MWMecha) do
                if Valid(o.mc) then
                    if type(o.jz) == "number" then o.mc.JumpZVel = o.jz end
                    if type(o.jjz) == "number" then o.mc.JetJumpZVel = o.jjz end
                    if type(o.jzv) == "number" then o.mc.JumpZVelocity = o.jzv end
                    if type(o.mf) == "number" then o.mc.MaxForwardSpeed = o.mf end
                    if type(o.mb) == "number" then o.mc.MaxBackwardSpeed = o.mb end
                    if type(o.ml) == "number" then o.mc.MaxLateralSpeed = o.ml end
                    if type(o.sr) == "number" then o.mc.SpeedRate = o.sr end
                end
            end
            _G.MWMecha = nil
        end)
    end
    if _G.MWConfig.FastCar then
        pcall(function()
            local tank = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
            if not Valid(tank) then return end
            local n = tostring(tank)
            pcall(function() local c = tank:GetClass() if c then local nm = c:GetName() if nm and nm ~= "" then n = nm end end end)
            if not (n:find("VH_Tank") or n:find("Leopard")) then return end
            if type(tank.GetVehicleWeapon) == "function" then
                local turret = nil
                pcall(function() turret = tank:GetVehicleWeapon(0, 0) end)
                if Valid(turret) then
                    _G.MWTankTurret = _G.MWTankTurret or {}
                    local key = tostring(turret)
                    if not _G.MWTankTurret[key] then
                        _G.MWTankTurret[key] = { t = turret, s = turret.WeaponRotationLagSpeed }
                    end
                    local TANK_TURRET_SPEED = 10000
                    if turret.WeaponRotationLagSpeed ~= TANK_TURRET_SPEED then turret.WeaponRotationLagSpeed = TANK_TURRET_SPEED end
                end
            end
            local moveComp = tank.VehicleMovement or tank.MovementComponent
            local steer = 0
            if Valid(moveComp) then
                pcall(function()
                    steer = moveComp.SteeringInput or 0
                    if type(moveComp.GetSteeringInput) == "function" then steer = moveComp:GetSteeringInput() end
                end)
            end
            if math.abs(steer) > 0.05 then
                local rootComp = tank.RootComponent or (type(tank.K2_GetRootComponent) == "function" and tank:K2_GetRootComponent())
                if Valid(rootComp) then
                    local TANK_BODY_TURN = 60
                    local z = (steer > 0 and 1 or -1) * TANK_BODY_TURN
                    if type(rootComp.SetAllPhysicsAngularVelocityInDegrees) == "function" then
                        pcall(function() rootComp:SetAllPhysicsAngularVelocityInDegrees(FVector(0, 0, z), false) end)
                    elseif type(rootComp.SetPhysicsAngularVelocityInDegrees) == "function" then
                        pcall(function() rootComp:SetPhysicsAngularVelocityInDegrees(FVector(0, 0, z), false, "None") end)
                    end
                end
            end
            local TANK_STRAIGHT_SPEED = 2500
            local TANK_STRAIGHT_ACC = 80
            if Valid(moveComp) and type(moveComp.EnableSpecialAntiCheatSpeed) == "function" then
                pcall(function() moveComp:EnableSpecialAntiCheatSpeed(true, TANK_STRAIGHT_SPEED + 1000) end)
            end
            local mfr = 0
            pcall(function() if type(tank.GetMoveForwardRate) == "function" then mfr = tank:GetMoveForwardRate() or 0 end end)
            if mfr > -0.05 and mfr < 0.05 then
                pcall(function()
                    local mis = tank.MovementInputState
                    if mis and mis.ThrottleInput and math.abs(mis.ThrottleInput) > 0.05 then mfr = mis.ThrottleInput end
                end)
                if mfr > -0.05 and mfr < 0.05 and tank.bIsPressingGas then mfr = 1 end
            end
            local goFwd = mfr > 0.05
            local goRev = mfr < -0.05
            if (goFwd or goRev) and math.abs(steer) < 0.05 then
                local rootComp = tank.RootComponent or (type(tank.K2_GetRootComponent) == "function" and tank:K2_GetRootComponent())
                local fwd = nil
                pcall(function() fwd = tank:GetActorForwardVector() end)
                if Valid(rootComp) and fwd and type(rootComp.SetAllPhysicsLinearVelocity) == "function" then
                    local fl = math.sqrt(fwd.X ^ 2 + fwd.Y ^ 2)
                    if fl > 0.001 then
                        local vel = nil
                        pcall(function() vel = tank:GetVelocity() end)
                        if not vel and type(rootComp.GetPhysicsLinearVelocity) == "function" then vel = rootComp:GetPhysicsLinearVelocity() end
                        local curSpeed = vel and math.sqrt(vel.X ^ 2 + vel.Y ^ 2) or 0
                        local vz = vel and vel.Z or 0
                        local newSpeed = math.min(TANK_STRAIGHT_SPEED, curSpeed + TANK_STRAIGHT_ACC)
                        local sgn = goRev and -1 or 1
                        local dirX, dirY = fwd.X / fl * sgn, fwd.Y / fl * sgn
                        rootComp:SetAllPhysicsLinearVelocity(FVector(dirX * newSpeed, dirY * newSpeed, vz), false)
                    end
                end
            end
        end)
        pcall(function()
            local mecha = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
            if not Valid(mecha) then return end
            local n = tostring(mecha)
            pcall(function() local c = mecha:GetClass() if c then local nm = c:GetName() if nm and nm ~= "" then n = nm end end end)
            if not n:find("Mecha") then return end
            local mc = mecha.VehicleMovement or mecha.MovementComponent
            if not Valid(mc) then return end
            local MECHA_JUMP_MUL = 2.0
            local MECHA_SPEED_MUL = 2.0
            _G.MWMecha = _G.MWMecha or {}
            local key = tostring(mc)
            if not _G.MWMecha[key] then
                _G.MWMecha[key] = {
                    mc = mc,
                    jz = mc.JumpZVel, jjz = mc.JetJumpZVel, jzv = mc.JumpZVelocity,
                    mf = mc.MaxForwardSpeed, mb = mc.MaxBackwardSpeed, ml = mc.MaxLateralSpeed, sr = mc.SpeedRate,
                }
            end
            local o = _G.MWMecha[key]
            local function setMul(field, orig, mul)
                if type(orig) == "number" and orig ~= 0 then
                    local target = orig * mul
                    if mc[field] ~= target then mc[field] = target end
                end
            end
            setMul("JumpZVel", o.jz, MECHA_JUMP_MUL)
            setMul("JetJumpZVel", o.jjz, MECHA_JUMP_MUL)
            setMul("JumpZVelocity", o.jzv, MECHA_JUMP_MUL)
            setMul("MaxForwardSpeed", o.mf, MECHA_SPEED_MUL)
            setMul("MaxBackwardSpeed", o.mb, MECHA_SPEED_MUL)
            setMul("MaxLateralSpeed", o.ml, MECHA_SPEED_MUL)
            setMul("SpeedRate", o.sr, MECHA_SPEED_MUL)
        end)
        pcall(function()
            local currentVehicle = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
            if Valid(currentVehicle) and type(currentVehicle.GetDriver) == "function" then
                local drv = nil
                pcall(function() drv = currentVehicle:GetDriver() end)
                if not Valid(drv) or drv ~= localPlayer then currentVehicle = nil end
            end
            if Valid(currentVehicle) and _G.MWIsHeli(currentVehicle) then
                local heli = currentVehicle
                currentVehicle = nil
                pcall(function()
                    local HELI_MAX_H = 13889
                    local HELI_MAX_DOWN = 5556
                    local hm = heli.HelicopterVehicleMovement
                    local rootComp = heli.RootComponent or (type(heli.K2_GetRootComponent) == "function" and heli:K2_GetRootComponent())
                    if not Valid(rootComp) or type(rootComp.SetAllPhysicsLinearVelocity) ~= "function" then return end
                    if Valid(hm) then
                        _G.MWHeliTurn = _G.MWHeliTurn or {}
                        local key = tostring(hm)
                        if not _G.MWHeliTurn[key] then
                            local HELI_TURN_MUL = 2
                            local o = { hm = hm, a = hm.MaxBackWingTorqueVaule, b = hm.SecondMaxBackWingTorqueVaule }
                            _G.MWHeliTurn[key] = o
                            if type(o.a) == "number" then hm.MaxBackWingTorqueVaule = o.a * HELI_TURN_MUL end
                            if type(o.b) == "number" then hm.SecondMaxBackWingTorqueVaule = o.b * HELI_TURN_MUL end
                        end
                    end
                    local fIn, rIn, uIn = 0, 0, 0
                    if Valid(hm) then
                        fIn = tonumber(hm.ForwardInputRate) or 0
                        rIn = tonumber(hm.RightInputRate) or 0
                        uIn = tonumber(hm.upInputRate) or 0
                    end
                    local isAccel = (math.abs(fIn) > 0.05) or (math.abs(rIn) > 0.05)
                    if heli.bIsPressingGas or (heli.Throttle and heli.Throttle ~= 0) then isAccel = true end
                    local isUp = false
                    local isDown = uIn < -0.05
                    local vel = nil
                    pcall(function() vel = heli:GetVelocity() end)
                    if not vel and type(rootComp.GetPhysicsLinearVelocity) == "function" then vel = rootComp:GetPhysicsLinearVelocity() end
                    if not vel then return end
                    do
                        local sp0 = math.sqrt(vel.X ^ 2 + vel.Y ^ 2)
                        if sp0 > HELI_MAX_H + 100 then
                            rootComp:SetAllPhysicsLinearVelocity(FVector(vel.X / sp0 * HELI_MAX_H, vel.Y / sp0 * HELI_MAX_H, vel.Z), false)
                            pcall(function() vel = heli:GetVelocity() end)
                        end
                    end
                    if not isAccel and not isUp and not isDown then return end
                    local lv = _G.MWState.CustomTextData.FastCarLevel or 50
                    local inc = 20 + lv * 5
                    local speed = math.sqrt(vel.X ^ 2 + vel.Y ^ 2)
                    local nx, ny = vel.X, vel.Y
                    if isAccel then
                        local dirX, dirY
                        if speed > 50 then
                            dirX, dirY = vel.X / speed, vel.Y / speed
                        else
                            local f = nil
                            pcall(function() f = heli:GetActorForwardVector() end)
                            if f then
                                local fl = math.sqrt(f.X ^ 2 + f.Y ^ 2)
                                if fl > 0.001 then
                                    local sgn = (fIn < -0.05) and -1 or 1
                                    dirX, dirY = f.X / fl * sgn, f.Y / fl * sgn
                                end
                            end
                        end
                        if dirX then
                            local newSpeed = math.min(HELI_MAX_H, speed + inc)
                            nx, ny = dirX * newSpeed, dirY * newSpeed
                        end
                    end
                    local nz = vel.Z
                    if isDown then
                        nz = math.max(-HELI_MAX_DOWN, math.min(vel.Z, 0) - inc)
                    end
                    rootComp:SetAllPhysicsLinearVelocity(FVector(nx, ny, nz), false)
                end)
            end
            if Valid(currentVehicle) and _G.MWIsAirVeh(currentVehicle) then currentVehicle = nil end
            if Valid(currentVehicle) then
                local vehName = tostring(currentVehicle)
                pcall(function()
                    local cls = currentVehicle:GetClass()
                    if cls then
                        local n = cls:GetName()
                        if n and n ~= "" then vehName = n end
                    end
                end)
                local isSkipVeh = vehName:find("MTLB") or vehName:find("Motorglider") or vehName:find("VH_Fighter") or vehName:find("VH_Tank") or vehName:find("Leopard") or vehName:find("AmphibiousBoat") or vehName:find("Mecha")
                if not isSkipVeh then
                    local rootComp = currentVehicle.RootComponent or (type(currentVehicle.K2_GetRootComponent) == "function" and currentVehicle:K2_GetRootComponent())
                    local moveComp = currentVehicle.VehicleMovement or currentVehicle.MovementComponent
                    if Valid(moveComp) and type(moveComp.EnableSpecialAntiCheatSpeed) == "function" then
                        local lv = _G.MWState.CustomTextData.FastCarLevel or 50
                        local maxSpd = 2000 + lv * 40
                        pcall(function() moveComp:EnableSpecialAntiCheatSpeed(true, maxSpd) end)
                    end
                    if Valid(rootComp) and type(rootComp.SetAllPhysicsLinearVelocity) == "function" then
                        local isAccel = false
                        if Valid(moveComp) then
                            local throttle = moveComp.ThrottleInput or 0
                            if type(moveComp.GetThrottleInput) == "function" then throttle = moveComp:GetThrottleInput() end
                            if throttle > 0.05 or throttle < -0.05 then isAccel = true end
                        end
                        if currentVehicle.bIsPressingGas or (currentVehicle.Throttle and currentVehicle.Throttle ~= 0) then isAccel = true end

                        if isAccel then
                            local steer = 0
                            local forwardSpd = 0
                            if Valid(moveComp) then
                                pcall(function()
                                    steer = moveComp.SteeringInput or 0
                                    if type(moveComp.GetSteeringInput) == "function" then steer = moveComp:GetSteeringInput() end
                                end)
                                pcall(function()
                                    if type(moveComp.GetForwardSpeed) == "function" then forwardSpd = moveComp:GetForwardSpeed() end
                                end)
                            end

                            if math.abs(forwardSpd) > 50 then
                                local boostScale = math.max(0, 1 - math.abs(steer) * 2)
                                if boostScale > 0.01 then
                                    local currentVel = nil
                                    if type(currentVehicle.GetVelocity) == "function" then
                                        currentVel = currentVehicle:GetVelocity()
                                    elseif type(rootComp.GetPhysicsLinearVelocity) == "function" then
                                        currentVel = rootComp:GetPhysicsLinearVelocity()
                                    elseif rootComp.ComponentVelocity then
                                        currentVel = rootComp.ComponentVelocity
                                    end

                                    if currentVel then
                                        local speed = math.sqrt(currentVel.X^2 + currentVel.Y^2)
                                        if speed > 50 then
                                            local lv = _G.MWState.CustomTextData.FastCarLevel or 50
                                            local maxSpd = 2000 + lv * 40
                                            if speed < maxSpd then
                                                local newSpeed = math.min(maxSpd, speed + (20 + lv * 5) * boostScale)
                                                local dirX = currentVel.X / speed
                                                local dirY = currentVel.Y / speed
                                                rootComp:SetAllPhysicsLinearVelocity(FVector(dirX * newSpeed, dirY * newSpeed, currentVel.Z), false)
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end)
    end



    pcall(function()
        if not _G.MWConfig.VehicleInstantStop then
            if _G.__VehStopWasOn then
                local cv = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
                if Valid(cv) then
                    local rc = cv.RootComponent or (type(cv.K2_GetRootComponent) == "function" and cv:K2_GetRootComponent())
                    if Valid(rc) and type(rc.SetLinearDamping) == "function" then
                        rc:SetLinearDamping(0.01)
                    end
                end
                _G.__VehStopWasOn = false
            end
            return
        end
        local currentVehicle = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
        if not Valid(currentVehicle) then return end
        if _G.MWIsHeli(currentVehicle) then
            pcall(function()
                local heli = currentVehicle
                if type(heli.GetDriver) == "function" then
                    local drv = heli:GetDriver()
                    if not Valid(drv) or drv ~= localPlayer then return end
                end
                local hm = heli.HelicopterVehicleMovement
                local rc = heli.RootComponent or (type(heli.K2_GetRootComponent) == "function" and heli:K2_GetRootComponent())
                if not Valid(rc) or type(rc.SetAllPhysicsLinearVelocity) ~= "function" then return end
                local fIn, rIn, uIn = 0, 0, 0
                if Valid(hm) then
                    fIn = tonumber(hm.ForwardInputRate) or 0
                    rIn = tonumber(hm.RightInputRate) or 0
                    uIn = tonumber(hm.upInputRate) or 0
                end
                local lateral = (math.abs(fIn) > 0.05) or (math.abs(rIn) > 0.05) or heli.bIsPressingGas or (heli.Throttle and heli.Throttle ~= 0)
                local vertical = math.abs(uIn) > 0.05
                if lateral and vertical then return end
                local vel = nil
                pcall(function() vel = heli:GetVelocity() end)
                if not vel then return end
                local nx, ny, nz = vel.X, vel.Y, vel.Z
                if not lateral then nx, ny = 0, 0 end
                if not vertical then nz = 0 end
                if nx == vel.X and ny == vel.Y and nz == vel.Z then return end
                rc:SetAllPhysicsLinearVelocity(FVector(nx, ny, nz), false)
            end)
            return
        end
        if _G.MWIsAirVeh(currentVehicle) then return end
        local isDriver = true
        if type(currentVehicle.GetDriver) == "function" then
            local drv = currentVehicle:GetDriver()
            isDriver = Valid(drv) and drv == localPlayer
        end
        if (not isDriver) or (not _G.MWVehGrounded(currentVehicle)) then
            if _G.__VehStopWasOn then
                local rc0 = currentVehicle.RootComponent or (type(currentVehicle.K2_GetRootComponent) == "function" and currentVehicle:K2_GetRootComponent())
                if Valid(rc0) and type(rc0.SetLinearDamping) == "function" then rc0:SetLinearDamping(0.01) end
                _G.__VehStopWasOn = false
            end
            return
        end
        local rootComp = currentVehicle.RootComponent or (type(currentVehicle.K2_GetRootComponent) == "function" and currentVehicle:K2_GetRootComponent())
        if not Valid(rootComp) or type(rootComp.SetLinearDamping) ~= "function" then return end

        local isAccel = false
        local canRead = false
        local moveComp = currentVehicle.VehicleMovement or currentVehicle.MovementComponent
        if Valid(moveComp) then
            local throttle = nil
            pcall(function() throttle = moveComp.ThrottleInput end)
            if type(moveComp.GetThrottleInput) == "function" then pcall(function() throttle = moveComp:GetThrottleInput() end) end
            if type(throttle) == "number" then
                canRead = true
                if throttle > 0.05 or throttle < -0.05 then isAccel = true end
            end
        end
        if currentVehicle.bIsPressingGas or (currentVehicle.Throttle and currentVehicle.Throttle ~= 0) then isAccel = true end
        if not canRead then return end

        if isAccel then
            rootComp:SetLinearDamping(0.01)
        else
            rootComp:SetLinearDamping(100.0)
        end
        _G.__VehStopWasOn = true
    end)

