    pcall(function()
        local st = _G.MWState
        local jp = st._jp
        local want = false
        local firing = false
        if _G.MWConfig.JigglePeek and not localPlayer.bIsGunADS then
            firing = localPlayer.bIsWeaponFiring == true
            if not firing then pcall(function() firing = localPlayer:HasState(UEnums.EPawnState.GunFire) == true end) end
        end
        if _G.MWConfig.JigglePeek and (localPlayer.bIsGunADS or firing) then
            want = true
            pcall(function()
                local v = localPlayer.CurrentVehicle or (type(localPlayer.GetCurrentVehicle) == "function" and localPlayer:GetCurrentVehicle())
                if v and slua.isValid(v) then want = false end
                if type(localPlayer.IsNearDeath) == "function" and localPlayer:IsNearDeath() then want = false end
            end)
        end
        if not want then
            if jp and jp.active then
                pcall(function() localPlayer:TryPeek(jp.left, false) end)
                jp.active = false
            end
            if jp and jp.pose0 ~= nil then
                local p0 = jp.pose0
                jp.pose0 = nil
                if (p0 == ESTEPoseState.Stand or p0 == ESTEPoseState.Crouch) and localPlayer.PoseState ~= p0 then
                    pcall(function() localPlayer:SwitchPoseState(p0, true, false, false, true) end)
                end
            end
            return
        end
        local JP_PERIOD = 0.1
        local JP_POSE = 0.15
        local now = _G.RealNow()
        if not jp then jp = { left = true, next = 0, active = false }; st._jp = jp end
        if jp.pose0 == nil then jp.pose0 = localPlayer.PoseState end
        if now >= (jp.poseNext or 0) then
            jp.poseNext = now + JP_POSE
            local ps = localPlayer.PoseState
            if ps == ESTEPoseState.Stand or ps == ESTEPoseState.Crouch then
                local target = (ps == ESTEPoseState.Stand) and ESTEPoseState.Crouch or ESTEPoseState.Stand
                pcall(function() localPlayer:SwitchPoseState(target, true, false, false, true) end)
            end
        end
        if now < jp.next then return end
        jp.next = now + JP_PERIOD
        if jp.active then pcall(function() localPlayer:TryPeek(jp.left, false) end) end
        jp.left = not jp.left
        pcall(function() localPlayer:TryPeek(jp.left, true) end)
        jp.active = true
    end)






    _G._ApplyRainEffect = function(enabled)
        pcall(function()
            local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
            if not slua.isValid(pc) then return end
            local char = pc:GetPlayerCharacterSafety()
            if slua.isValid(char) and char.SetRainyEffectEnable then
                local EType = import("EScreenParticleEffectType")
                if EType then char:SetRainyEffectEnable(EType.ESPET_Rainy, enabled and true or false, enabled and 500 or 0) end
            end
            local ok2, SubMgr = pcall(require, "GameLua.GameCore.Module.Subsystem.SubsystemMgr")
            if ok2 and SubMgr then
                local ws = SubMgr:Get("CreativeModeWeatherSubsystem")
                if slua.isValid(ws) then
                    if enabled then pcall(function() ws:StartRainScreenEffect() end)
                    else pcall(function() ws:StopRainScreenEffect() end) end
                end
            end
        end)
    end

