    local function ApplySpeedHack(player)
        if not player.AttrModifyComp then return end
        if _G.MWState._speedHackChar ~= player then
            if _G.MWState._speedHackChar and slua.isValid(_G.MWState._speedHackChar) and _G.MWState._speedHackModifyId then
                pcall(function() _G.MWState._speedHackChar.AttrModifyComp:RemoveModifyItemFromCache(_G.MWState._speedHackModifyId) end)
            end
            _G.MWState._speedHackModifyId = nil
            _G.MWState._speedHackChar = player
            _G.MWState._speedHackLastRate = nil
        end
        local rate = (_G.MWState.CustomTextData and _G.MWState.CustomTextData.SpeedRunLevelV2) or 0.5
        local knocked = false
        pcall(function() knocked = player:IsNearDeath() == true end)
        if knocked then rate = 3.4 end
        if rate == _G.MWState._speedHackLastRate and _G.MWState._speedHackModifyId then
            return
        end
        if _G.MWState._speedHackModifyId then
            pcall(function() player.AttrModifyComp:RemoveModifyItemFromCache(_G.MWState._speedHackModifyId) end)
            _G.MWState._speedHackModifyId = nil
        end
        _G.MWState._speedHackModifyId = player.AttrModifyComp:AddModifyItemAndCache("SpeedRate", 0, rate, true, player, false)
        _G.MWState._speedHackLastRate = rate
    end

    local function RestoreSpeedHack(player)
        if slua.isValid(player) and player.AttrModifyComp then
            pcall(function() player.AttrModifyComp:RemoveModifyItemFromCache(_G.MWState._speedHackModifyId) end)
        end
        _G.MWState._speedHackModifyId = nil
        _G.MWState._speedHackChar = nil
        _G.MWState._speedHackLastRate = nil
    end

    pcall(function()
        if _G.MWConfig.SpeedRunV2 then
            SpeedHackButton.Show()
            if SpeedHackButton.IsHeld() then
                ApplySpeedHack(localPlayer)
            else
                if _G.MWState._speedHackModifyId then
                    RestoreSpeedHack(localPlayer)
                end
            end
        else
            if _G.MWState._speedHackModifyId then
                RestoreSpeedHack(localPlayer)
            end
            SpeedHackButton.Hide()
