                end)

                local eKey = GetSafeEnemyKey(enemy)
                _G.MWState.EnemyMarks[eKey] = _G.MWState.EnemyMarks[eKey] or { enemy = enemy }
                local markData = _G.MWState.EnemyMarks[eKey]
                markData.enemy = enemy 

