                    local isBotResult, isStateLoaded = CheckIsAI(enemy, markData)
                    local isBot = markData.AK_IS_BOT or false

                    local nowT = _G.RealNow()
                    if (not markData._ColorCheckT) or (nowT - markData._ColorCheckT) >= 0.2 or (markData._ColorCfg ~= _G.MWConfig.WallHackV2) then
                        markData._ColorCheckT = nowT
                        markData._ColorCfg = _G.MWConfig.WallHackV2
                        if _G.MWConfig.WallHackV2 then
                            ApplyColorBodyNew(enemy, markData)
                        else
                            UndoColorBodyNew(enemy, markData)
                        end
                    end

                    local currentHp, maxHp = 100, 100
                    local showFrameUI = (_G.MWConfig.EspPlayerBox and _G.UseNativeBox) and true or false
                    local doFrameUI = (not markData._FrameUIT) or (nowT - markData._FrameUIT) >= 0.1 or (markData._FrameUICfg ~= showFrameUI)
                    if doFrameUI then markData._FrameUIT = nowT; markData._FrameUICfg = showFrameUI end
                    
                    if showFrameUI and doFrameUI then
                        pcall(function()
                            if enemy.Health then currentHp = enemy.Health elseif type(enemy.GetHealth) == "function" then currentHp = enemy:GetHealth() end
                            if enemy.HealthMax then maxHp = enemy.HealthMax elseif type(enemy.GetHealthMax) == "function" then maxHp = enemy:GetHealthMax() end
                        end)
                        if maxHp <= 0 then maxHp = 100 end
                    end
                    local hpRatio = currentHp / maxHp

                    if showFrameUI and doFrameUI then
                        pcall(function()
                            local SecurityCommonUtils = Cached_SecurityCommonUtils
                            local show = true
                            if enemy.HealthStatus and SecurityCommonUtils and SecurityCommonUtils.IsHealthStatusAlive then 
                                if not SecurityCommonUtils.IsHealthStatusAlive(enemy.HealthStatus) then show = false end
                            end
                            if show and mLoc then
                                if aLoc and SecurityCommonUtils and SecurityCommonUtils.IsVector then
                                    if SecurityCommonUtils.IsVector(aLoc) and SecurityCommonUtils.IsVector(mLoc) then
                                        if aLoc.Z >= 150000 or FVector.Dist2D(mLoc, aLoc) > 50000 then show = false end
                                    end
                                end
                            end
                            if show then
                                if enemy.Replay_IsEnemyFrameUIExisted and not enemy:Replay_IsEnemyFrameUIExisted() then enemy:Replay_CreateEnemyFrameUI(true, true) end
                                if enemy.Replay_SetVisiableOfFrameUI then enemy:Replay_SetVisiableOfFrameUI(true) end
                                if enemy.Replay_UpdateEnemyFrameUI then enemy:Replay_UpdateEnemyFrameUI(hpRatio) end
                                
                                local uiComp = enemy.EnemyFrameUI or (type(enemy.GetEnemyFrameUI) == "function" and enemy:GetEnemyFrameUI())
                                if Valid(uiComp) then
                                    if markData.LastFrameUIState ~= "VISIBLE" then
                                        if type(uiComp.SetVisibility) == "function" then uiComp:SetVisibility(0) end
                                        if type(uiComp.SetHiddenInGame) == "function" then uiComp:SetHiddenInGame(false) end
                                        markData.LastFrameUIState = "VISIBLE"
                                    end
                                end
                            end
                        end)
                    elseif (not showFrameUI) and doFrameUI then
                        pcall(function()
                            if enemy.Replay_SetVisiableOfFrameUI then enemy:Replay_SetVisiableOfFrameUI(false) end
                            local uiComp = enemy.EnemyFrameUI or (type(enemy.GetEnemyFrameUI) == "function" and enemy:GetEnemyFrameUI())
                            if Valid(uiComp) then
                                if markData.LastFrameUIState ~= "HIDDEN" then
                                    if type(uiComp.SetVisibility) == "function" then uiComp:SetVisibility(2) end
                                    if type(uiComp.SetHiddenInGame) == "function" then uiComp:SetHiddenInGame(true) end
                                    markData.LastFrameUIState = "HIDDEN"
                                end
                            end
                        end)
                    end


                else
                    if not markData.IsCleanedUp then
                        if markData.MIDs then
                            for meshStr, midTable in pairs(markData.MIDs) do
                                for k, _ in pairs(midTable) do midTable[k] = nil end
                            end
                            markData.MIDs = nil
                        end
                        
                        if markData.MIDs_V3 then
                            for meshStr, midTable in pairs(markData.MIDs_V3) do
                                for k, _ in pairs(midTable) do midTable[k] = nil end
                            end
                            markData.MIDs_V3 = nil
                        end
                        
                        pcall(function()
                            local eObj = markData.enemy
                            if Valid(eObj) then 
                                if eObj.Replay_SetVisiableOfFrameUI then eObj:Replay_SetVisiableOfFrameUI(false) end
                                local uiComp = eObj.EnemyFrameUI or (type(eObj.GetEnemyFrameUI) == "function" and eObj:GetEnemyFrameUI())
                                if Valid(uiComp) then
                                    if type(uiComp.SetVisibility) == "function" then uiComp:SetVisibility(2) end 
                                    if type(uiComp.SetHiddenInGame) == "function" then uiComp:SetHiddenInGame(true) end
                                end
                            end
                            
                            local PPM = Cached_PPM
                            local avatarComp = Valid(eObj) and (type(eObj.getAvatarComponent2) == "function") and eObj:getAvatarComponent2() or nil
                            if Valid(avatarComp) and Valid(PPM) then PPM:EnableAvatarOutline(avatarComp, false) end
                        end)

                        markData.IsCleanedUp = true
                    end
                end
            end
        end

        if _G.MWConfig.EspVehicle then
            pcall(function()
                local MyHUD = Cached_MyHUD
                if Valid(MyHUD) then
                    if not _G.CachedGameplayStatics then _G.CachedGameplayStatics = import("GameplayStatics") end
                    if not _G.CachedActorClass_ForVehicle then _G.CachedActorClass_ForVehicle = import("STExtraVehicleBase") end 
                    if not _G.CachedVehicleArray then _G.CachedVehicleArray = slua.Array(UEnums.EPropertyClass.Object, _G.CachedActorClass_ForVehicle) end
                    
                    local ui_util = require("client.common.ui_util")
                    local gameInstance = ui_util and ui_util.GetGameInstance()
                    
                    if gameInstance and _G.CachedGameplayStatics then
                        local curTime = _G.RealNow()

                        if not _G.LastVehicleScanTime or (curTime - _G.LastVehicleScanTime) > 1.0 then
                            _G.LastVehicleScanTime = curTime
                            local allVehicles = _G.CachedGameplayStatics.GetAllActorsOfClass(gameInstance, _G.CachedActorClass_ForVehicle, _G.CachedVehicleArray)

                            local activeVehicles = {}
                            if allVehicles then
                                for _, veh in pairs(allVehicles) do
                                    if slua.isValid(veh) and not veh.bHidden and not veh.bTearOff then
                                        local isPendingKill = false
                                        pcall(function() if type(veh.IsPendingKill) == "function" then isPendingKill = veh:IsPendingKill() end end)
                                        local isDead = false
                                        pcall(function()
                                            if veh.VehicleHealthState and veh.VehicleHealthState >= 2 then isDead = true end
                                        end)

                                        if not isPendingKill and not isDead then
                                            local className = ""
                                            pcall(function()
                                                local cls = veh:GetClass()
                                                if cls then className = cls:GetName() or "" end
                                            end)
                                            if className == "" then className = tostring(veh) end

                                            local hasDriver = false
                                            local isMyVehicle = false
                                            pcall(function()
                                                local driver = type(veh.GetDriver) == "function" and veh:GetDriver() or nil
                                                if slua.isValid(driver) then
                                                    hasDriver = true
                                                    if driver == localPlayer then isMyVehicle = true end
                                                end
                                            end)
                                            if not isMyVehicle then
                                                pcall(function()
                                                    local mv = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
                                                    if slua.isValid(mv) and mv == veh then isMyVehicle = true end
                                                end)
                                            end
                                            if isMyVehicle then goto skip_vehicle end

                                            local displayName = nil
                                            local filterGroup = "heavy"
                                            local fn = className
                                            if string.find(fn, "UH60") then displayName = (_G.MWLang == "EN") and "UH60 HELICOPTER" or "UH60 HELICOPTER"; filterGroup = "heavy"; forceColor = {R=0, G=255, B=0, A=255}
                                            elseif string.find(fn, "AH6_Vehicle") then displayName = (_G.MWLang == "EN") and "HELICOPTER" or "HELICOPTER"; filterGroup = "heavy"; forceColor = {R=255, G=0, B=0, A=255}
                                            elseif string.find(fn, "Leopard") then displayName = "LEOPARD TANK"; filterGroup = "heavy"; forceColor = {R=0, G=255, B=0, A=255}
                                            elseif string.find(fn, "ArmedPickupFloat") then displayName = (_G.MWLang == "EN") and "ARMED PICKUP" or "ARMED PICKUP"; filterGroup = "heavy"; forceColor = {R=255, G=0, B=0, A=255}
                                            elseif string.find(fn, "ArmedDacia") then displayName = (_G.MWLang == "EN") and "ARMED DACIA" or "ARMED DACIA"; filterGroup = "heavy"; forceColor = {R=255, G=0, B=0, A=255}
                                            elseif string.find(fn, "ArmedBuggy") then displayName = (_G.MWLang == "EN") and "ARMED BUGGY" or "ARMED BUGGY"; filterGroup = "heavy"; forceColor = {R=255, G=0, B=0, A=255}
                                            elseif string.find(fn, "ArmedUAZ") then displayName = (_G.MWLang == "EN") and "ARMED UAZ" or "ARMED UAZ"; filterGroup = "heavy"; forceColor = {R=255, G=0, B=0, A=255}
                                            elseif string.find(fn, "_UTV_C") then displayName = "UTV"; filterGroup = "offroad"
                                            elseif string.find(fn, "_VH_Bigfoot_C") then displayName = "Monster Truck"; filterGroup = "offroad"
                                            elseif string.find(fn, "Buggy") then displayName = "Buggy"; filterGroup = "car"
                                            elseif string.find(fn, "UAZ") then displayName = "UAZ"; filterGroup = "car"
                                            elseif string.find(fn, "Dacia") then displayName = "Dacia"; filterGroup = "car"
                                            elseif string.find(fn, "Scooter") then displayName = "Scooter"; filterGroup = "moto"
                                            elseif string.find(fn, "Rony") then displayName = "Rony"; filterGroup = "car"
                                            elseif string.find(fn, "StoreBus") then displayName = "Store Bus"; filterGroup = "car"
                                            elseif string.find(fn, "LootTruck") then displayName = "Loot Truck"; filterGroup = "car"
                                            elseif string.find(fn, "MiniBus") then displayName = "Mini Bus"; filterGroup = "car"
                                            elseif string.find(fn, "Snowmobile") then displayName = "Snowmobile"; filterGroup = "offroad"
                                            elseif string.find(fn, "PG117") then displayName = "PG-117"; filterGroup = "boat"
                                            elseif string.find(fn, "_Motorcycle_") then displayName = "Motorcycle"; filterGroup = "moto"
                                            elseif string.find(fn, "_Snowbike_C") then displayName = "Snowbike"; filterGroup = "moto"
                                            elseif string.find(fn, "_Bike_") then displayName = (_G.MWLang == "EN") and "Bicycle" or "Bicycle"; filterGroup = "moto"
                                            elseif string.find(fn, "_MotorcycleCart_") then displayName = "Sidecar Motorcycle"; filterGroup = "moto"
                                            elseif string.find(fn, "_VH_Tuk_1") then displayName = "Tukshai"; filterGroup = "moto"
                                            elseif string.find(fn, "PickUp_0") then displayName = "Pickup"; filterGroup = "car"
                                            elseif string.find(fn, "BRDM") then displayName = "BRDM"; filterGroup = "heavy"; forceColor = {R=255, G=0, B=0, A=255}
                                            elseif string.find(fn, "AmphibiousBoat") then displayName = (_G.MWLang == "EN") and "MILITARY BOAT" or "MILITARY BOAT"; filterGroup = "heavy"; forceColor = {R=255, G=0, B=0, A=255}
                                            elseif string.find(fn, "AquaRail") then displayName = "Jet Ski"; filterGroup = "boat"
                                            elseif string.find(fn, "RubberBoat") then displayName = "Rubber Boat"; filterGroup = "boat"
                                            elseif string.find(fn, "VH_Tank_Beta_C") then displayName = "TANK"; filterGroup = "heavy"; forceColor = {R=0, G=255, B=0, A=255}
                                            elseif string.find(fn, "rado_open") then displayName = "Mirado (Open Top)"; filterGroup = "car"
                                            elseif string.find(fn, "rado_close") then displayName = "Mirado (Closed Top)"; filterGroup = "car"
                                            elseif string.find(fn, "Mirado") then displayName = "Mirado"; filterGroup = "car"
                                            elseif string.find(fn, "CoupeRB") then displayName = "Coupe RB"; filterGroup = "car"
                                            elseif string.find(fn, "Motorglider") then displayName = "Motor Glider"; filterGroup = "heavy"; forceColor = {R=255, G=0, B=0, A=255}
                                            elseif string.find(fn, "Roadster") then displayName = "Roadster"; filterGroup = "car"
                                            elseif string.find(fn, "ATV") then displayName = "Quad"; filterGroup = "offroad"
                                            elseif string.find(fn, "MTLB") then displayName = "MTLB"; filterGroup = "heavy"; forceColor = {R=255, G=0, B=0, A=255}
                                            elseif string.find(fn, "MechaVehicle") then displayName = "MECHA"; filterGroup = "heavy"; forceColor = {R=0, G=255, B=0, A=255}
                                            elseif string.find(fn, "VH_Fighter") then displayName = (_G.MWLang == "EN") and "FIGHTER JET" or "FIGHTER JET"; filterGroup = "heavy"; forceColor = {R=0, G=255, B=0, A=255}
                                            elseif string.find(fn, "VH_Horse") then displayName = (_G.MWLang == "EN") and "Horse" or "Horse"; filterGroup = "car"
                                            elseif string.find(fn, "UCAV") then displayName = "UCAV Drone"; filterGroup = "heavy"; forceColor = {R=0, G=255, B=0, A=255}
                                            end

                                            if not displayName then
                                                displayName = className
                                                filterGroup = "heavy"
                                                forceColor = {R=0, G=255, B=0, A=255}
                                            end
                                            local isSpecialWall = filterGroup == "heavy"
                                            local vehKind = nil
                                            if string.find(fn, "UH60") or string.find(fn, "AH6_Vehicle") then vehKind = "heli"
                                            elseif string.find(fn, "VH_Fighter") then vehKind = "jet"
                                            elseif string.find(fn, "Motorglider") or string.find(fn, "UCAV") then vehKind = "plane"
                                            elseif string.find(fn, "VH_Horse") then vehKind = "horse"
                                            elseif string.find(fn, "AmphibiousBoat") then vehKind = "mboat"
                                            elseif string.find(fn, "MechaVehicle") then vehKind = "robot"
                                            elseif string.find(fn, "VH_Tank") or string.find(fn, "Leopard") or string.find(fn, "MTLB") then vehKind = "tank"
                                            elseif string.find(fn, "Armed") then vehKind = "armed"
                                            elseif not (string.find(fn, "Leopard") or string.find(fn, "VH_Tank") or string.find(fn, "BRDM") or string.find(fn, "MTLB") or string.find(fn, "MechaVehicle")) then
                                                local okA, isA = pcall(function() return veh.IsArmedVehicle and veh:IsArmedVehicle() end)
                                                if okA and isA == true then vehKind = "armed" end
                                            end
                                            table.insert(activeVehicles, {act = veh, name = displayName, group = filterGroup, hasDriver = hasDriver, forceColor = forceColor, isSpecialWall = isSpecialWall or false, isHeli = (vehKind == "heli"), kind = vehKind})
                                            forceColor = nil
                                            ::skip_vehicle::
                                        end
                                    end
                                end
                            end
                            _G.CachedVehicles = activeVehicles

                        end

                        local realNowV = _G.RealNow()
                        if _G.CachedVehicles and (realNowV - (_G.LastVehicleDrawTime or 0)) >= 0.03 then
                            _G.LastVehicleDrawTime = realNowV
                            local vOff = _G._VehESP_TextOffset
                            if not vOff then vOff = {X=-40, Y=0, Z=150}; _G._VehESP_TextOffset = vOff end
                            for _, item in ipairs(_G.CachedVehicles) do
                                local veh = item.act
                                if slua.isValid(veh) and not veh.bHidden then
                                    local isShow = false
                                    local g = item.group
                                    if g == "car" then isShow = _G.MWConfig.EspVeh_Car
                                    elseif g == "moto" then isShow = _G.MWConfig.EspVeh_Moto
                                    elseif g == "offroad" then isShow = _G.MWConfig.EspVeh_Offroad
                                    elseif g == "boat" then isShow = _G.MWConfig.EspVeh_Boat
                                    else isShow = _G.MWConfig.EspVeh_Heavy end

                                    if isShow then
                                        local distM = 0
                                        pcall(function() distM = localPlayer:GetDistanceTo(veh) / 100 end)

                                        if distM > 0 then
                                            item.shown = true
                                            if item.isSpecialWall then
                                                if not _G.VehWallState then _G.VehWallState = {} end
                                                local vKey = tostring(veh)
                                                local wasOn = _G.VehWallState[vKey]
                                                local shouldWall = _G.MWConfig.EspVeh_WallHeavy and distM > 10
                                                if shouldWall and not wasOn then
                                                    pcall(function()
                                                        if not _G.ConsoleNewWallReady then
                                                            local KSL = import("KismetSystemLibrary")
                                                            local w = slua.getWorld()
                                                            if KSL and w then
                                                                KSL.ExecuteConsoleCommand(w, "r.EnableDrawDyeingColor 1")
                                                                KSL.ExecuteConsoleCommand(w, "r.CustomDepth 3")
                                                                KSL.ExecuteConsoleCommand(w, "r.IdeaOutline.Enable 1")
                                                                KSL.ExecuteConsoleCommand(w, "r.Highlight.Enable 1")
                                                                _G.ConsoleNewWallReady = true
                                                            end
                                                        end
                                                        local LC = import("LinearColor") or _G.FLinearColor
                                                        local visC = LC and LC(0, 22, 100, 100) or nil
                                                        local occC = LC and LC(100, 0, 0, 100) or nil
                                                        local vehMeshes = {}
                                                        pcall(function()
                                                            local skels = veh:GetComponentsByClass(import("SkeletalMeshComponent"))
                                                            if skels then for _, m in pairs(skels) do if slua.isValid(m) then table.insert(vehMeshes, m) end end end
                                                        end)
                                                        pcall(function()
                                                            local statics = veh:GetComponentsByClass(import("StaticMeshComponent"))
                                                            if statics then for _, m in pairs(statics) do if slua.isValid(m) then table.insert(vehMeshes, m) end end end
                                                        end)
                                                        for _, mesh in ipairs(vehMeshes) do
                                                            pcall(function()
                                                                if type(mesh.SetDrawDyeing) == "function" then
                                                                    mesh:SetDrawDyeing(true)
                                                                    mesh:SetDrawDyeingMode(1)
                                                                    mesh:SetVisibleDyeingColor(visC)
                                                                    mesh:SetOccludedDyeingColor(occC)
                                                                    mesh:SetDyeingColorFadeDistance(99999.0)
                                                                    mesh:SetDyeingColorMinMaxDistance(0.0, 99999.0)
                                                                    mesh:SetDrawHighlight(true)
                                                                    mesh:OverrideHighlightColor(visC)
                                                                    mesh:SetHighlightCanBeOccluded(false)
                                                                    mesh:SetDrawIdeaOutline(true)
                                                                    mesh:SetIdeaOutlineNew(true)
                                                                    mesh:SetIdeaOutlineOcclusionHighlight(true)
                                                                    mesh:OverrideIdeaOutlineColor(visC)
                                                                    mesh:SetIdeaOutlineOcclusionColor(occC)
                                                                    mesh:OverrideIdeaOutlineThickness(1.0)
                                                                    mesh:SetIdeaOverrideOutlineAndOcclusion(true)
                                                                    mesh:SetRenderCustomDepth(true)
                                                                    mesh:SetCustomDepthStencilValue(255)
                                                                end
                                                            end)
                                                        end
                                                        _G.VehWallState[vKey] = true
                                                    end)
                                                elseif not shouldWall and wasOn then
                                                    pcall(function()
                                                        local vehMeshes = {}
                                                        pcall(function()
                                                            local skels = veh:GetComponentsByClass(import("SkeletalMeshComponent"))
                                                            if skels then for _, m in pairs(skels) do if slua.isValid(m) then table.insert(vehMeshes, m) end end end
                                                        end)
                                                        pcall(function()
                                                            local statics = veh:GetComponentsByClass(import("StaticMeshComponent"))
                                                            if statics then for _, m in pairs(statics) do if slua.isValid(m) then table.insert(vehMeshes, m) end end end
                                                        end)
                                                        for _, mesh in ipairs(vehMeshes) do
                                                            pcall(function()
                                                                if type(mesh.SetDrawDyeing) == "function" then
                                                                    mesh:SetDrawDyeing(false)
                                                                    mesh:SetDrawHighlight(false)
                                                                    mesh:SetDrawIdeaOutline(false)
                                                                    mesh:SetRenderCustomDepth(false)
                                                                end
                                                            end)
                                                        end
                                                        _G.VehWallState[vKey] = false
                                                    end)
                                                end
                                            end

                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end)
        end

    end)
end


_G.MWState.LoopToken = (_G.MWState.LoopToken or 0) + 1
local myToken = _G.MWState.LoopToken

local function FastTick()
    if myToken ~= _G.MWState.LoopToken then return end
    pcall(MainLoop)
    local okTicker, ticker = pcall(require, "common.time_ticker")
    if okTicker and ticker and ticker.AddTimerOnce then
        ticker.AddTimerOnce(0.01, FastTick)
    end
end

FastTick()

local function InitAllModSystems()
    if isExpired then return end 

    pcall(function()
        if _G.StartBypass_VIP_v3 then _G.StartBypass_VIP_v3() end
    end)

    local GameplayData = package.loaded["GameLua.GameCore.Data.GameplayData"] or require("GameLua.GameCore.Data.GameplayData")
    if not GameplayData then return end

    pcall(function()
        local LocalPlayer = GameplayData.GetPlayerCharacter and GameplayData.GetPlayerCharacter()
        if slua.isValid(LocalPlayer) then
            if LocalPlayer.bHasShownDevNotice == nil then
                LocalPlayer.bHasShownDevNotice = false 
                LocalPlayer.bHasShownExpiredNotice = false 
                LocalPlayer.bIsDeadFlag = false
            end
        end
    end)
end

if not isExpired then
    pcall(function() 
        require("common.time_ticker").AddTimerOnce(0.5, InitAllModSystems) 
    end)
end

