        if dm.InitRoleData and not dm._ucInitRoleHooked then
            dm._ucInitRoleHooked = true
            local oldInit = dm.InitRoleData
            dm.InitRoleData = function(roleDataTb, ...)
                if oldInit then pcall(oldInit, roleDataTb, ...) end
                if _G.MWConfig and _G.MWConfig.UCSpend and _G._ApplyUCDisplay then pcall(_G._ApplyUCDisplay) end
            end
