                if _G.MWConfig and _G.MWConfig.UCSpend and _G._ApplyUCDisplay then pcall(_G._ApplyUCDisplay) end
            end
        end
        pcall(function()
            if not EventSystem then return end
            if EVENTTYPE_DATA_MGR then
                if EVENTID_DATAMGR_GOLD_CHANGE then EventSystem:postEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_GOLD_CHANGE, uc) end
